"use strict";
const DATA = [{"id": "s01", "section": 1, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 1 & 2", "title": "阅读理解", "lessons": "Lesson 1 & 2", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">This is a book. It is a red book. It is on the desk. Whose is it? Is this Tom's book? No, it isn't. Is it Jim's book? No, it isn't. Ah, I see. It's Helen's book. Her name is in this book.</p>\n<p class=\"source-line\">Jane: Excuse me, Helen! Is this your book?</p>\n<p class=\"source-line\">Helen: Yes, it is. Thank you.</p>\n<p class=\"source-line\">Jane: Not at all.</p>\n<p class=\"source-line\">根据短文内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What colour（什么颜色）is this book?</p>", "options": [], "answer": "It is red. || It's red.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">Where（哪儿）is this book?</p>", "options": [], "answer": "It is on the desk. || It's on the desk.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">Whose is this book?</p>", "options": [], "answer": "It is Helen's. || It's Helen's.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">Whose name is in the book?</p>", "options": [], "answer": "Helen's name.", "type": "input", "correct": null}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Ann: Excuse me.</p>\n<p class=\"source-line\">Lily: Yes?</p>\n<p class=\"source-line\">Ann: Is this your book?</p>\n<p class=\"source-line\">Lily: I beg your pardon.</p>\n<p class=\"source-line\">Ann: Is this your book?</p>\n<p class=\"source-line\">Lily: No, it's not mine. It is Lucy's.</p>\n<p class=\"source-line\">Ann: Could you take it to her?</p>\n<p class=\"source-line\">Lily: No problem.</p>\n<p class=\"source-line\">Ann: Thank you.</p>\n<p class=\"source-line\">Lily: That's all right.</p>\n<p class=\"source-line\">根据对话内容，判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Ann finds a coat.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">The book is Lily's.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Lily and Lucy know each other.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Ann will take the book to Lucy.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s02", "section": 2, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 3 & 4", "title": "阅读理解", "lessons": "Lesson 3 & 4", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">（G = Green; K = Knot）</p>\n<p class=\"source-line\">G: Hello!</p>\n<p class=\"source-line\">K: Good morning. Is that Mrs. Green?</p>\n<p class=\"source-line\">G: Yes. This is Mrs. Green. Is that Mr. Smith?</p>\n<p class=\"source-line\">K: No, I'm Knot.</p>\n<p class=\"source-line\">G: Is that Mr. Black?</p>\n<p class=\"source-line\">K: No, I'm Knot.</p>\n<p class=\"source-line\">G: What's your name?</p>\n<p class=\"source-line\">K: I'm Knot. K-N-O-T. Knot. Knot White.</p>\n<p class=\"source-line\">G: Sorry, sir.</p>\n<p class=\"source-line\">根据对话内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mrs. Green is Mr. Knot's friend.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">The man（男人）is Mr. Smith.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Mrs. Green doesn't know（不认识）Mr. Knot.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> Mother Is at Home</h4>\n<p class=\"source-line\">Little John is playing in front of a house. A man asks him, \"Hi, boy! Is your mother in?\" \"Yes!\" John answers. Then the man rings the doorbell. No one answers. The man asks John, \"Nobody is at home?\" \"Right!\" John answers, \"But this is not my house. It's Mr. Green's house. He is on holiday with his wife and son.\"</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">John is reading in front of a house.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">John's mother is at home.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">The man asks John, \"Is your mother in?\"</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">The house is Mr. Green's house.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s03", "section": 3, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 5 & 6", "title": "阅读理解", "lessons": "Lesson 5 & 6", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">This is Lu Ming. He is Chinese. He has a car. It is a Ford. The car is very big. Lu Ming likes his car very much. He washes it in the morning. He has a son and a daughter. This is his son. His name is David. He is a student. This is his daughter. Her name is Alice. She is not a student. She has a car, too. It is a Mini. It is an English toy car.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What nationality is Lu Ming?</p>", "options": ["Italian.", "Chinese.", "English.", "Japanese."], "answer": "B（Chinese.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">What make is Lu Ming's car?</p>", "options": ["Ford.", "Volvo.", "Mini.", "Daewoo."], "answer": "A（Ford.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Who is Lu Ming's son?</p>", "options": ["Ford.", "Alice.", "David.", "Mini."], "answer": "C（David.）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Whose car is a toy car?</p>", "options": ["Lu Ming's.", "Alice's.", "Mini's.", "David's."], "answer": "B（Alice's.）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Joan: Hello! Nice to meet you.</p>\n<p class=\"source-line\">Jim: Hello! Nice to meet you, too.</p>\n<p class=\"source-line\">Joan: I'm a new student. I am Joan.</p>\n<p class=\"source-line\">Jim: What's your last name?</p>\n<p class=\"source-line\">Joan: It's Brown. My name is Joan Brown.</p>\n<p class=\"source-line\">Jim: I'm Jim. I'm from England. Where are you from?</p>\n<p class=\"source-line\">Joan: I'm from America.</p>\n<p class=\"source-line\">Jim: And who's that little boy?</p>\n<p class=\"source-line\">Joan: He's my brother. His name is Mike.</p>\n<p class=\"source-line\">根据对话内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Joan is ____.</p>", "options": ["ten", "from England", "a new student", "Jim's brother"], "answer": "C（a new student）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mike is ____ brother.</p>", "options": ["Jim's", "Joan's", "my", "your"], "answer": "B（Joan's）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">What is \"last name\" in Chinese?</p>", "options": ["姓名", "姓氏", "名字", "号码"], "answer": "B（姓氏）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">How old is Mike?</p>", "options": ["Eight.", "Nine.", "Ten.", "We don't know."], "answer": "D（We don't know.）", "type": "mcq", "correct": 3}, {"number": 5, "questionHtml": "<p class=\"source-line\">Who is from England?</p>", "options": ["Joan.", "Mike.", "Jim.", "We don't know."], "answer": "C（Jim.）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s04", "section": 4, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 7 & 8", "title": "阅读理解", "lessons": "Lesson 7 & 8", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Catherine is a housewife. She is very nice. She is English. She works in the morning, but she plays in the afternoon. She has a parrot. Its name is Mini. It speaks English, too. It likes speaking English to Catherine. This is their dialogue.</p>\n<p class=\"source-line\">\"What's your job?\"</p>\n<p class=\"source-line\">\"I am a housewife.\"</p>\n<p class=\"source-line\">\"Are you a hairdresser?\"</p>\n<p class=\"source-line\">\"No, I'm not.\"</p>\n<p class=\"source-line\">\"But I need a hairdresser. She can tidy my hair.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What is Catherine's job?</p>", "options": ["An air hostess.", "A policewoman.", "A housewife.", "A mechanic."], "answer": "C（A housewife.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">What nationality is Catherine?</p>", "options": ["Japanese.", "Chinese.", "English.", "Italian."], "answer": "C（English.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">What is the parrot's name?</p>", "options": ["Mini.", "Kate.", "Judy.", "Alan."], "answer": "A（Mini.）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">The parrot needs a ____.</p>", "options": ["milkman", "housewife", "hairdresser", "postman"], "answer": "C（hairdresser）", "type": "mcq", "correct": 2}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Jim Green is an American boy. He's in China now. His father works in China. His father is a teacher. He teaches English. He teaches in a middle school. Jim's mother doesn't work. She is at home. Jim studies in a different middle school. He has some Chinese friends: Li Lei, Lin Tao and Meimei. Li Lei's father is a worker. He works in a factory. His mother is a Chinese teacher. She works in a middle school. Li Lei and his mother are in the same school. Lin Tao's father is a farmer. He works on a farm. His mother is a doctor. Meimei's father is a soldier. Her mother is a worker. She works in a shop.</p>\n<p class=\"source-line\">根据短文内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Where's Jim Green from?</p>", "options": [], "answer": "He is from America. || He's from America.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">What does Jim's father do?</p>", "options": [], "answer": "He is an English teacher. || He's an English teacher.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">Is Jim in the same school as his father?</p>", "options": [], "answer": "No, he is not. || No, he isn't.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">What does Li Lei's mother do?</p>", "options": [], "answer": "She is a Chinese teacher. || She's a Chinese teacher.", "type": "input", "correct": null}, {"number": 5, "questionHtml": "<p class=\"source-line\">What does Lin Tao's mother do?</p>", "options": [], "answer": "She is a doctor. || She's a doctor.", "type": "input", "correct": null}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s05", "section": 5, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 9 & 10", "title": "阅读理解", "lessons": "Lesson 9 & 10", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">（S = Sophie; H = Hans）</p>\n<p class=\"source-line\">H: Hello, Sophie. Nice to see you!</p>\n<p class=\"source-line\">S: Hi, Hans. Nice to see you, too!</p>\n<p class=\"source-line\">H: How are you today, Sophie?</p>\n<p class=\"source-line\">S: Very well, thanks. And you?</p>\n<p class=\"source-line\">H: I'm fine, too.</p>\n<p class=\"source-line\">S: Hans, who is that woman? She is new.</p>\n<p class=\"source-line\">H: That's right. That is Miss Stevenson, our English teacher.</p>\n<p class=\"source-line\">S: Really? Let's go and say hello to her.</p>\n<p class=\"source-line\">H: OK. Let's go.</p>\n<p class=\"source-line\">根据对话内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Sophie is very well.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">That woman is not new.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Miss Stevenson is Sophie and Hans's English teacher.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Look at this family photo of Ken. The old man is his grandfather. He is a teacher. The old woman is Ken's grandmother. She is a housewife. Who is that tall man? It's his father. His father is a policeman. Ken has a younger sister. Her name is Emma. She is ten, but she is tall. She has a white dog. Who is this young boy? Guess what? It's Ken. Ken is a student. He is twelve. His family are all fine.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Who is a teacher?</p>", "options": ["Ken's father.", "Ken's mother.", "Ken's grandfather.", "Ken's grandmother."], "answer": "C（Ken's grandfather.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">What is his father's job?</p>", "options": ["A nurse.", "A policeman.", "A milkman.", "A postman."], "answer": "B（A policeman.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">What does Emma look like（长什么样）?</p>", "options": ["Fat.", "Thin.", "Short.", "Tall."], "answer": "D（Tall.）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">How old（多大）is Ken?</p>", "options": ["Ten.", "Eleven.", "Twelve.", "Thirteen."], "answer": "C（Twelve.）", "type": "mcq", "correct": 2}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s06", "section": 6, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 11 & 12", "title": "阅读理解", "lessons": "Lesson 11 & 12", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Tom is a tall boy. He is very young, but he looks very old. He and Sam are in a shop today. Tom wants to buy a shirt. The blue shirt is nice. Tom likes it very much. He puts his white shirt in the cloakroom and tries on the blue one. \"Whose is this white shirt? Is it that man's?\" asks the salesgirl. \"That man? He is only twelve,\" answers Sam.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Tom is ____.</p>", "options": ["old", "tall", "short", "thin"], "answer": "B（tall）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Where are Tom and Sam?</p>", "options": ["In a shop.", "In a school.", "In a car.", "In a handbag."], "answer": "A（In a shop.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Tom likes the ____ shirt.</p>", "options": ["white", "blue", "red", "black"], "answer": "B（blue）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">How old（多大）is Tom?</p>", "options": ["10.", "11.", "12.", "13."], "answer": "C（12.）", "type": "mcq", "correct": 2}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Linda: Excuse me, Paul, is this your pencil?</p>\n<p class=\"source-line\">Paul: Yes, it is. Thank you.</p>\n<p class=\"source-line\">Linda: Is this your book?</p>\n<p class=\"source-line\">Paul: No, it isn't. Maybe it's Mary's.</p>\n<p class=\"source-line\">Linda: Mary, is this your book?</p>\n<p class=\"source-line\">Mary: No, it isn't. My book is here. Ask Bill. Maybe it's his.</p>\n<p class=\"source-line\">Linda: Bill, is this your book?</p>\n<p class=\"source-line\">Bill: Yes, it is.</p>\n<p class=\"source-line\">Linda: Here you are.</p>\n<p class=\"source-line\">Bill: Thank you very much. But where is my bag?</p>\n<p class=\"source-line\">根据对话内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">This is Linda's pencil.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Bill may be a student.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">The book is Bill's.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Mary can't find（找到）her book.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">Paul knows（知道）Linda and Mary.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s07", "section": 7, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 13 & 14", "title": "阅读理解", "lessons": "Lesson 13 & 14", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">The two girls are twins. The two girls have big blue eyes. They are seven. They are in the same class. The one in a brown skirt is Lily. The other one in a pink skirt is Lucy. Their father is Mr. Black. He is in a blue coat. Their mother is Mrs. Black. She is in white shoes. Ben is their brother. He is in a blue hat. He is a middle school student.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What colour are Lucy and Lily's eyes?</p>", "options": ["Black.", "Blue.", "White.", "Pink."], "answer": "B（Blue.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mr. Black and Mrs. Black have ____.</p>", "options": ["one son and two daughters", "two sons and one daughter", "one son and one daughter", "two sons and two daughters"], "answer": "A（one son and two daughters）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Mr. Black is ____.</p>", "options": ["in black shoes", "in a blue cap", "in a blue coat", "in a yellow sweater"], "answer": "C（in a blue coat）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">What colour are Mrs. Black's shoes?</p>", "options": ["White.", "Blue.", "Brown.", "Black."], "answer": "A（White.）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> Cats</h4>\n<p class=\"source-line\">Some cats are black. Some cats are white. Some cats are black and white. But no cats are green. I have a mother cat. She is black. She has two sons and one daughter. They are all black and white. The mother cat loves her sons and daughter, and she looks after them. And they love their mother very much.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The mother cat is ____.</p>", "options": ["black", "white", "black and white", "green"], "answer": "A（black）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Cats ____ green.</p>", "options": ["are", "are not", "love", "have"], "answer": "B（are not）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">I have ____.</p>", "options": ["two sons", "three daughters", "some cats", "two sons and one daughter"], "answer": "C（some cats）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">The sons and the daughter love ____ very much.</p>", "options": ["the mother cat", "my mother", "me", "their mother's cats"], "answer": "A（the mother cat）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">Who looks after the sons and the daughter?</p>", "options": ["The white mother cat.", "The green mother cat.", "The mother cat.", "No one."], "answer": "C（The mother cat.）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s08", "section": 8, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 15 & 16", "title": "阅读理解", "lessons": "Lesson 15 & 16", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Here is a lovely girl. Is my good friend Jane Russian? No, she is Dutch. She has long blond hair. She has two big eyes. Her nose is small and her mouth is small, too. Her blouse is white. Her skirt is blue and her shoes are black and white. Which girl is she? Guess! Yes, you are right. The one under the big tree.</p>\n<p class=\"source-line\">根据短文内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What nationality is Jane?</p>", "options": [], "answer": "She is Dutch. || She's Dutch.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">What colour is Jane's hair?</p>", "options": [], "answer": "Her hair is blond. || It's blond.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">What is blue?</p>", "options": [], "answer": "Jane's skirt.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">Which girl is Jane?</p>", "options": [], "answer": "The one under the big tree.", "type": "input", "correct": null}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Those girls are my good friends. Are they Swedish? No, they aren't. They are Norwegian. They come to China for a visit. They are showing their passports to the customs officer. I am going to take them to see a lot of places in China. They are friendly tourists. They say hello to Chinese people. I help them carry their cases. Those cases are very heavy, but I am happy to help them.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What nationality are those girls?</p>", "options": ["English.", "Chinese.", "Swedish.", "Norwegian."], "answer": "D（Norwegian.）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">Who can check（检查）their passports?</p>", "options": ["The teacher.", "The customs officer.", "The nurse.", "The milkman."], "answer": "B（The customs officer.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Those girls are very ____.</p>", "options": ["heavy", "friendly", "cold", "hot"], "answer": "B（friendly）", "type": "mcq", "correct": 1}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s09", "section": 9, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 17 & 18", "title": "阅读理解", "lessons": "Lesson 17 & 18", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Look! This is a photo of our classroom. The woman in a blue coat is our English teacher, Miss Zhao. She is a good teacher. The boy in a white shirt is Frank. He is thirteen. He is an English boy. He cannot speak Chinese at all. We have to help him with his Chinese. The girls are Lucy and Lily. They are both twelve years old. Their parents work in our school. They teach English. But they are not our English teachers. I like my class. I like my school.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Frank's English teacher is in a red coat.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Frank comes from England.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Lucy is twelve but Lily is not.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Lily's father is an English teacher.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Kate is a student. She has a big family. Her father's name is Smith. He works in a hospital. People think ①他是个很好的医生. Kate's mother is a teacher. She is a nice teacher. Kate has a brother and a sister. Now her brother is in China. He speaks Chinese very well and has many friends there. Her sister is also a student. She is studying Chinese very hard and ②she wants to be a teacher of Chinese in her country.</p>\n<p class=\"source-line\">根据短文内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Is Kate a student?</p>", "options": [], "answer": "Yes, she is.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mr. and Mrs. Smith have a son and ____ daughters.</p>", "options": [], "answer": "two", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">将文中①翻译成英语：</p>", "options": [], "answer": "He is a great doctor. || He's a great doctor.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">A doctor is a person who works in a ____.</p>", "options": [], "answer": "hospital", "type": "input", "correct": null}, {"number": 5, "questionHtml": "<p class=\"source-line\">将画线部分②译成中文。</p>", "options": [], "answer": "她想在她的国家做一名中文教师。", "type": "input", "correct": null}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s10", "section": 10, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 19 & 20", "title": "阅读理解", "lessons": "Lesson 19 & 20", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">It is very hot today. There is a woman under the tree. She is selling ice creams. She is busy. Many children are around her. They need ice creams.</p>\n<p class=\"source-line\">\"Three ice creams, please.\"</p>\n<p class=\"source-line\">\"Here you are, children.\"</p>\n<p class=\"source-line\">Those children are students. They study in a school nearby. Their school is small, but there are many students. The students like ice creams in summer very much. The woman under the tree is very happy every day. Her ice cream box is empty soon.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Where is the woman?</p>", "options": ["On the tree.", "In the tree.", "Under the tree.", "In the school."], "answer": "C（Under the tree.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Those children can get（得到）____ from the woman.</p>", "options": ["books", "ice creams", "pens", "dresses"], "answer": "B（ice creams）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Who are those children?</p>", "options": ["Teachers.", "Friends.", "Students.", "Boys."], "answer": "C（Students.）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">The woman is ____.</p>", "options": ["happy", "small", "old", "young"], "answer": "A（happy）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> A Clever Mother Crow</h4>\n<p class=\"source-line\">It's a hot day. A mother crow and her two kids are flying in the sky. They are very thirsty. So mother says to her children, \"Let's find some water to drink.\" They find a jar on the floor. There's some water in the jar. But it's not full. Their beaks are too short. They can't drink the water. Little crows don't know what to do. Mother crow looks at the jar, then she asks her children to put some stones into the jar. Oh, the jar is full now! The mother crow and her children can drink the water now. How clever the mother crow is!</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">It's a cold day.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">The crows are thirsty.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">The crows need some food to eat.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">The mother crow asks her children to put some oranges into the jar.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">The mother crow is very clever.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s11", "section": 11, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 21 & 22", "title": "阅读理解", "lessons": "Lesson 21 & 22", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">（A = Sam; B = Jane）</p>\n<p class=\"source-line\">A: Hi, Jane. Give me that book, please.</p>\n<p class=\"source-line\">B: Which book? The red one?</p>\n<p class=\"source-line\">A: No, not that one. The pink one.</p>\n<p class=\"source-line\">B: Here you are.</p>\n<p class=\"source-line\">A: Thanks. By the way, which class is Tom in?</p>\n<p class=\"source-line\">B: He is in Class Four.</p>\n<p class=\"source-line\">A: Is he your good friend?</p>\n<p class=\"source-line\">B: Yes, he is. We are not in the same class, but we are good friends.</p>\n<p class=\"source-line\">A: Is he good at English?</p>\n<p class=\"source-line\">B: Sure. He is from the USA.</p>\n<p class=\"source-line\">根据对话内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Which book does Sam want?</p>", "options": ["The red one.", "The blue one.", "The pink one.", "The brown one."], "answer": "C（The pink one.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Which class is Tom in?</p>", "options": ["Class 1.", "Class 2.", "Class 3.", "Class 4."], "answer": "D（Class 4.）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Where is Tom from?</p>", "options": ["England.", "Japan.", "China.", "America."], "answer": "D（America.）", "type": "mcq", "correct": 3}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Would you like to come with me to have a look at my classroom? Do you know which my seat is?</p>\n<p class=\"source-line\">This is Lily's seat. She sits in the second row. That's Lucy's seat. She is in front of Lily. Paul sits behind Lily. Li Lei sits on his right and Tom sits on his left. They are all in front of Jim. Jim sits next to me. We are the tallest two in my class. We sit in the last row.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Lucy sits in the ____ row.</p>", "options": ["first", "second", "last", "third"], "answer": "A（first）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Paul is on Li Lei's ____.</p>", "options": ["left", "last", "right", "front"], "answer": "A（left）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Tom is ____ than Jim.</p>", "options": ["fatter", "thinner", "shorter", "taller"], "answer": "C（shorter）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Who sits behind Tom?</p>", "options": ["No one.", "Li Lei.", "I.", "Paul."], "answer": "C（I.）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">My seat is in the ____ row.</p>", "options": ["first", "second", "third", "last"], "answer": "D（last）", "type": "mcq", "correct": 3}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s12", "section": 12, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 23 & 24", "title": "阅读理解", "lessons": "Lesson 23 & 24", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">（A = Alice; B = Bill; C = Cathy）</p>\n<p class=\"source-line\">A: Whose glass is that? Is it yours, Bill?</p>\n<p class=\"source-line\">B: No. It's not mine. Mine is here. I think it's Cathy's.</p>\n<p class=\"source-line\">A: Hi, Cathy.</p>\n<p class=\"source-line\">C: Yes?</p>\n<p class=\"source-line\">A: Is that your glass?</p>\n<p class=\"source-line\">C: Which glass?</p>\n<p class=\"source-line\">A: The one on the shelf.</p>\n<p class=\"source-line\">C: Oh, it's not mine. It's David's.</p>\n<p class=\"source-line\">A: Please give it to him.</p>\n<p class=\"source-line\">C: OK. I will.</p>\n<p class=\"source-line\">根据对话内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The glass on the shelf is Bill's.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">The glass on the shelf isn't Cathy's.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Cathy will give the glass to David.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Are you a student? Is your school beautiful? Our school is very beautiful. Now I introduce it to you. Our school lies in a peaceful and quiet place outside the city. It has a five-storey building for classrooms and school offices, a three-storey building for a library, a two-storey building for a laboratory, and a four-storey building for the students to live in.</p>\n<p class=\"source-line\">Our playground is very large. We do morning exercises there. Sometimes we have P.E. lessons there, too. We also play football and basketball after school.</p>\n<p class=\"source-line\">We have a school garden at the back of the playground. In the garden there are all kinds of trees and flowers. It's a real pleasure to study our lessons in the shade of the trees or to take a walk in the garden after supper.</p>\n<p class=\"source-line\">Our school is beautiful. We love it.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Where is the school?</p>", "options": ["It lies in a place in the city.", "It lies in a place in the middle of the city.", "It lies in a place outside the city.", "It lies in a noisy place."], "answer": "C（It lies in a place outside the city.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">How many buildings are there in the school?</p>", "options": ["Three.", "Four.", "Five.", "Two."], "answer": "B（Four.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Which building is the teaching building?</p>", "options": ["The five-storey building.", "The two-storey building.", "The three-storey building.", "The four-storey building."], "answer": "A（The five-storey building.）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Where is the garden?</p>", "options": ["In the middle of the school.", "Off the school.", "At the back of the playground.", "Behind the laboratory."], "answer": "C（At the back of the playground.）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">When do we like to walk in the garden?</p>", "options": ["In the morning.", "In the afternoon.", "After lunch.", "After supper."], "answer": "D（After supper.）", "type": "mcq", "correct": 3}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s13", "section": 13, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 25 & 26", "title": "阅读理解", "lessons": "Lesson 25 & 26", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">My name is Bob. I have a small room. It is clean. There is a desk, two chairs and a bed in the room. The door is here. The window is there. I have a radio. It's on the desk. There is a pencil box and some books on the desk, too. The chairs are near the desk. The bed is near the window. Under the bed there is a ball. There is a photo in my room. The photo is on the wall near the door. It is a photo of my family. There are five people in my family. It's a nice photo.</p>\n<p class=\"source-line\">In the evening, I study my lessons and do my homework in my room. I like my room.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Bob has a radio.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Bob's bed is near the desk.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">The photo is on the wall near the window.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">In Bob's family, there are five people.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">Bob likes his room.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> Where Is My Fish?</h4>\n<p class=\"source-line\">Smith likes fish very much. He buys some fish in the shop and takes it home one day. But when his wife sees the fish, she says to herself, \"Good! I can ask my friends to have lunch, and we can eat the fish. They like fish very much.\"</p>\n<p class=\"source-line\">So when Smith comes home in the evening, the fish is not there and his wife says, \"Oh, your cat eats it.\" And she gives Smith some bread for his supper. Smith is very angry. He takes the cat and his wife to the shop near his house and weighs the cat. Then he turns to his wife and says, \"My fish weighs one kilo. This cat weighs one, too. My cat is here, you see; then where is my fish?\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">____ eat the fish.</p>", "options": ["Mr. Smith", "Mrs. Smith", "The cat", "Mrs. Smith and her friends"], "answer": "D（Mrs. Smith and her friends）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">What does Mrs. Smith do with the fish?</p>", "options": ["She eats the fish before Smith comes back.", "She asks her friends to come to eat the fish with her.", "She puts the fish in the refrigerator and waits for her husband.", "She cooks the fish for her husband."], "answer": "B（She asks her friends to come to eat the fish with her.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Mr. Smith weighs ____ in the shop with his wife.</p>", "options": ["the fish", "the cat", "his wife", "his friend"], "answer": "B（the cat）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">How much fish does Smith buy?</p>", "options": ["One kilo.", "Two kilos.", "Three kilos.", "Four kilos."], "answer": "A（One kilo.）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">Smith likes ____ very much.</p>", "options": ["cats", "his wife", "fish", "his friends"], "answer": "C（fish）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s14", "section": 14, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 27 & 28", "title": "阅读理解", "lessons": "Lesson 27 & 28", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Lucy and Tom are in the same school. What's the name of the school? Let me see. Oh, it's No. 2 High School. In the school, you can see many big trees and beautiful flowers. And there are some teaching buildings in the centre of the school. The teachers' office building is next to the teaching buildings. The library is in front of the teachers' office building. The dining hall is between the library and the computer room. The playground is at the back of the school. You can see a hill behind the school. Many trees are on it, too. Oh, there is a river near the school. It's very clear. I think the school is very good.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">This is ____ High School.</p>", "options": ["No. 1", "No. 2", "No. 3", "No. 4"], "answer": "B（No. 2）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Where are the teaching buildings?</p>", "options": ["Behind the school.", "In front of the school.", "In the centre of the school.", "Next to the school."], "answer": "C（In the centre of the school.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Where is the dining hall?</p>", "options": ["In front of the teachers' office building.", "Between the library and the computer room.", "Behind the school.", "Near the school."], "answer": "B（Between the library and the computer room.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">The passage（文章）tells us about ____.</p>", "options": ["a house", "a library", "a school", "a river"], "answer": "C（a school）", "type": "mcq", "correct": 2}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">This is Lily and Lucy's bedroom. The walls are white and the windows are big. There is a picture of their family on the wall. The desk is near the window. There are some books and flowers on it. A clock is on it, too. There are two baseball bats under the bed. Lily's sweater is on her bed, but Lucy's sweater is behind her chair. Where are their hats? Are they on the sofa? Oh, no, they are on the floor. What's on the sofa? They are cats. They look like hats.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">This is ____.</p>", "options": ["Lucy's bedroom", "Lily's bedroom", "Lucy and Lily's bedroom"], "answer": "C（Lucy and Lily's bedroom）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">There are ____ on the desk.</p>", "options": ["books", "flowers and books", "flowers, books and a clock"], "answer": "C（flowers, books and a clock）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">The baseball bats are ____.</p>", "options": ["on the bed", "under the bed", "near the bed"], "answer": "B（under the bed）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">There are sweaters in the bedroom. One is on ____ bed, and the other is behind ____ chair.</p>", "options": ["Lily; Lucy", "Lucy's; Lily's", "Lily's; Lucy's"], "answer": "C（Lily's; Lucy's）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">____ are on the sofa.</p>", "options": ["Their hats", "Their cats", "Their hats and cats"], "answer": "B（Their cats）", "type": "mcq", "correct": 1}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s15", "section": 15, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 29 & 30", "title": "阅读理解", "lessons": "Lesson 29 & 30", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Dear Jack,</p>\n<p class=\"source-line\">I'm glad to get your letter. I know you want to know something about my life at home in your letter. Now let me tell you something about it.</p>\n<p class=\"source-line\">I must get up early every day. I must make my bedroom tidy. My mother asks me to open the window and air the room. Then I must make the bed and dust the dressing table. After lunch, I must wash the dishes. I can't watch television on weekdays. I must sweep the floor, too. I am very tired. How about you? Please write to me soon.</p>\n<p class=\"source-line\">Yours,<br>\nSally</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">This letter is from Sally to Jack.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Sally must get up late every day.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Sally's mother asks her to close the window.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Sally must do a lot of housework every day.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">One day, Mother looked at Henry's shoes and said, \"Henry, look at your shoes. They are dirty. You must clean them now.\" \"Oh, Mum, but I cleaned them only yesterday,\" said Henry. \"They are dirty now. You must clean them again,\" Mother said.</p>\n<p class=\"source-line\">\"If I clean them today, they'll be dirty again tomorrow,\" Henry said.</p>\n<p class=\"source-line\">Mother thought for a minute and said nothing. In the afternoon, Henry came back from school. He was very hungry. \"Mum,\" he said, \"Give me something to eat, please.\"</p>\n<p class=\"source-line\">\"But you had your breakfast in the morning, Henry, and you had lunch at school,\" Mother said.</p>\n<p class=\"source-line\">\"I'm hungry again!\" said Henry.</p>\n<p class=\"source-line\">\"Oh, hungry? If I give you something to eat today, you'll be hungry again tomorrow,\" said Mother with a smile.</p>\n<p class=\"source-line\">Henry's face turned red. He said nothing and began to clean his shoes.</p>\n<p class=\"source-line\">根据对话和短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Did Henry like cleaning his shoes?</p>", "options": ["Yes, he did.", "No, he didn't.", "We don't know."], "answer": "B（No, he didn't.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why did Henry's mother ask him to clean his shoes?</p>", "options": ["Because they were dirty.", "Because she had no time to do that.", "Because his mother wanted him to do some housework."], "answer": "A（Because they were dirty.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why didn't Henry want to clean his shoes?</p>", "options": ["Because he was very tired.", "Because he wanted his mother to do that.", "Because he thought his shoes would be dirty again even though he cleaned them."], "answer": "C（Because he thought his shoes would be dirty again even though he cleaned them.）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">What did he want to do when he came back from school?</p>", "options": ["He wanted to have breakfast.", "He wanted to have lunch.", "He wanted to eat something."], "answer": "C（He wanted to eat something.）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">Which of the following is TRUE?</p>", "options": ["Henry's face turned red because he was hungry.", "Henry did nothing when he heard his mother's words.", "Henry realized（意识到）his mistake and cleaned his shoes at last."], "answer": "C（Henry realized his mistake and cleaned his shoes at last.）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s16", "section": 16, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 31 & 32", "title": "阅读理解", "lessons": "Lesson 31 & 32", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Dear Tom,</p>\n<p class=\"source-line\">Thanks for your letter and the photos. Do you know? You look very cool in these photos. I like them very much. Here are some of my photos. In the first one, I'm swimming with my mother in the swimming pool. My mother is teaching me how to swim. I can swim now. I am very happy. In Picture 2, I am playing basketball with my classmates on the playground. You know basketball is my favourite sport. In Picture 3, you can see my family at home. We are having dinner. My little brother Sam and I are very happy. In the last picture, you can see my father and me at home. Look! He is watching television and I am doing my homework. I will hand it in tomorrow.</p>\n<p class=\"source-line\">Best wishes for you and your family. Please write to me soon.</p>\n<p class=\"source-line\">Yours,<br>\nJulie</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">This letter is from Tom to Julie.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Julie likes Tom's photos very much.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Julie can't swim now.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">In Picture 2, Julie is playing basketball.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">Julie's father is watching TV in the last picture.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">It's nine in the evening. It's time for Kate to go to bed. But her mother can't see her in the rooms.</p>\n<p class=\"source-line\">\"Where is your sister, Jim?\"</p>\n<p class=\"source-line\">\"She is behind the house,\" says the boy.</p>\n<p class=\"source-line\">\"What is she doing there?\"</p>\n<p class=\"source-line\">\"I don't know.\"</p>\n<p class=\"source-line\">\"Go and call her in. You must go to bed now, or you will be late for school tomorrow.\"</p>\n<p class=\"source-line\">Jim comes out and asks, \"What are you doing here, Kate?\"</p>\n<p class=\"source-line\">\"I am counting the stars, brother.\"</p>\n<p class=\"source-line\">\"It's very dark now,\" says Jim. \"Let's count them tomorrow morning.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Jim is Kate's ____.</p>", "options": ["friend", "brother", "teacher", "classmate"], "answer": "B（brother）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">When does the girl count the stars?</p>", "options": ["9:00 in the morning.", "9:00 in the evening.", "Tomorrow.", "Tomorrow morning."], "answer": "B（9:00 in the evening.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Mrs. Green wants her children to ____.</p>", "options": ["go to school", "stand in front of the house", "play in the rooms", "go to bed"], "answer": "D（go to bed）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">Where does Kate count the stars?</p>", "options": ["Behind the house.", "In the room.", "In front of the house.", "At school."], "answer": "A（Behind the house.）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s17", "section": 17, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 33 & 34", "title": "阅读理解", "lessons": "Lesson 33 & 34", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">（J = Jody; B = Blues）</p>\n<p class=\"source-line\">J: It's a fine day, isn't it?</p>\n<p class=\"source-line\">B: Sure, it is.</p>\n<p class=\"source-line\">J: Where is Mike, Blues?</p>\n<p class=\"source-line\">B: He is in the library.</p>\n<p class=\"source-line\">J: What is he doing?</p>\n<p class=\"source-line\">B: He is reading a book.</p>\n<p class=\"source-line\">J: Is Tim in the library, too?</p>\n<p class=\"source-line\">B: Yes, he is.</p>\n<p class=\"source-line\">J: What is Tim doing?</p>\n<p class=\"source-line\">B: He's reading newspapers.</p>\n<p class=\"source-line\">J: There is a cat in front of the library. What is it doing?</p>\n<p class=\"source-line\">B: It's playing with a doll.</p>\n<p class=\"source-line\">J: Is your father working in the school?</p>\n<p class=\"source-line\">B: No, he isn't. He is a doctor. He works in a hospital.</p>\n<p class=\"source-line\">根据对话内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Where is Mike?</p>", "options": [], "answer": "He is in the library. || He's in the library.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">What is Tim doing?</p>", "options": [], "answer": "He is reading newspapers. || He's reading newspapers.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">What is the cat doing?</p>", "options": [], "answer": "It is playing with a doll. || It's playing with a doll.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">Where does Blues's father work?</p>", "options": [], "answer": "He works in a hospital.", "type": "input", "correct": null}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">It is Sunday morning. It is a nice day. Mr. and Mrs. Liu take their daughter to the park. There are many people there. Some women are drinking tea under a big tree. Some children are playing games near a house. A girl is sitting in a boat. She is reading a book. There are many birds in the trees. They are singing, and some boys are playing football over there.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mr. and Mrs. Liu are in the park.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Some women are reading books.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Some boys are swimming in the river.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">A girl is reading in a boat.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">Some boys are playing football.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s18", "section": 18, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 35 & 36", "title": "阅读理解", "lessons": "Lesson 35 & 36", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mr. Wang is very old. His wife is not alive now, so he feels very lonely. He has only one friend. It is his dog. The dog is very lovely. It likes to walk with Mr. Wang in the park. Now Mr. Wang is walking in the park with his dog. The dog is running after a little bird, but it can't get the bird. Do you know why? The bird is flying. The dog is running. Look! The dog is jumping off the wall. It wants to catch the bird very much. Mr. Wang wants to go home. He asks his dog to stop running. Soon they come back home.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mr. Wang has a friend. It is a ____.</p>", "options": ["cat", "dog", "boy", "woman"], "answer": "B（dog）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">What is Mr. Wang doing now?</p>", "options": ["He is walking in the park with the dog.", "He is running after a bird.", "He is jumping off the wall.", "He is swimming in the river."], "answer": "A（He is walking in the park with the dog.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">What is the bird doing?</p>", "options": ["It's running.", "It's flying.", "It's sleeping.", "It's catching the dog."], "answer": "B（It's flying.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Can the dog catch the bird?</p>", "options": ["Yes, it can.", "Nobody knows.", "No, it can't.", "It can fly."], "answer": "C（No, it can't.）", "type": "mcq", "correct": 2}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">This is a photo. From the photo we can see Mr. Green's home in England. It is not in the city. It is in the country. It has a big garden. In the garden there is a big tree in front of their house. There are two small brown dogs and a small grey cat under the tree. There are two sheep under the tree, too. The man in the picture is Mr. Green. He is taking a walk with his wife, Jane. A little white dog is walking with them. The boy and the girl near their house are Jim and Kate. They are Mr. Green's son and daughter. They are playing with a football.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Where is Mr. Green's home?</p>", "options": ["In China.", "In the city.", "In the country.", "In America."], "answer": "C（In the country.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">There are ____.</p>", "options": ["two big trees in the garden", "two brown dogs, a cat and two sheep in the garden", "three people in Mr. Green's family", "a sheep in the garden"], "answer": "B（two brown dogs, a cat and two sheep in the garden）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">What are Mr. and Mrs. Green doing?</p>", "options": ["Walking with a dog.", "Playing with a ball.", "Working in the garden.", "Talking with a man."], "answer": "A（Walking with a dog.）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Jim and Kate are ____.</p>", "options": ["playing with a dog and a cat", "Mr. and Mrs. Green's children", "playing with a dog near their house", "at home"], "answer": "B（Mr. and Mrs. Green's children）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">How many kinds of animals are there in the family?</p>", "options": ["Four.", "Five.", "Three.", "Two."], "answer": "C（Three.）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s19", "section": 19, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 37 & 38", "title": "阅读理解", "lessons": "Lesson 37 & 38", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Bell always loves ships. He often says, \"I'm going to be a sailor. I'm going to make a small boat and go around the world.\" Boats are very expensive and Bell doesn't have enough money. What must he do? He has to drop his idea.</p>\n<p class=\"source-line\">Bell sees some people swimming in the swimming pool. Bell can't swim. But he wants to be a good swimmer now. Soon he becomes a good swimmer. His friend asks, \"How can you learn to swim so well?\" \"I'm not good at swimming at all. I swim in the water and see a lot of fish. I feel afraid and swim very fast.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What does Bell love?</p>", "options": ["Ships.", "Dogs.", "Cats.", "Toys."], "answer": "A（Ships.）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">A boat is very ____.</p>", "options": ["tall", "short", "cheap", "expensive"], "answer": "D（expensive）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">What does Bell see in the swimming pool?</p>", "options": ["Some boys are swimming.", "Some girls are swimming.", "Some people are swimming.", "Some people are jumping."], "answer": "C（Some people are swimming.）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Why does Bell swim fast?</p>", "options": ["His teacher asks him to swim fast.", "His parents tell him to swim fast.", "His friend asks him to swim fast.", "He feels afraid of the fish."], "answer": "D（He feels afraid of the fish.）", "type": "mcq", "correct": 3}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">It is the day of the big sale. A lot of people are waiting in a long line in front of the store.</p>\n<p class=\"source-line\">A small man is trying to go to the front of the line, but people push him back. On the man's second attempt（尝试）, people punch（拳打）him in the jaw and then throw him to the end of the line again.</p>\n<p class=\"source-line\">As he gets up, he says to the person at the end of the line, \"If they hit me one more time, I am not going to open the store!\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Who is this man?</p>", "options": ["A customer.", "A worker of the shop.", "We don't know."], "answer": "B（A worker of the shop.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why are there so many people in front of the shop?</p>", "options": ["Because they are waiting for the shop to open.", "Because they are waiting for the boss of the shop.", "Because they are watching something."], "answer": "A（Because they are waiting for the shop to open.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why can't the small man get to the door?</p>", "options": ["Because there are too many people.", "Because people don't let him go.", "Because he cannot walk."], "answer": "B（Because people don't let him go.）", "type": "mcq", "correct": 1}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s20", "section": 20, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 39 & 40", "title": "阅读理解", "lessons": "Lesson 39 & 40", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">（T = Tony; M = May）</p>\n<p class=\"source-line\">T: Be careful! What are you going to do with that pair of shoes?</p>\n<p class=\"source-line\">M: I am going to throw them away.</p>\n<p class=\"source-line\">T: It's a pair of running shoes. Don't you like sports now?</p>\n<p class=\"source-line\">M: Yes, I do. But now I have changed my favourite sport.</p>\n<p class=\"source-line\">T: What sport do you like best now?</p>\n<p class=\"source-line\">M: Swimming.</p>\n<p class=\"source-line\">T: Who is your favourite player?</p>\n<p class=\"source-line\">M: Sun Yang, a young man from China.</p>\n<p class=\"source-line\">T: I have heard of him. He is a great swimmer. He does well in swimming. I like him very much, too.</p>\n<p class=\"source-line\">M: Really? That's great.</p>\n<p class=\"source-line\">根据对话内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What is May going to do with that pair of shoes?</p>", "options": [], "answer": "She is going to throw them away. || She's going to throw them away.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">What sport does May like best?</p>", "options": [], "answer": "Swimming.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">Who is May's favourite player?</p>", "options": [], "answer": "Sun Yang.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">What is Sun Yang's job?</p>", "options": [], "answer": "He is a great swimmer. || He's a great swimmer.", "type": "input", "correct": null}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">A college（大学）student is proudly（自豪地）showing his new apartment（公寓）to his friends. He leads the way into the living room. There is a big gong（锣）and a hammer（锤子）. \"What is the big hammer for?\" one of his friends asks. \"That is the talking clock,\" the man replies（回答）. \"How does it work?\" \"Watch,\" the man says and gives the gong a big pound（重击）with the hammer. Suddenly, someone screams（尖叫）from the other side of the wall, \"Don't knock again, you idiot（白痴）! It's two o'clock in the morning!\"</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The student is showing his room to his friends.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">There is a talking clock in his house.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">The student pounds the gong with his fist.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">The neighbour is complaining about the noise.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s21", "section": 21, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 41 & 42", "title": "阅读理解", "lessons": "Lesson 41 & 42", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Jerry and Clair are twins. But they have different living habits. Now let's go to Jerry's room. Jerry cleans his bedroom every day and puts everything in the right place. There is a computer on the desk. There are two balls under the bed. A guitar and a kite are on the wall. Some books are on the shelf. So he must be a careful boy. Now let's go to Clair's room. The room is in a mess. Can you see his clothes on the desk? Oh, yes. Clair never does any cleaning on weekends, so his room is untidy.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What does Jerry do every day?</p>", "options": ["Eat an apple.", "Clean his bedroom.", "Sweep his study.", "Clean the classroom."], "answer": "B（Clean his bedroom.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Where is the computer?</p>", "options": ["Under the chair.", "On the chair.", "On the desk.", "Behind the door."], "answer": "C（On the desk.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">What's on the wall?</p>", "options": ["A map.", "A guitar.", "A kite.", "B & C."], "answer": "D（A guitar and a kite.）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">Why is Clair's room untidy?</p>", "options": ["He doesn't like his room.", "He never does any cleaning on weekends.", "He is a careful boy.", "He is hard-working."], "answer": "B（He never does any cleaning on weekends.）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">What is the sky? Where is it? How high is it? What lies above it? These questions are difficult to answer, aren't they?</p>\n<p class=\"source-line\">Is the sky blue? The sky has no colour. We know that there is air around the world. When planes fly, they need air to lift their wings. Planes cannot fly very high because when they go higher, the air gets thinner. If we go far enough away from the earth, we find there is no air at all.</p>\n<p class=\"source-line\">Perhaps we can answer some of our questions now. The sky is space. In this space there are only the sun, the moon and the stars.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What is the sky?</p>", "options": ["It's the clouds.", "It's space.", "It's air.", "It's nothing."], "answer": "B（It's space.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">The sky ____.</p>", "options": ["is blue", "is white", "is black", "has no colour"], "answer": "D（has no colour）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Planes cannot fly very high because ____.</p>", "options": ["the air becomes thinner", "the flying machine is not good", "people will be afraid if the planes fly too high", "there is no air"], "answer": "A（the air becomes thinner）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">If we go far enough away from the earth, we find ____.</p>", "options": ["there is more air", "there is less air", "there is nothing but air", "there is no air"], "answer": "D（there is no air）", "type": "mcq", "correct": 3}, {"number": 5, "questionHtml": "<p class=\"source-line\">In space there are ____.</p>", "options": ["nothing", "air everywhere", "everything", "only the sun, the moon and all the stars"], "answer": "D（only the sun, the moon and all the stars）", "type": "mcq", "correct": 3}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s22", "section": 22, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 43 & 44", "title": "阅读理解", "lessons": "Lesson 43 & 44", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Sam lived in the country. He loved playing in the river near his old house, but now his father has a job in a big city.</p>\n<p class=\"source-line\">Their new house has a garden, but the garden is very small. \"Is there a river near here?\" he asks his mother. \"No, there isn't. But there's a park near here. We are going to go there this afternoon.\"</p>\n<p class=\"source-line\">After lunch, Sam and his mother go to the park. Sam wants to walk near the pool, but there is a sign behind it. His mother reads it to him, \"Be careful! This pool is dangerous. 122 people have fallen into it.\" Sam looks into the pool carefully and says, \"But I can't see them.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">There is ____ near Sam's old house.</p>", "options": ["a tree", "a garden", "a river", "a park"], "answer": "C（a river）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">What is there near Sam's new house?</p>", "options": ["A shop.", "A river.", "A park.", "A parking lot."], "answer": "C（A park.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Which is NOT right?</p>", "options": ["Sam's father works in a big city now.", "Sam liked playing in the river.", "122 people have fallen into the pool.", "Sam gets into the pool and swims in it."], "answer": "D（Sam gets into the pool and swims in it.）", "type": "mcq", "correct": 3}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> A Clever Monkey</h4>\n<p class=\"source-line\">An old lion lives in the forest. He doesn't want to look for food. He wants other animals to give him something to eat.</p>\n<p class=\"source-line\">He sees a monkey and says to him, \"I'm hungry, monkey. Go and give me something to eat.\" \"Oh, lion,\" says the monkey, \"I can't do that now. There is another lion over there. He wants something to eat, too. He doesn't let me give any food to you. I'm afraid of him.\"</p>\n<p class=\"source-line\">\"What? Where is it? I must see him.\"</p>\n<p class=\"source-line\">\"Come with me,\" says the monkey.</p>\n<p class=\"source-line\">The monkey and the lion go to a bridge.</p>\n<p class=\"source-line\">\"Now, look down at the river. Do you see it?\"</p>\n<p class=\"source-line\">\"Yes, I do. I must eat him!\" With these words, the lion jumps into the river.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The lion looks for food himself.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">The lion tells the monkey to look for food for him.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">The monkey tells the lion that there is another lion in the forest.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">The monkey is not afraid of the lion.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">The lion falls into the river.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s23", "section": 23, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 45 & 46", "title": "阅读理解", "lessons": "Lesson 45 & 46", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Lucy and Lily are twins. They are eleven years old now. They often ask each other funny questions. Lucy asks Lily, \"Can you lift that cake, Lily?\" \"No, I can't. I can only eat that cake,\" answers Lily. \"I couldn't ride a bike three years ago, but I can ride it well now,\" says Lucy. \"I couldn't swim two years ago, but now I can,\" says Lily. I think they are very lovely. They always wear the same clothes. They eat the same food. But they like different things.</p>\n<p class=\"source-line\">根据短文内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">How old are Lucy and Lily?</p>", "options": [], "answer": "They are eleven years old. || They're eleven years old.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">What can Lucy ride now?</p>", "options": [], "answer": "She can ride a bike.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">What couldn't Lily do two years ago?</p>", "options": [], "answer": "She could not swim. || She couldn't swim.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">Do they like the same things or different things?</p>", "options": [], "answer": "They like different things.", "type": "input", "correct": null}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Ali wants to send a letter to his wife, but he can't read. He can't write, either. He has to work all day long, so he can only look for（寻找）somebody to write his letter at night. At last he finds a letter writer, Jonathan. It is very late and Jonathan is already in bed. \"What do you want?\" the writer asks. \"I want you to write a letter to my wife,\" Ali says. Jonathan is not pleased（高兴的）. He thinks for a while and says, \"My writing is strange. Only I can read it. If I have to travel a long way to read the letter to your wife, it will cost you a lot of money.\" On hearing this, Ali runs away at once（马上）.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What does Ali want?</p>", "options": ["He wants to look for a friend.", "He wants to write a letter to his wife.", "He wants to find a job.", "He wants to see his wife."], "answer": "B（He wants to write a letter to his wife.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Which of the following statements is TRUE about the writer?</p>", "options": ["He can't write a letter.", "He can't read a letter.", "He can't help Ali.", "He can't walk."], "answer": "C（He can't help Ali.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why does Ali run away?</p>", "options": ["Because his wife is not at home.", "Because Jonathan is angry.", "Because Jonathan can't write.", "Because Jonathan asks for a lot of money."], "answer": "D（Because Jonathan asks for a lot of money.）", "type": "mcq", "correct": 3}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s24", "section": 24, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 47 & 48", "title": "阅读理解", "lessons": "Lesson 47 & 48", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Brian is my good friend. He is a nice boy, but he eats too much and doesn't like sports. He has a big breakfast every morning. He has three eggs, a lot of bread and a big glass of coffee for breakfast. For lunch, he eats a lot of fried rice and chicken. He often eats fish, eggs and chicken for supper, too. Eating lots of food is not good for his health. Now he becomes fatter and fatter. He is worried about his health. Can you help him?</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Brian doesn't like ____.</p>", "options": ["breakfast", "sports", "coffee", "eggs"], "answer": "B（sports）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Brian doesn't eat ____ for supper.</p>", "options": ["fish", "chicken", "vegetables", "eggs"], "answer": "C（vegetables）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Brian is ____ now.</p>", "options": ["thinner and thinner", "taller and taller", "fatter and fatter", "stronger and stronger"], "answer": "C（fatter and fatter）", "type": "mcq", "correct": 2}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">One Sunday morning, Mr. Green and his child, Bill, are in a big shop. Mr. Green wants to buy a new blouse for Mrs. Green. Bill likes oranges, so his father buys two kilos of oranges for him. Bill also wants to buy some picture books and colour pencils. There are many people in the shop. They are men and women, old and young. They all want to buy something there.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mr. Green goes to the shop with ____.</p>", "options": ["Mrs. Green", "his son", "his daughter", "his father"], "answer": "B（his son）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mr. Green wants to buy a new blouse for ____.</p>", "options": ["Bill's mother", "Bill", "his friend", "other people"], "answer": "A（Bill's mother）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Bill likes ____.</p>", "options": ["all the things", "the new blouse", "oranges", "apples"], "answer": "C（oranges）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Bill wants to buy ____.</p>", "options": ["some picture books", "some colour pencils", "clothes in the shop", "A and B"], "answer": "D（some picture books and some colour pencils）", "type": "mcq", "correct": 3}, {"number": 5, "questionHtml": "<p class=\"source-line\">The shop is ____.</p>", "options": ["empty", "closed", "full of children", "full of people"], "answer": "D（full of people）", "type": "mcq", "correct": 3}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s25", "section": 25, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 49 & 50", "title": "阅读理解", "lessons": "Lesson 49 & 50", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mr. Black and his son, Tom, are in a supermarket. Mr. Black loves Tom and wants to buy some picture books for him. But Tom doesn't like picture books. He likes something to eat. So his father buys three kilos of apples for him. Tom also wants to buy a new jacket and some colour pencils. His father buys him some colour pencils. But Mr. Black can't buy the new jacket because he doesn't have much money with him. It makes him and Tom feel sad.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Tom and ____ are in the supermarket.</p>", "options": ["his father", "Mrs. Black", "his mother", "his brother"], "answer": "A（his father）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Tom would like to buy ____.</p>", "options": ["apples and colour pencils", "some picture books", "some pictures and some apples", "picture books and a jacket"], "answer": "A（apples and colour pencils）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Mr. Black doesn't buy ____ for his son.</p>", "options": ["apples", "colour pencils", "anything", "a new jacket"], "answer": "D（a new jacket）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">Mr. Black buys ____ kilos of apples.</p>", "options": ["two", "three", "four", "five"], "answer": "B（three）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">| Food | Who Likes It | Who Doesn't Like It |\n| --- | --- | --- |\n| Tomato | Barry | Jack |\n| Banana | Bill | June |\n| Hamburger | Lucy, Jack | April |\n| Ice cream | Peter, Bob | Barry |\n| Strawberry | Jane, June | Bill |</p>\n<p class=\"source-line\">根据表格内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">____ like(s) ice cream.</p>", "options": ["Peter", "Barry", "Bob", "A and C"], "answer": "D（Peter and Bob）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">Bill likes ____, but doesn't like ____.</p>", "options": ["tomatoes; strawberries", "bananas; strawberries", "bananas; ice cream", "tomatoes; ice cream"], "answer": "B（bananas; strawberries）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">____ like hamburgers.</p>", "options": ["Lucy and June", "Jane and Lucy", "Lucy and Jack", "April and Jack"], "answer": "C（Lucy and Jack）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">____ likes strawberries, but doesn't like bananas.</p>", "options": ["Barry", "Bill", "June", "Jane"], "answer": "C（June）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">In the table（表格）, we can see ____ names.</p>", "options": ["6", "7", "8", "9"], "answer": "D（9）", "type": "mcq", "correct": 3}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s26", "section": 26, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 51 & 52", "title": "阅读理解", "lessons": "Lesson 51 & 52", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">My home is in a village. It's very beautiful. The trees are green in spring and the water is very clear. There are four seasons in my hometown. They are spring, summer, fall and winter. Spring is usually very warm. It lasts from February to April. Everything begins to come out in spring. Summer is often very hot here. I like summer best because I can swim in the river. Autumn is always very cool. The colour of the leaves is yellow. Winter comes after fall. I don't like winter because it is very cold.</p>\n<p class=\"source-line\">These are the seasons of my hometown. How about yours? Could you please tell me about the seasons of your hometown?</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">When is summer in the writer's hometown?</p>", "options": ["From February to April.", "From May to July.", "From August to October.", "From November to January."], "answer": "B（From May to July.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why does the writer like summer best?</p>", "options": ["Because it is very hot.", "Because the writer can make snowmen.", "Because the writer can fly kites.", "Because the writer can go swimming in the river."], "answer": "D（Because the writer can go swimming in the river.）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">What colour are the tree leaves in fall?</p>", "options": ["Light green.", "Red.", "White.", "Yellow."], "answer": "D（Yellow.）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">What's the best title for the passage?</p>", "options": ["My Hometown", "Four Seasons of My Hometown", "My Favourite Season", "The Temperature of My Hometown"], "answer": "B（Four Seasons of My Hometown）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">In England, people don't often talk to each other when they travel. If you get on a bus or a train, you will sometimes see people sitting and looking out of the window. Other people will be reading books or newspapers.</p>\n<p class=\"source-line\">When you meet English people, they often start a conversation by talking about the weather. So when you meet somebody in England, you can say, \"Nice weather for the time of year!\"</p>\n<p class=\"source-line\">\"But it was a little cold yesterday,\" somebody may answer.</p>\n<p class=\"source-line\">\"But it will get a bit warmer later,\" you can say.</p>\n<p class=\"source-line\">Talk like this, and the English will think, \"How friendly you are!\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">English people often ____ on the bus.</p>", "options": ["talk a lot", "talk to each other", "eat something", "read newspapers"], "answer": "D（read newspapers）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">When you meet an English person, you can start the conversation by talking about the ____.</p>", "options": ["weather", "time", "food", "countryside"], "answer": "A（weather）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">According to the passage, if you talk to English people about the weather, they will think ____.</p>", "options": ["you are friendly", "you are right", "you are English", "you talk too much"], "answer": "A（you are friendly）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Some people sit and look out of the ____ on a train.</p>", "options": ["window", "door", "roof", "hole"], "answer": "A（window）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">Which sentence is TRUE?</p>", "options": ["English people like travelling by bus.", "English people don't talk much when they're on public transport.", "English people are unfriendly.", "English people don't enjoy good weather."], "answer": "B（English people don't talk much when they're on public transport.）", "type": "mcq", "correct": 1}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s27", "section": 27, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 53 & 54", "title": "阅读理解", "lessons": "Lesson 53 & 54", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">I come from a small city in the southwest of China. There are four seasons here in a year. They are spring, summer, autumn and winter. My favourite season is spring. In spring, everything comes back to life. Trees turn green and flowers come out. I like spring best because I can fly kites in spring. It is the best season for climbing hills, too. What about you? Which is your favourite season? Can you tell me something about it?</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">How many seasons are there in a year?</p>", "options": ["One.", "Two.", "Three.", "Four."], "answer": "D（Four.）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why does the writer like spring best?</p>", "options": ["The writer can fly kites.", "The writer can go swimming.", "The writer can go for a walk.", "The writer can play basketball."], "answer": "A（The writer can fly kites.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">What colour do trees turn in spring?</p>", "options": ["Yellow.", "Black.", "White.", "Green."], "answer": "D（Green.）", "type": "mcq", "correct": 3}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">In Britain, winter is not very cold and summer is not very hot. There is not a great difference between summer and winter. Why is this?</p>\n<p class=\"source-line\">Britain has a mild winter and a cool summer because it is an island country. In winter the sea is warmer than the land. The winds from the sea bring warm air to Britain.</p>\n<p class=\"source-line\">The west winds blow over Britain all year. They blow from the southwest. They are wet winds. They bring rain to Britain all year. Britain has a lot of rain all year. The east of Britain is drier than the west.</p>\n<p class=\"source-line\">The four seasons are all three months long. Winter is in December, January and February. Spring is in March, April and May. Summer is in June, July and August. Autumn is in September, October and November.</p>\n<p class=\"source-line\">根据短文内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What are winter and summer like in Britain?</p>", "options": [], "answer": "Winter is not very cold and summer is not very hot.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">Are summer and winter the same?</p>", "options": [], "answer": "No, they are not, but there is not a great difference between them. || No, they aren't, but there isn't a great difference between them.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">How long does spring last in Britain?</p>", "options": [], "answer": "Three months.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">When does summer come in Britain?</p>", "options": [], "answer": "In June.", "type": "input", "correct": null}, {"number": 5, "questionHtml": "<p class=\"source-line\">Is there a lot of rain all year in Britain?</p>", "options": [], "answer": "Yes, there is.", "type": "input", "correct": null}, {"number": 6, "questionHtml": "<p class=\"source-line\">How many seasons are there in Britain?</p>", "options": [], "answer": "Four.", "type": "input", "correct": null}], "questionCount": 6, "hasAnswers": true}]}, {"id": "s28", "section": 28, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 55 & 56", "title": "阅读理解", "lessons": "Lesson 55 & 56", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Hi, my name is Jackson. I am twelve years old. I'm a student at No. 1 Middle School. Do you want to know about my day? I usually get up at six forty-five. At seven ten I have my breakfast. And then I go to school by bus at seven thirty. Classes begin at seven forty. I have four classes in the morning.</p>\n<p class=\"source-line\">I often have lunch at about half past twelve. I have three classes in the afternoon. After school, I always play soccer with my classmates. At about five o'clock, I take a bus home again.</p>\n<p class=\"source-line\">I eat dinner at six thirty. After dinner I often do my homework and watch TV for about one hour. I often go to bed at half past ten.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">How does Jackson go to school every day?</p>", "options": ["By subway.", "By train.", "By bus.", "On foot."], "answer": "C（By bus.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">How many classes does Jackson have every day?</p>", "options": ["Two.", "Four.", "Six.", "Seven."], "answer": "D（Seven.）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Which of the following is TRUE?</p>", "options": ["Jackson studies at No. 2 Middle School.", "Jackson gets up at about seven ten.", "Jackson likes playing soccer after school.", "Jackson doesn't watch TV at all in the evening."], "answer": "C（Jackson likes playing soccer after school.）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Which is the best title for the passage?</p>", "options": ["Jackson's Day", "Jackson and His School", "Going to School by Bus", "Jackson's School"], "answer": "A（Jackson's Day）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">I'm not happy. There are too many rules in my family. I have to get up at 6:00 every morning. I can't meet my friends after school because I have to take my dog for a walk. I can't watch TV on school nights. And I have to be in bed by 10 o'clock from Monday to Friday. On weekends, I have to clean my room and wash my clothes. Then I have to help my mother make dinner. Later I have to go to the Children's Palace（少年宫）to learn the piano. I never have any fun.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">When does the writer get up every morning?</p>", "options": ["At 6:00.", "At 10 o'clock.", "At 11 o'clock.", "We don't know."], "answer": "A（At 6:00.）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why can't the writer play with his friends after school?</p>", "options": ["Because he has to do his homework.", "Because he has to walk the dog.", "Because he likes to watch TV.", "Because he has to make dinner."], "answer": "B（Because he has to walk the dog.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">What does the writer do on weekends?</p>", "options": ["Cleans his room.", "Makes dinner.", "Learns the piano.", "All of the above."], "answer": "D（All of the above.）", "type": "mcq", "correct": 3}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s29", "section": 29, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 57 & 58", "title": "阅读理解", "lessons": "Lesson 57 & 58", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">It is an unusual day today. It's nine o'clock in the morning. We're having an English class. The teacher sees a boy reading a storybook and says, \"Ben, what do you usually do after lunch?\"</p>\n<p class=\"source-line\">Ben gets up from his seat, but he doesn't know how to answer. He thinks for a while and then says, \"Wait for supper.\" The teacher isn't happy and, just at that moment, he sees another boy sleeping. The teacher is getting a little angry now, but he doesn't want to show it. Then he asks, \"And you, Jim?\"</p>\n<p class=\"source-line\">Jim's classmate wakes him up. He stands up and answers, \"Me, too.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What is Ben doing while the teacher is having an English class?</p>", "options": ["He is sleeping.", "He is reading a storybook.", "He is listening to music.", "He is reading English."], "answer": "B（He is reading a storybook.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">What does Ben usually do after lunch according to（按照）his answer?</p>", "options": ["He usually goes for a walk.", "He usually takes a break.", "He usually waits for supper.", "He usually plays basketball."], "answer": "C（He usually waits for supper.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">From the passage, we know ____.</p>", "options": ["Ben likes English very much", "Jack likes English a lot", "the teacher is very happy", "the teacher isn't happy"], "answer": "D（the teacher isn't happy）", "type": "mcq", "correct": 3}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Sandra usually gets up early in the morning. She usually has her breakfast at half past six. She leaves home half an hour later. She is never late for school.</p>\n<p class=\"source-line\">She has many classes in the morning. At a quarter past twelve, she comes back for lunch. In the afternoon she isn't so busy. After school she does her homework and plays with other kids.</p>\n<p class=\"source-line\">In the evening her parents come back from school. The family have dinner together. After that they usually read books or listen to music for a little while. Sometimes they watch TV. Sandra goes to bed at nine thirty. But her father often works late at night.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Sandra often goes to school at ____.</p>", "options": ["half past seven", "seven fifteen", "around six thirty", "around seven"], "answer": "D（around seven）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">Sandra's parents are ____.</p>", "options": ["doctors", "teachers", "actors", "runners"], "answer": "B（teachers）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Sandra does her homework ____.</p>", "options": ["after dinner", "in the evening", "after school", "after nine thirty"], "answer": "C（after school）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Sandra's father often ____ late.</p>", "options": ["comes home", "has supper", "goes to work", "goes to bed"], "answer": "D（goes to bed）", "type": "mcq", "correct": 3}, {"number": 5, "questionHtml": "<p class=\"source-line\">After dinner the family sometimes ____.</p>", "options": ["watch TV", "do their homework", "read newspapers", "play with other kids"], "answer": "A（watch TV）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s30", "section": 30, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 59 & 60", "title": "阅读理解", "lessons": "Lesson 59 & 60", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Jane is a forgetful girl. She often forgets what others tell her. Her mother asks her to go shopping and buy some school things. She comes to the stationery shop. \"I want some envelopes and pencils,\" says Jane. \"Is that all?\" asks the shop assistant. \"Oh, let me see. I'd like a large box of chalk, too.\" \"OK, here you are. Fifty dollars.\" Oh, my God! She doesn't have any money with her. Her mother gives her money and tells her to remember it. She has to go back home with nothing.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Jane has a good memory.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Jane's mother doesn't give her any money.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Those things are 50 dollars.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Jane goes home with school things.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> I Don't Have the Time</h4>\n<p class=\"source-line\">A driver stopped his car near the road to have a rest. When he wanted to sleep and closed his eyes, a tall man came up and knocked at his window to ask the time. The driver opened his eyes and looked at his watch. \"It's 8 a.m.,\" he said. Then he went to sleep again. But soon he woke up because a fat man was knocking at the window. \"Sir, do you have the time?\" he asked. The driver looked at his watch again and told the man it was 8:30.</p>\n<p class=\"source-line\">As he wanted to have a good rest, he wrote a short note on the window. It said, \"I don't have the time.\"</p>\n<p class=\"source-line\">Again the man began to sleep. A few minutes later a woman came up and began knocking at the window. \"Hey, sir,\" she said, \"It's a quarter to nine.\"</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">A driver stopped his car to buy something.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">A tall man came up and asked him the time.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">When he went to sleep again, a fat woman woke him up.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">The third time（第三次）, a woman came and asked the time.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">The driver didn't sleep at all.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s31", "section": 31, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 61 & 62", "title": "阅读理解", "lessons": "Lesson 61 & 62", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">In the USA, the flu kills 20,000 people every year. Most of them are children or old people. When it happens to you, you will feel weak, have a high fever and cough often.</p>\n<p class=\"source-line\">For most people, the treatment is just to wait it out: stay at home and have a good rest, drink lots of boiled water and take some pills, e.g. aspirin. It usually goes away about two weeks later. For the old and young, it's much harder to treat because they are too weak to fight against the flu.</p>\n<p class=\"source-line\">Flu season in the USA is usually from December to March. So you'd better stay away from infected people. But the best way is to do more exercise and keep healthy.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The flu kills about ____ people every month in America.</p>", "options": ["1,667", "2,000", "15,000", "20,000"], "answer": "A（1,667）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Which of the following is NOT a symptom of flu?</p>", "options": ["You feel weak.", "You have a high fever.", "You often cough.", "You want to eat food."], "answer": "D（You want to eat food.）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Which is NOT true about the treatment of the flu?</p>", "options": ["Staying in bed to have a good rest.", "Drinking more cold water.", "Taking some medicine like aspirin and painkillers.", "Drinking plenty of hot water."], "answer": "B（Drinking more cold water.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">What can we learn from the last paragraph?</p>", "options": ["The flu can't kill people in the USA.", "The flu doesn't happen in winter in the USA.", "The flu isn't contagious（传染的）among people.", "It's not easy for strong people to catch the flu."], "answer": "D（It's not easy for strong people to catch the flu.）", "type": "mcq", "correct": 3}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Peter is a junior high school student. He was sick yesterday. He went to see the doctor. The doctor told him to take some medicine. Before taking the medicine, it's important to read the directions carefully.</p>\n<p class=\"source-line\">Directions on the Medicine:</p>\n<p class=\"source-line\">1. Patients under 17 years old take the medicine every 6 hours.\n2. Grown-ups take the medicine every 4 hours.\n3. Don't take it before meals.\n4. Don't take it with tea or coffee.\n5. Don't take it for more than 6 days successively.\n6. Don't take it after September 10, 2008.\n7. Keep the medicine away from young children.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">How often should grown-ups take the medicine?</p>", "options": ["Every 2 hours.", "Every 3 hours.", "Every 4 hours.", "Every 6 hours."], "answer": "C（Every 4 hours.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Peter hates taking medicine, but he likes coffee. What can he take the medicine with?</p>", "options": ["Tea.", "Coffee.", "Water.", "Rice."], "answer": "C（Water.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Peter took the medicine at 7:00 this morning. What time should he take the medicine next?</p>", "options": ["11:00 a.m.", "1:00 p.m.", "12:00 p.m.", "3:00 p.m."], "answer": "B（1:00 p.m.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Where should grown-ups put the medicine?</p>", "options": ["On a high shelf.", "On a red table.", "In a big living room.", "Near a beautiful garden."], "answer": "A（On a high shelf.）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s32", "section": 32, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 63 & 64", "title": "阅读理解", "lessons": "Lesson 63 & 64", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">（L = Lily; D = David）</p>\n<p class=\"source-line\">D: Lily, do you know how to keep healthy?</p>\n<p class=\"source-line\">L: Yes. It's easy.</p>\n<p class=\"source-line\">D: So what must I do to keep fit?</p>\n<p class=\"source-line\">L: First, you must eat more healthy food.</p>\n<p class=\"source-line\">D: Is smoking good or bad for my health?</p>\n<p class=\"source-line\">L: Of course it's bad for your health.</p>\n<p class=\"source-line\">D: So what else must I remember?</p>\n<p class=\"source-line\">L: You'd better drink more boiled water every day.</p>\n<p class=\"source-line\">D: Is that all?</p>\n<p class=\"source-line\">L: No, one more thing: you should go to bed early and have a good rest.</p>\n<p class=\"source-line\">D: Thank you, Lily.</p>\n<p class=\"source-line\">L: You're welcome!</p>\n<p class=\"source-line\">根据对话内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Does Lily know how to keep healthy?</p>", "options": [], "answer": "Yes, she does.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">What must we eat to keep healthy?</p>", "options": [], "answer": "More healthy food.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">What must we drink every day?</p>", "options": [], "answer": "More boiled water.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">What must we do to keep healthy?</p>", "options": [], "answer": "（1）Eat healthy food.<br>（2）Drink more water.<br>（3）Go to bed early and have a good rest.<br>（4）Do not smoke. || （1）Eat healthy food.<br>（2）Drink more water.<br>（3）Go to bed early and have a good rest.<br>（4）Don't smoke.", "type": "input", "correct": null}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Old John went to see a doctor. The doctor examined him and said, \"Medicine can't help you. You must have a good rest. Go to a quiet place for a month, go to bed early, drink some milk, walk a lot and smoke one cigar a day.\"</p>\n<p class=\"source-line\">\"Thank you very much,\" said Old John. \"I will do everything you say.\"</p>\n<p class=\"source-line\">A month later Old John came to the doctor again. \"Well,\" said the doctor, \"I'm glad to see you. You look much younger.\"</p>\n<p class=\"source-line\">\"Oh, doctor,\" said Old John, \"I feel quite well now. I had a good rest. I went to bed early, I drank a lot of milk, and I walked a lot. Your advice certainly helped me. But you asked me to smoke one cigar a day, and that nearly killed me at first. It's no joke to start smoking at my age.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The doctor ____.</p>", "options": ["asked him to take some medicine", "asked him not to take any medicine", "didn't say anything about medicine", "gave him some medicine"], "answer": "B（asked him not to take any medicine）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Old John ____ after a month.</p>", "options": ["didn't get well", "got well", "was young", "was old"], "answer": "B（got well）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Which one is TRUE?</p>", "options": ["Old John didn't smoke before.", "Old John smoked before.", "Old John didn't smoke a cigar a day.", "Old John wanted to smoke."], "answer": "A（Old John didn't smoke before.）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">When Old John was ill, he looked ____.</p>", "options": ["young", "old", "younger", "older"], "answer": "D（older）", "type": "mcq", "correct": 3}, {"number": 5, "questionHtml": "<p class=\"source-line\">The best title of this passage should be ____.</p>", "options": ["Old John", "Old John Is Ill", "The Doctor's Advice", "Old John Did as the Doctor Asked Him"], "answer": "C（The Doctor's Advice）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s33", "section": 33, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 65 & 66", "title": "阅读理解", "lessons": "Lesson 65 & 66", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Two children are playing on the beach. They are enjoying themselves. They are both five years old. Their parents are not with them because they are swimming in the sea now. The boy says to the girl, \"Am I a good young boy, Laura?\" \"Sure, you are,\" answers Laura. \"Can I have the key to your front door? I can visit you easily.\" \"I must ask my dad first. Maybe he doesn't allow it,\" answers Laura. \"You know, you are five years old. We are not two- or three-year-old babies any longer. We can decide some things ourselves,\" says the boy.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What are the two children doing?</p>", "options": ["They are sleeping.", "They are walking.", "They are playing.", "They are running."], "answer": "C（They are playing.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">How old is Laura?</p>", "options": ["Two.", "Three.", "Five.", "Fifteen."], "answer": "C（Five.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">What does the boy ask the girl to give him?</p>", "options": ["The key to the back door.", "The key to the front door.", "The key to the car.", "The key to the bookcase."], "answer": "B（The key to the front door.）", "type": "mcq", "correct": 1}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">I go home after work. I am on a bus on a rainy day. A woman with a dog gets on the bus. It is a big dog and its feet are not clean. I don't want the dog to sit next to me. But the woman says to the conductor, \"Oh, I bought a ticket for my dog. Can he sit here like the other people?\" The conductor looks at the dog and says, \"Yes, but like the other people, he must not put his feet on the chair.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">I'm going home ____ now.</p>", "options": ["by bike", "by bus", "by car", "by jeep"], "answer": "B（by bus）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">What do I see on the bus?</p>", "options": ["A bus.", "A doctor.", "A dog.", "A woman with a big dog."], "answer": "D（A woman with a big dog.）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">I don't want the dog to sit next to me because ____.</p>", "options": ["the dog is big", "the dog's feet are not clean", "the dog is old", "the dog isn't mine"], "answer": "B（the dog's feet are not clean）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Why do the woman and the dog get on the bus?</p>", "options": ["It's a rainy day.", "No one is on the bus.", "The dog can sit.", "The woman is a conductor."], "answer": "A（It's a rainy day.）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">The meaning of the conductor's words is ____.</p>", "options": ["the dog's feet are like the other people's", "the dog must like a man", "the dog must not sit on the chair", "the dog can sit on the chair"], "answer": "C（the dog must not sit on the chair）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s34", "section": 34, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 67 & 68", "title": "阅读理解", "lessons": "Lesson 67 & 68", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mona was ill yesterday. She had to stay in hospital. She was worried about her lessons. She telephoned her class teacher to ask for leave. Her class teacher told her not to worry about anything. She should have a good rest in the hospital.</p>\n<p class=\"source-line\">Mona's classmates decided to visit her. They went to buy a box of milk in the dairy and some apples in a fruit shop. Mona was very excited to see them. Lucy gave Mona an MP3 player and told her to review her lessons with it. Lily promised to help her with her lessons after she came back to school.</p>\n<p class=\"source-line\">Mona was very glad to have such good classmates. She felt much better soon.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What was wrong with Mona yesterday?</p>", "options": ["She was unhappy.", "She was ill.", "Her mother was ill.", "Her dog was ill."], "answer": "B（She was ill.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Who did Mona telephone?</p>", "options": ["Her father.", "Her brother.", "Her class teacher.", "Her sister."], "answer": "C（Her class teacher.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Where did Mona's classmates buy the milk?</p>", "options": ["In a fruit shop.", "In a dairy.", "At school.", "At home."], "answer": "B（In a dairy.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Who would help Mona with her lessons?</p>", "options": ["Lucy.", "Lily.", "Her English teacher.", "Her class teacher."], "answer": "B（Lily.）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mr. and Mrs. Green lived in a big city, and one summer they went to the country for their holiday. They enjoyed it very much because it was a quiet, clean place.</p>\n<p class=\"source-line\">One day, they went for a walk early in the morning and met an old man. He lived on a farm and he was sitting in the warm sun in front of his house. Mr. Green asked him, \"Do you like to live in this quiet place?\"</p>\n<p class=\"source-line\">\"Yes, I do,\" the old man said.</p>\n<p class=\"source-line\">\"What are the good things about it?\" Mr. Green asked.</p>\n<p class=\"source-line\">The old man answered, \"Well, the people here know each other. They often come and visit me, and I often go and visit them. And I can see lots of children here.\"</p>\n<p class=\"source-line\">\"That's interesting. And what are the bad things?\" Mr. Green asked.</p>\n<p class=\"source-line\">The old man thought for a moment and then said, \"Well, the same things, really.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mr. and Mrs. Green went to the country ____.</p>", "options": ["to see the old man", "to spend their holiday", "to see the quiet place", "to see their friends"], "answer": "B（to spend their holiday）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mr. and Mrs. Green enjoyed the country because ____.</p>", "options": ["it was far from the city", "it was a farm", "it wasn't far", "it was quiet and clean"], "answer": "D（it was quiet and clean）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Mr. and Mrs. Green took a walk ____.</p>", "options": ["early in the morning", "after breakfast", "in the evening", "after lunch"], "answer": "A（early in the morning）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">The old man said, \"Yes, I do.\" \"I do\" here means ____.</p>", "options": ["I like to live in this quiet place.", "I like to sit in the warm sun.", "I like to go out for a walk early in the morning.", "I like to live in the city."], "answer": "A（I like to live in this quiet place.）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">Did the old man think the good things were the same as the bad things?</p>", "options": ["Yes, he did.", "No, he didn't.", "We don't know.", "Sometimes he did, but sometimes he didn't."], "answer": "A（Yes, he did.）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s35", "section": 35, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 69 & 70", "title": "阅读理解", "lessons": "Lesson 69 & 70", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">It was a report about the University of Oxford. It was the oldest university in the English-speaking world and one of the top universities in the world. There was no clear date when the university started, but it began teaching in about 1096.</p>\n<p class=\"source-line\">There were 38 independent colleges at Oxford. There were over 100 libraries for the students and learned people to use. At the University of Oxford, they also award a large amount of money to the best students.</p>\n<p class=\"source-line\">College life at Oxford was very exciting but also very busy. The colleges were strict with students about their studies. Many Chinese students were studying there. The number of Chinese students at the university had grown quickly over the past 10 years.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">How many libraries were there at Oxford?</p>", "options": ["39.", "1096.", "More than 100.", "Over 10."], "answer": "C（More than 100.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">College life at Oxford was ____.</p>", "options": ["exciting but busy", "exciting but free", "boring and busy", "hard and sad"], "answer": "A（exciting but busy）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Which is right?</p>", "options": ["The colleges weren't strict with students.", "The University of Oxford was very young.", "The University of Oxford was a famous university.", "Every Chinese person could go to the University of Oxford."], "answer": "C（The University of Oxford was a famous university.）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">What's the best title for the passage?</p>", "options": ["College Life", "The Famous Buildings at Oxford", "Peking University", "The University of Oxford"], "answer": "D（The University of Oxford）", "type": "mcq", "correct": 3}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> Buy a Ball for You!</h4>\n<p class=\"source-line\">Mark likes sports. He's tall and strong in his middle school. Now his father and mother work in London. So he begins to study in a middle school there. He's a member of the school football team. He likes football very much and plays it on Saturday and Sunday.</p>\n<p class=\"source-line\">His grandma lives in a small town. One day she comes to see him. It's Saturday and she doesn't see the boy at home. So she goes to look for him in the school. She sees many boys running after only one ball. The old woman tells Mark to go home with her.</p>\n<p class=\"source-line\">\"But, Grandma, I...\"</p>\n<p class=\"source-line\">\"Don't play with them, my dear!\" says the old woman. \"I'm going to buy a ball for you!\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mark is strong because ____.</p>", "options": ["he's tall", "he's a student", "he likes sports"], "answer": "C（he likes sports）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mark lives ____ now.</p>", "options": ["in a village", "in London", "with his grandma"], "answer": "B（in London）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Mark ____ on Saturday and Sunday.</p>", "options": ["plays basketball", "plays football", "does some housework"], "answer": "B（plays football）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">____, so the old woman doesn't find him at home.</p>", "options": ["Mark goes shopping", "Mark leaves London", "Mark is at school"], "answer": "C（Mark is at school）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">The old woman doesn't know how to play football, so she ____.</p>", "options": ["watches the game for a long time", "tells the boy to go home with her", "gives the team a new ball"], "answer": "B（tells the boy to go home with her）", "type": "mcq", "correct": 1}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s36", "section": 36, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 71 & 72", "title": "阅读理解", "lessons": "Lesson 71 & 72", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Jodie is a 999 operator in London. One Tuesday morning, she was surprised to get a call from a little girl. She said, \"Mum ill. Mum ill,\" again and again. Jodie soon found the address of the call. She called the police. In a minute, the policemen and doctors arrived at the house. They broke the door open. They couldn't believe their eyes. The little baby was so young that she could not walk! She was sitting beside her mother and holding her mother's hand. Tears were running down her face.</p>\n<p class=\"source-line\">The doctors gave the woman some medicine and soon she woke up. Later, she told people that she couldn't believe it. Her one-year-old daughter could dial the number 999 while she was so young.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What did the baby want to say?</p>", "options": ["\"Mum, I'm ill.\"", "\"My mum is ill.\"", "\"Mum and I are ill.\"", "\"Mum, we are ill.\""], "answer": "B（My mum is ill.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Who called the police?</p>", "options": ["The baby.", "No one.", "The operator.", "The little girl's mum."], "answer": "C（The operator.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">The little girl felt ____ when her mum was ill.</p>", "options": ["happy", "sad", "excited", "funny"], "answer": "B（sad）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">From the story, we know that ____.</p>", "options": ["the little girl's mother died at last", "the little girl could walk at the age of one", "the little girl's mother saved herself", "the little girl saved her mum"], "answer": "D（the little girl saved her mum）", "type": "mcq", "correct": 3}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mrs. Jones is waiting for an important telephone call, but she has no bread in the house, so she leaves the baby at home and says to her five-year-old son, \"I'm going to the shop, Jimmy, and I'll be back in a few minutes.\"</p>\n<p class=\"source-line\">While she is out, the telephone rings, and Jimmy answers it. \"Hello,\" says a man. \"Is your mother here?\"</p>\n<p class=\"source-line\">\"No,\" answers Jimmy.</p>\n<p class=\"source-line\">\"Well, when she comes back, say to her that Mr. Baker telephoned.\"</p>\n<p class=\"source-line\">\"What?\"</p>\n<p class=\"source-line\">\"Mr. Baker. Write it down, B—A—K—E—R.\"</p>\n<p class=\"source-line\">\"How do you make a B?\"</p>\n<p class=\"source-line\">\"How do I make a B? Listen, little boy, is there anybody else with you? Any brothers or sisters?\"</p>\n<p class=\"source-line\">\"My brother Billy is here.\"</p>\n<p class=\"source-line\">\"Good. I want to talk to him, please.\"</p>\n<p class=\"source-line\">\"All right.\" Jimmy takes the telephone to the baby's bed and gives it to Billy. When their mother comes back, she asks, \"Did anyone telephone?\" \"Yes,\" says Jimmy. \"A man, but he only wanted to talk to Billy.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mrs. Jones is waiting for ____.</p>", "options": ["her husband", "her children", "an important telephone call", "her brother"], "answer": "C（an important telephone call）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Jimmy is ____.</p>", "options": ["Billy's brother", "Mrs. Jones's brother", "Mr. Baker's son", "Mrs. Jones's daughter"], "answer": "A（Billy's brother）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Mrs. Jones has no ____ in her house.</p>", "options": ["money", "milk", "bread", "rice"], "answer": "C（bread）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Billy is ____ than Jimmy.</p>", "options": ["older", "younger", "taller", "cleverer"], "answer": "B（younger）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">From the story, we know that ____.</p>", "options": ["Jimmy can write a lot of words", "Jimmy can write a few words", "Jimmy can write few letters", "Jimmy can write a lot of letters"], "answer": "C（Jimmy can write few letters.）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s37", "section": 37, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 73 & 74", "title": "阅读理解", "lessons": "Lesson 73 & 74", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">One day a student came to tell the teacher, \"My red pen is lost.\" \"Who took the pen away?\" the teacher asked. But everyone answered, \"It wasn't me.\"</p>\n<p class=\"source-line\">The teacher knew that one student had told a lie, but he didn't know who had done it. Suddenly he had a good idea. He told the students that he would let God reveal who had taken away the pen. He said God would put a cross on the student's back if he or she had done it. The teacher asked every student to go into a dark room and face the wall. Two minutes later, they came out of the room. The teacher found that Tom's back was white with something on it while the others had nothing on their backs. The wall was wet with white paint. If someone was afraid of the cross, he would turn his back against the wall. Soon the class teacher knew who had done it.</p>\n<p class=\"source-line\">Do you know how the class teacher found out who did it?</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What was wrong with a student one day?</p>", "options": ["The student lost his pen.", "The student lost his pencil case.", "The student was late for school.", "The student took away his pencil case."], "answer": "A（The student lost his pen.）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Who told a lie to the teacher?</p>", "options": ["Everyone.", "No one.", "Tom.", "God."], "answer": "C（Tom.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">According to the teacher's words, what would God do?</p>", "options": ["God would tell the name of the thief.", "God would put a cross on the student's back if he or she had done it.", "God would keep silent.", "God would tell the thief to stop doing it again."], "answer": "B（God would put a cross on the student's back.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">What's the best title for the passage?</p>", "options": ["A Funny Teacher", "A Clever Teacher", "A Clever Student", "God Is Everything"], "answer": "B（A Clever Teacher）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mrs. Brown goes to see her son in London. Her son works in a music club there. Mrs. Brown doesn't know London well, and she can't find her way.</p>\n<p class=\"source-line\">She sees a man at a bus stop. She wants to ask the man the way. \"Excuse me! Can you help me, please? Which bus goes to Miller's Shop?\" Mrs. Brown asks.</p>\n<p class=\"source-line\">The man is very friendly. He smiles. But he can't speak English. He can speak French. He is new in London. He puts his hand into his coat and takes out a small book. He opens it and reads something from it. \"I'm sorry, I can't speak English.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mrs. Brown goes to ____ in London.</p>", "options": ["work in a club", "find the way", "see her son", "ask the man"], "answer": "C（see her son）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mrs. Brown's son works in ____.</p>", "options": ["a big school", "a shop", "a music club", "a bus stop"], "answer": "C（a music club）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">What is \"bus stop\" in Chinese?</p>", "options": ["车库", "加油站", "交通灯", "车站"], "answer": "D（车站）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">Mrs. Brown can't find her way because ____.</p>", "options": ["she is old", "she can't speak English", "she doesn't know London well", "she can't see"], "answer": "C（she doesn't know London well）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">Which is TRUE?</p>", "options": ["The man can't help Mrs. Brown.", "The man at the bus stop is an Englishman.", "Mrs. Brown can't speak English.", "Mrs. Brown borrows the book from the man."], "answer": "A（The man can't help Mrs. Brown.）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s38", "section": 38, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 75 & 76", "title": "阅读理解", "lessons": "Lesson 75 & 76", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">I have a lovely friend at home. Her name is Kitty. She is black and white. She is very cute. I often play with her when I am free. She likes eating fish very much. When she is behind the sofa or in her box, you can't see her. When I sit on the sofa, she sits with me. In the evening I do my homework at my desk, and she is on the desk. Winter is coming. I am afraid that she might be cold. I go to the clothing store to buy a warm coat for her. I help her put the coat on. I think she must feel very comfortable. After she wears the coat, she often rips it with her paws. Oh, she feels uncomfortable wearing a coat. What a lovely cat!</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Who is my lovely friend at home?</p>", "options": ["A boy.", "A cat.", "A fish.", "A dog."], "answer": "B（A cat.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">When she is in the box or behind the sofa, you ____.</p>", "options": ["can't see her", "like her", "play with her", "don't like her"], "answer": "A（can't see her）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">When I do my homework, she ____.</p>", "options": ["does her homework", "plays with a ball", "sits on the sofa", "sits on the desk"], "answer": "D（sits on the desk）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">From the story, we can know that ____.</p>", "options": ["Kitty is the name of a dog", "Kitty likes wearing a coat", "Kitty feels uncomfortable wearing a coat", "Kitty always feels warm"], "answer": "C（Kitty feels uncomfortable wearing a coat.）", "type": "mcq", "correct": 2}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">As a young mother, my neighbour Jane believed that it was very wrong to waste any food. Last night, she gave her small daughter a snack（零食）before bed. First she gave her a slice（一片）of fresh brown bread and butter, but the child said that she did not want it. She asked for some jam（果酱）on her bread as well.</p>\n<p class=\"source-line\">Her mother looked at her for a few seconds and then said, \"When I was a small girl like you, Lucy, I could get only bread and butter, but never bread with butter and jam.\" Lucy looked at her mother for a few seconds and then said to her kindly, \"Are you pleased that you live with us now?\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Why did the young mother give her daughter only bread and butter?</p>", "options": ["Because she was poor.", "Because she didn't like to waste food.", "Because her small girl liked it."], "answer": "B（Because she didn't like to waste food.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">When did she give the girl the bread and butter?</p>", "options": ["After lunch.", "During breakfast.", "Before she went to bed."], "answer": "C（Before she went to bed.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">What did the small girl infer from her mother's words?</p>", "options": ["Mother was very poor when she was young.", "Mother didn't like jam when she was young.", "Mother hated to give her any jam."], "answer": "A（Mother was very poor when she was young.）", "type": "mcq", "correct": 0}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s39", "section": 39, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 77 & 78", "title": "阅读理解", "lessons": "Lesson 77 & 78", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">In the doctor's waiting room, sick men and women were sitting on the chairs. Bob, a schoolboy, was among them. They all looked very sad except Bob. He was deeply absorbed in an exciting story in a magazine. Just then the doctor came in and said he was ready for the next person. Bob jumped up and ran into the doctor's room.</p>\n<p class=\"source-line\">\"What's the matter with you?\" said the doctor. Before Bob could say a word, the doctor made him lie down on a bed. \"Now, let me listen to your heart.\" Bob tried to speak, but the doctor told him not to say anything. \"I'll take your temperature.\" Bob tried to stand up, but the doctor stopped him. After a moment, the doctor said, \"Well, boy, you don't have a fever. In fact, there is nothing wrong with you.\"</p>\n<p class=\"source-line\">\"I know there is nothing wrong with me,\" said Bob. \"I just came here to get some medicine for my father.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">In the doctor's waiting room, Bob felt ____.</p>", "options": ["sad", "unhappy", "excited", "ill"], "answer": "C（excited）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">What was wrong with Bob?</p>", "options": ["He was badly ill.", "There was nothing wrong with him.", "He was too fat.", "He felt very tired every day."], "answer": "B（There was nothing wrong with him.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why did Bob come to the doctor's room?</p>", "options": ["To see a doctor.", "To help the doctor.", "To get some medicine.", "To clean the room."], "answer": "C（To get some medicine.）", "type": "mcq", "correct": 2}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">A man had a blind date（相亲）with a girl in a restaurant. For the whole evening, the man couldn't stand（忍受）the girl.</p>\n<p class=\"source-line\">Earlier, he secretly asked a friend to call him, so he would have an excuse（借口）to leave. When he returned to the table, he lowered（低下）his eyes and began to cry. The girl asked, \"Is there something wrong?\" The man said, \"Yes. I have some bad news. My grandfather just died.\" \"Thank heavens!\" the girl replied. \"If yours didn't, mine is going to!\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Why did the man stay with the girl in the restaurant?</p>", "options": ["Because they were dating.", "Because the man loved the girl.", "Because the girl was the man's friend."], "answer": "A（Because they were dating.）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why did the man ask his friend to call him?</p>", "options": ["Because he didn't like the girl.", "Because he feared he might miss something important.", "It is not mentioned."], "answer": "A（Because he didn't like the girl.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Who actually died?</p>", "options": ["The man's grandfather.", "The girl's grandfather.", "Nobody."], "answer": "C（Nobody.）", "type": "mcq", "correct": 2}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s40", "section": 40, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 79 & 80", "title": "阅读理解", "lessons": "Lesson 79 & 80", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">In Canada or America, on Sundays lots of people go out for a picnic. They often ask their good friends to go with them. They go to grocery stores to buy some fruit and food. Then they go to the park or climb mountains. They bring many things with them, like glasses, kites, knives, some drinks or other delicious food. Sometimes, they take their pets with them. If it is very fine, they may have their food in the park, in the countryside or on a hill. That's great fun. Do you like this kind of lifestyle?</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Where do people go on Sundays in Canada or America?</p>", "options": ["They go swimming.", "They go shopping.", "They go out for a picnic.", "They stay at home."], "answer": "C（They go out for a picnic.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Who do they often ask to go with them?</p>", "options": ["Their uncles.", "Their aunts.", "Their friends.", "Their sons."], "answer": "C（Their friends.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">They don't bring ____ with them to go for a picnic.</p>", "options": ["kites", "knives", "pets", "pens"], "answer": "D（pens）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">What does the passage tell us?</p>", "options": ["Going shopping in Canada.", "Going for a picnic in China.", "Eating out on a hill.", "Sunday activities in Canada or the USA."], "answer": "D（Sunday activities in Canada or the USA.）", "type": "mcq", "correct": 3}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> Do Shopping</h4>\n<p class=\"source-line\">We go shopping on Saturdays. I often go to the shop with my mother on Saturday morning by bus. Father likes fruit very much. We buy some red apples for him. Mother likes yellow bananas, but they are green. \"Look! The oranges are very nice, Mum. Do you like them?\" I say to Mum. \"Yes, I like oranges very much.\" Mother buys some for herself. The melons are very nice. Mother buys some for me. I like melons very much.</p>\n<p class=\"source-line\">We need some vegetables. We buy some tomatoes, carrots and potatoes. My favourite food is hamburgers and beef. I like drinking Coke and eating ice cream. After shopping, Mother and I have some French fries, milk and juice. And then we go back home with the fruit and vegetables.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mother likes apples very much.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mother buys some melons for me.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">My mother likes oranges very much.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">After we buy the fruit and vegetables, we only have some fruit.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">After shopping, Mother and I go straight back home.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s41", "section": 41, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 81 & 82", "title": "阅读理解", "lessons": "Lesson 81 & 82", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">I am Jack. There are five people in my family: my grandparents, my parents and me. My grandparents are old but very healthy. They like drinking some whisky when they have dinner. My father has a different taste for dinner. He often eats dinner at a restaurant because he has many friends to meet every day. My mum is a beautiful woman. She often cooks beef and potatoes for dinner. I like potatoes very much. I always thank my mum for her kind help. I have a happy family. What about your family?</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">There are five people in the writer's family.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">The writer's parents like whisky very much.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">The writer's father is very busy.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">The writer's mum usually cooks beef and potatoes for dinner.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">An English breakfast is a very big meal: eggs, tomatoes, tea...</p>\n<p class=\"source-line\">（1）Lunch is a quick meal for many people. People often have hamburgers, bread or other fast food because they are very busy at work. Schoolchildren can have a hot meal at school, but many just take a sandwich, a drink and some fruit from home.</p>\n<p class=\"source-line\">Tea means two things. They are a drink and a meal together. （2）Some people have afternoon tea with sandwiches and cakes.</p>\n<p class=\"source-line\">（3）A English evening meal is very late, between six o'clock and eight o'clock. It is a big dinner. All the family members eat at home.</p>\n<p class=\"source-line\">根据短文内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">把（1）处画线句子改写为否定句。</p>", "options": [], "answer": "Lunch is not a quick meal for many people. || Lunch isn't a quick meal for many people.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">把（2）处画线句子翻译成汉语。</p>", "options": [], "answer": "有些人喝下午茶时，吃三明治和蛋糕。", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">把（3）处画线句子中的错误找出来，并改正。</p>", "options": [], "answer": "将 A 改为 An。", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">Why do many people have fast food for lunch?</p>", "options": [], "answer": "Because they are busy at work.", "type": "input", "correct": null}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s42", "section": 42, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 83 & 84", "title": "阅读理解", "lessons": "Lesson 83 & 84", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">May Day is coming. We are making plans for travelling. We'll go to Hainan for our holidays. It's a good place to spend holidays. My aunt lives there. I hope to travel with her. My parents work hard to make money for this holiday. I study hard to make my parents happy. I've already heard that Sanya is a beautiful city in Hainan. It's cool around May. If you go there, you can see flowers everywhere. Girls can wear skirts there. You can see the sea there and swim in the sea. I'll take a camera and take a lot of photos. We also want to visit some other places of interest. Oh, the food there is different from ours. It must be very delicious. It's really wonderful!</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">We are going to visit Sanya, Hainan.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">My parents will be happy if I study hard.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Men can wear skirts in Sanya.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Yosemite National Park was once called the most beautiful place in America. In Yosemite, there are huge rocks and tall trees covering the hills and valleys. Every year, more than 4 million people visit there. They can stay there for one day, one week or even one month because there are many things to do in the park.</p>\n<p class=\"source-line\">People can go for a hike to see Yosemite Falls. It is the tallest waterfall in North America. They can also ride a bike, go fishing or go swimming in the river. People can also take a free art class at the art centre to draw or paint pictures. There is also a climbing class that people can take before they climb the huge rocks.</p>\n<p class=\"source-line\">Are you still looking for a good place to go with your family this summer? Why not plan a trip to Yosemite National Park? You and your family will have a great time there.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What can't you see in Yosemite?</p>", "options": ["Sharks（鲨鱼）.", "Fish.", "A waterfall.", "Trees."], "answer": "A（Sharks.）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">What can't people do in Yosemite?</p>", "options": ["Go fishing.", "Go hiking.", "Go swimming.", "Go shopping."], "answer": "D（Go shopping.）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Which is TRUE?</p>", "options": ["Yosemite is a famous museum.", "People have to pay to get into Yosemite National Park.", "The art class at the art centre is free.", "People can only stay in Yosemite for one week."], "answer": "C（The art class at the art centre is free.）", "type": "mcq", "correct": 2}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s43", "section": 43, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 85 & 86", "title": "阅读理解", "lessons": "Lesson 85 & 86", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Last May Day my family went to the country by car for our holiday. There was too much traffic on the road, so we had to move very slowly. It took us about an hour to get out of the town. After some time, we came to a farm. It was clean and beautiful. I had never seen such a beautiful place before. The animals were very lovely. We thought it was a nice place for a picnic, so we stopped and took the food, fruit and drinks out of the car. We sat down under a big green tree and began to eat. Suddenly, a strong wind blew and soon it started to rain. We had to run back to our car and had our picnic in the car. Then we drove back home. What a bad trip it was!</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Last May Day, how did the family go to the country?</p>", "options": ["By bus.", "By car.", "By train.", "On foot."], "answer": "B（By car.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Where did the family have their picnic last May Day?</p>", "options": ["On a farm.", "In the park.", "On the mountain.", "In the car."], "answer": "D（In the car.）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">How did the family feel about their trip?</p>", "options": ["Nice.", "Good.", "Bad.", "Happy."], "answer": "C（Bad.）", "type": "mcq", "correct": 2}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">A man goes home and tells his wife that he has bought something for her. He holds out a gold ring（金戒指）for his wife to see. Then he drops（掉）it. So he begins to look for it on the floor. It is dark inside the house and he cannot see anything. He goes outside and looks for the ring in the street. Just then a friend comes along. The man tells him that he has just lost a ring in his home. His friend laughs, \"You lost your ring inside your house, but you are looking for it outside in the street. That seems very foolish.\" \"How can I find it in a dark room?\" the man answers.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What has the man bought for his wife?</p>", "options": ["A light.", "A ring.", "A necklace.", "A candle."], "answer": "B（A ring.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why does the man go to the street to look for the ring?</p>", "options": ["Because he lost the ring in the street.", "Because it is very dark in the house.", "Because he knows the ring is in the street.", "Because he wants to meet his friend."], "answer": "B（Because it is very dark in the house.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why does the friend think the man is foolish?</p>", "options": ["Because the man cannot find the ring in the street.", "Because the street is also very dark.", "Because his wife has the ring.", "Because the friend has found the ring."], "answer": "A（Because the man cannot find the ring in the street.）", "type": "mcq", "correct": 0}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s44", "section": 44, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 87 & 88", "title": "阅读理解", "lessons": "Lesson 87 & 88", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">There was a teacher. He had a car, but he didn't drive it often because he wanted to get some exercise. He rode his bike to school and rode it back from school every day.</p>\n<p class=\"source-line\">One night, at about half past ten, he came back home from his evening classes as usual by bicycle. He was riding into a tunnel when a car caught up with him quickly. The driver was a little drunk and didn't notice the bicycle in front of him. The car crashed into the bicycle. Unfortunately, the bicycle was thrown aside and the teacher was badly hurt. He lay on the ground, crying out, \"Help! Help!\" The driver thought it was a dog barking and drove away quickly.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Why didn't the teacher like driving his car?</p>", "options": ["He wanted to walk.", "He liked bicycles better.", "His car was broken.", "He wanted to exercise."], "answer": "D（He wanted to exercise.）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">When did the crash happen?</p>", "options": ["At half past ten a.m.", "At half past ten p.m.", "In the morning.", "In the afternoon."], "answer": "B（At half past ten p.m.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Who was badly hurt?</p>", "options": ["The teacher.", "The driver.", "No one.", "The dog."], "answer": "A（The teacher.）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Why didn't the driver stop his car after the crash?</p>", "options": ["He wanted to have his car repaired soon.", "He thought his car had hit a dog instead of a man.", "He was afraid of sending the hurt man to the hospital.", "He wanted to drive his car to the police station quickly."], "answer": "B（He thought his car had hit a dog instead of a man.）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">One day Mr. Wood went to work in his nice car. The traffic was very heavy. All the cars were moving slowly. When Mr. Wood came to the traffic lights, his mobile phone rang. He took out the phone and answered it. So he didn't notice the red light. His car continued moving and suddenly it hit another car. The two cars had to stop there, and the driver of the other car called the police. They both had to wait for the police to arrive. \"It's cold at this time of year, isn't it?\" said Mr. Wood. \"Sure it is. It's the midwinter season,\" answered the man.</p>\n<p class=\"source-line\">Mr. Wood took out a bottle of vodka and said to the man, \"Try having a drink and it will make you feel warmer.\" The man took the bottle and took a sip. \"Good wine. Why don't you have a drink?\" \"I never drink wine,\" said Mr. Wood. He knew the traffic rules very well. Who would be responsible for the accident after drunk driving? That was why he asked the man to have a drink.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">How did Mr. Wood go to work?</p>", "options": ["By car.", "By bus.", "On foot.", "By subway."], "answer": "A（By car.）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">What was Mr. Wood doing when the accident happened?</p>", "options": ["He was sleeping.", "He was talking to his wife.", "He was answering the phone.", "He was looking at another man."], "answer": "C（He was answering the phone.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Which season was it then?</p>", "options": ["Spring.", "Summer.", "Autumn.", "Winter."], "answer": "D（Winter.）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">From the story, we may know that ____.</p>", "options": ["the other man was clever", "Mr. Wood was very rich", "Mr. Wood was very clever", "the other man didn't want to drink the wine"], "answer": "C（Mr. Wood was very clever.）", "type": "mcq", "correct": 2}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s45", "section": 45, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 89 & 90", "title": "阅读理解", "lessons": "Lesson 89 & 90", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Have you ever met the following situation when you take a taxi?</p>\n<p class=\"source-line\">It was a dark and cold night. The taxi driver didn't have even one passenger all day. When he went by the railway station, he saw an old woman coming out. So he quickly opened the door of the car and asked, \"Where do you want to go, madam?\"</p>\n<p class=\"source-line\">\"To Sunshine Hotel,\" the old woman answered. Sunshine Hotel was close to the station. The driver could only get 4 dollars. But suddenly, he had an idea.</p>\n<p class=\"source-line\">After driving around several streets, the car arrived at the hotel. \"15 dollars.\" \"What? Last week, I took a taxi from the railway station to this same hotel and I only gave the driver 13 dollars. I will give you 13 dollars, too,\" said the old woman.</p>\n<p class=\"source-line\">根据短文内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">When the taxi driver went by the railway station, what did he see?</p>", "options": [], "answer": "He saw an old woman coming out of the railway station.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">Where did the old woman want to go?</p>", "options": [], "answer": "She wanted to go to Sunshine Hotel.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">How much did the old woman want to pay?</p>", "options": [], "answer": "Thirteen dollars.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">What do you think of the two taxi drivers?</p>", "options": [], "answer": "They are dishonest taxi drivers. || They are not good taxi drivers.", "type": "input", "correct": null}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mr. Smith lives in a village, but he works in a big city. He goes to work by train every morning and comes back home in the same way.</p>\n<p class=\"source-line\">This morning, when he was reading his newspapers on the train, a man behind him said \"Hello\" to him and began to talk to him. \"Your life is not interesting, is it? You take the same train at the same time every morning, and you always sit in the same seat and read the same newspapers.\" \"How do you know all that about me?\" Mr. Smith asked angrily.</p>\n<p class=\"source-line\">\"Because I always sit in the same seat behind you,\" the man answered.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mr. Smith works ____.</p>", "options": ["in a village", "in a city", "in a town", "in the country"], "answer": "B（in a city）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">He comes back home from work ____.</p>", "options": ["by ship", "by bus", "on foot", "by train"], "answer": "D（by train）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">When he is on the train, Mr. Smith often ____.</p>", "options": ["reads books", "reads newspapers", "talks to others", "listens to others"], "answer": "B（reads newspapers）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Mr. Smith ____.</p>", "options": ["likes the man very much", "is good at reading", "doesn't like the man at all", "has much money"], "answer": "C（doesn't like the man at all）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">The man knows Mr. Smith because ____.</p>", "options": ["he is Mr. Smith's good friend", "they work in the same factory", "they live in the same village", "he sits behind Mr. Smith on the train every day"], "answer": "D（he sits behind Mr. Smith on the train every day）", "type": "mcq", "correct": 3}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s46", "section": 46, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 91 & 92", "title": "阅读理解", "lessons": "Lesson 91 & 92", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">The first new hotel in a tree is going to open soon. It will open in a faraway village in Sweden. The tree hotel will have four rooms when it opens on June 1st. Another two rooms will open in September—the UFO and A Room with a View.</p>\n<p class=\"source-line\">\"Our goal in five years is to have 20 rooms in several places,\" says Edward, who thought of the idea along with his wife, Venus. It is four metres high and four metres wide. Many people will pay attention to it because the tree hotel is attached to a single tree.</p>\n<p class=\"source-line\">It is an interesting building. You cannot find anything like this in the world today. The price is a little high, $680 for two people, but you will have a good time on your trip there.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">How many rooms will there be in the tree hotel by September?</p>", "options": ["Two.", "Four.", "Six.", "Twenty-four."], "answer": "C（Six.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">The idea of the tree hotel was thought of by ____.</p>", "options": ["Edward", "Venus", "many people", "Edward and Venus"], "answer": "D（Edward and Venus）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">How much money will one person spend on the tree hotel for a night?</p>", "options": ["$240.", "$340.", "¥680.", "¥340."], "answer": "B（$340.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">What can we know from the passage?</p>", "options": ["Several countries have tree hotels.", "Sweden is the first country to have a tree hotel.", "A UFO also flies to the tree hotel.", "Edward is Venus's wife."], "answer": "B（Sweden is the first country to have a tree hotel.）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Charlie has a big shop in the city and makes a lot of money. His wife wanted to live in another section, so she could go to the park in front of the house and play volleyball on the beach by the sea. Charlie thought she was right and hoped to buy the rooms on the first floor of the house, so they could watch the flowers in the garden through the windows. But his wife liked the rooms on the second floor. They were bright and clean. Charlie agreed.</p>\n<p class=\"source-line\">Last Monday Charlie and his wife moved into the new rooms. Their friends came to help them. After dinner they began to dance, play classical music and sing. They were very happy. At eleven the telephone rang and Helen went to answer it. After that she said to her husband, \"The old man downstairs called us. He said the noise in our rooms kept him from going to sleep. Luckily we live upstairs!\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">____, so they wanted to live in another section.</p>", "options": ["Charlie was very busy", "Charlie made a lot of money", "Charlie hoped to live on the first floor", "Charlie hoped for rooms with little noise"], "answer": "B（Charlie made a lot of money）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Charlie wanted to buy the rooms on the first floor because ____.</p>", "options": ["there was a garden near the house", "it was difficult for him to go upstairs", "he could walk near the garden", "he could dance in them"], "answer": "A（there was a garden near the house）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">They had dinner ____.</p>", "options": ["before they moved into the new rooms", "when they danced and sang in the rooms", "after they moved into the new rooms", "after the old man downstairs called them"], "answer": "C（after they moved into the new rooms）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Helen thought ____.</p>", "options": ["they had to finish dancing upstairs", "they were lucky to live upstairs", "they did wrong that evening", "she had to say sorry to the old man"], "answer": "B（they were lucky to live upstairs）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s47", "section": 47, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 93 & 94", "title": "阅读理解", "lessons": "Lesson 93 & 94", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">I have a new neighbour now. He is a pilot. He lives upstairs. I don't know his name. I only know he comes back home very late every night.</p>\n<p class=\"source-line\">Whenever he comes back, he always cooks dinner at about half past eleven p.m. The sound of the kitchen noise makes me mad. What's worse, he usually takes off his shoes loudly and drops them on the floor. Bang, one shoe; bang, the other shoe. So I went to talk with him about this problem the night before last.</p>\n<p class=\"source-line\">Last night, he came back as usual. After dinner, he took off one of his shoes. Bang! Suddenly he remembered his neighbour and put the other shoe on the floor lightly. I was about to sleep at that time, but I couldn't fall asleep. I was waiting for the sound of his other shoe.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The writer's new neighbour is ____.</p>", "options": ["a doctor", "a pilot", "an engineer", "a teacher"], "answer": "B（a pilot）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">What time does the writer's neighbour come back from work?</p>", "options": ["At about ten a.m.", "At about half past eleven p.m.", "At six o'clock p.m.", "At about half past eleven a.m."], "answer": "B（At about half past eleven p.m.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">What makes the writer feel unhappy?</p>", "options": ["The kitchen noise.", "The noise of the shoes.", "The noisy music.", "Both A and B."], "answer": "D（Both A and B.）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">Why couldn't the writer fall asleep?</p>", "options": ["Because the writer was too tired to fall asleep.", "Because the writer was waiting for the sound of the other shoe.", "Because the writer was thinking of some way to stop it.", "Because the writer wasn't angry with the neighbour any longer."], "answer": "B（Because the writer was waiting for the sound of the other shoe.）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Most people who work in an office have a boss. So do I. But my boss is a little unusual. What's unusual about him? It's a big dog. Many men have dogs, but few men bring their dogs to the office every day. My boss's dog, Robinson, is big and brown. My boss brings him to work every day. He takes the dog to meetings and he takes the dog to lunch. When there is a telephone call for my boss, I always know if he is in the office. I only look under his desk. If I see something brown and hairy under it, I know my boss is somewhere in the office. If there is no dog, I know my boss is out.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">People ____ bring dogs to the office.</p>", "options": ["usually", "often", "seldom（几乎不）", "sometimes"], "answer": "C（seldom）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">My boss is Robinson's ____.</p>", "options": ["boss", "master（主人）", "classmate", "teacher"], "answer": "B（master）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Robinson goes to meetings ____ my boss.</p>", "options": ["for", "without", "instead of（代替）", "with"], "answer": "D（with）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">Robinson is always under the desk if the boss is ____.</p>", "options": ["in the office", "at meetings", "out of the office", "out of work"], "answer": "A（in the office）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">The passage tells us the boss ____ the dog very much.</p>", "options": ["looks like", "hates（恨）", "likes", "trusts（信任）"], "answer": "C（likes）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s48", "section": 48, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 95 & 96", "title": "阅读理解", "lessons": "Lesson 95 & 96", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Taking a train is faster than taking a taxi or a bus, but taking the wrong train is a disaster when you're not careful. If you're in a hurry, you might not reach your destination, or it might take you much longer than you expected.</p>\n<p class=\"source-line\">I had been in this new city in Thailand for only several weeks. I had to take the train for convenience. It was my first time travelling all by myself. I thought I had missed a train, but I was happy that there were two trains. I didn't know how to ask clearly enough yet, so I followed the train instructions and got on a train. Just as I was about to ask someone, the train started moving in the opposite direction from my destination. I told the conductor to let me get off at the next station.</p>\n<p class=\"source-line\">That's my story.</p>\n<p class=\"source-line\">根据短文内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Which is faster for travelling, by train or by bus?</p>", "options": [], "answer": "By train.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">Where had the writer stayed for only several weeks?</p>", "options": [], "answer": "In Thailand.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">What happened to the writer when he took the train?</p>", "options": [], "answer": "He took the wrong train.", "type": "input", "correct": null}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> I Only Save Four Dollars Now</h4>\n<p class=\"source-line\">Gary is a worker in a factory. He goes to the factory on foot every day. One day, he comes back home and is very angry. His wife asks him, \"Why are you angry, Gary?\" \"Bus tickets cost three dollars last week, but now they cost two dollars,\" he says. \"It's good. Going by bus is cheaper now,\" his wife says. \"Yes, it is,\" Gary says. \"But I always walk to work in the morning and walk home in the afternoon. Last week I saved six dollars every day, but now I only save four dollars.\"</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Gary was angry because of his wife.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Gary was angry because the bus tickets were more expensive.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Gary was angry because the bus tickets were cheaper.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Last week Gary saved six dollars every day.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">Now Gary saves two dollars less every day than last week.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s49", "section": 49, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 97 & 98", "title": "阅读理解", "lessons": "Lesson 97 & 98", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> Who Moved My Cheese?</h4>\n<p class=\"source-line\">One day, Mice Sniff and Scurry arrive at Cheese Station C, only to find no cheese left, but they are not surprised. Noticing that the cheese supply is low, they leave to find more cheese. Leaving Cheese Station C behind, they begin their hunt for new cheese together. Later that day, Mice Hem and Haw arrive at Cheese Station C only to find the same thing: no cheese. Angered and annoyed, Hem asks, \"Who moved my cheese?\" After making sure that the cheese is indeed gone, they get angry at the unfair situation and both go home hungry. Returning the next day, Hem and Haw find the same cheeseless place. Starting to see the situation at hand, Haw thinks of a way to search for new cheese. But Hem dies because he stays in the same place where there is no cheese.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">There are four mice in the story.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Two mice leave to find more cheese immediately.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Hem comes up with a way to find new cheese.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Two mice die in the end.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Today Mike is playing near a river. Suddenly, his knife falls into the water. He likes the knife very much. Now it's lost, so he is very sad. Then an old woman comes up and asks Mike what is wrong. \"I lost my knife,\" he says. The old woman gives him a gold knife and asks, \"Is it your knife?\" \"No,\" says the boy. The old woman gives him a silver knife and asks again, \"And this one?\" \"No,\" says the boy. Then she gives him an iron knife. \"Yes, that's mine,\" shouts the happy boy. The old woman says, \"OK, take the gold knife and the silver knife as well. You are a good boy.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What happens（发生）to Mike when he is playing near a river?</p>", "options": ["His father gives him a knife.", "He goes into the river.", "An old woman goes into the water.", "His knife goes into the water."], "answer": "D（His knife goes into the water.）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">The word \"sad\" means ____.</p>", "options": ["高兴的", "好奇的", "伤心的", "生气的"], "answer": "C（伤心的）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Mike is happy because ____.</p>", "options": ["he sees the gold knife", "the old woman is kind", "he gets his knife back with the old woman's help", "he likes the old woman"], "answer": "C（he gets his knife back with the old woman's help）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">____ knife is Mike's.</p>", "options": ["The gold", "The silver", "The iron", "The old"], "answer": "C（The iron）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">What do you think of the boy?</p>", "options": ["Silly.", "Good.", "Bad.", "Warm-hearted."], "answer": "B（Good.）", "type": "mcq", "correct": 1}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s50", "section": 50, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 99 & 100", "title": "阅读理解", "lessons": "Lesson 99 & 100", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">A: Good morning. What's wrong with you, madam?</p>\n<p class=\"source-line\">B: I feel ill. My throat hurts.</p>\n<p class=\"source-line\">A: How long have you been like this?</p>\n<p class=\"source-line\">B: About one day.</p>\n<p class=\"source-line\">A: What's your temperature?</p>\n<p class=\"source-line\">B: I don't know.</p>\n<p class=\"source-line\">A: OK. Put the thermometer in your mouth.</p>\n<p class=\"source-line\">B: All right.</p>\n<p class=\"source-line\">（After 5 minutes.）</p>\n<p class=\"source-line\">A: Let me have a look at the thermometer. Your temperature is 38.2 degrees centigrade. You have caught a cold.</p>\n<p class=\"source-line\">B: Will I have an injection?</p>\n<p class=\"source-line\">A: Yes, the nurse will do it for you. Your temperature will go down soon. And you should take some medicine.</p>\n<p class=\"source-line\">B: OK. How should I take it?</p>\n<p class=\"source-line\">A: Take three pills at a time, three times a day.</p>\n<p class=\"source-line\">B: Thank you, doctor.</p>\n<p class=\"source-line\">根据对话内容回答问题。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What's wrong with the woman?</p>", "options": [], "answer": "Her throat hurts.", "type": "input", "correct": null}, {"number": 2, "questionHtml": "<p class=\"source-line\">How long has the woman been like this?</p>", "options": [], "answer": "About one day.", "type": "input", "correct": null}, {"number": 3, "questionHtml": "<p class=\"source-line\">What's her temperature?</p>", "options": [], "answer": "38.2 degrees centigrade.", "type": "input", "correct": null}, {"number": 4, "questionHtml": "<p class=\"source-line\">How many pills should the woman take a day?</p>", "options": [], "answer": "Nine pills a day.", "type": "input", "correct": null}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> A Little Horse Crosses a River</h4>\n<p class=\"source-line\">Mummy asks a little horse to carry a bag of wheat home.</p>\n<p class=\"source-line\">On the way home, the little horse meets a small river. He is very worried. \"What should I do?\" he thinks. At this time, he meets a squirrel（松鼠）.</p>\n<p class=\"source-line\">\"Can I cross the river?\" the little horse asks.</p>\n<p class=\"source-line\">\"Oh, you can't. The river is very deep. You will be drowned,\" the squirrel says.</p>\n<p class=\"source-line\">The little horse is very afraid. He cries.</p>\n<p class=\"source-line\">A cow comes to the little horse. \"What's the matter with you, little horse?\" the cow asks. \"I can't cross this river. It's very deep,\" the little horse answers. \"Oh, don't worry. This river isn't deep at all. I am sure you can cross the river easily. Try!\" the cow says.</p>\n<p class=\"source-line\">The little horse stops crying. He tries his best and crosses the river.</p>\n<p class=\"source-line\">The moral: You never know what you can do until you try.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">One day, the little horse's mummy asks him to ____.</p>", "options": ["carry a bag of wheat home", "cross the river", "go home"], "answer": "A（carry a bag of wheat home）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">The squirrel thinks the little horse ____.</p>", "options": ["can cross the river", "can't cross the river", "will not be drowned"], "answer": "B（can't cross the river）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">The cow thinks the little horse ____.</p>", "options": ["can cross the river easily", "can't cross the river", "will be drowned"], "answer": "A（can cross the river easily）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">At last, the little horse tries his best to ____ the river.</p>", "options": ["cross", "fly", "fall into"], "answer": "A（cross）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">At last, the little horse knows ____.</p>", "options": ["he can't cross the river", "the river is very deep and he can't cross it", "the river isn't very deep and he can cross it"], "answer": "C（the river isn't very deep and he can cross it）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s51", "section": 51, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 101 & 102", "title": "阅读理解", "lessons": "Lesson 101 & 102", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">One day, I was free from work. I decided to tidy up my bookcase. I found a lot of old things in it. Suddenly I saw a postcard. It was sent to me by the post office before the Spring Festival. There was a group of numbers on the card. If you were lucky enough, your card numbers would be chosen as lucky numbers. I was very happy to find the card.</p>\n<p class=\"source-line\">I hurriedly visited the post office's website to see whether I was a lucky dog. To my surprise, the lucky numbers were exactly the same as those on my postcard. As a prize, I would be given a laptop. I called the office excitedly and told the office worker that I was the lucky dog.</p>\n<p class=\"source-line\">A moment later, the office worker said, \"First, I should say you are very lucky. But I should say sorry to you at the same time because the activity ended the day before.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What did the writer decide to do one day?</p>", "options": ["To clean the bedroom.", "To watch TV.", "To tidy up the bookcase.", "To cook dinner."], "answer": "C（To tidy up the bookcase.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Where did the writer get the postcard?</p>", "options": ["His friend sent it to him.", "The post office sent it to him.", "He bought it in a shop.", "His boss sent it to him."], "answer": "B（The post office sent it to him.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">What would the writer get if his numbers were the lucky numbers?</p>", "options": ["A pen.", "A book.", "A laptop.", "A refrigerator."], "answer": "C（A laptop.）", "type": "mcq", "correct": 2}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> Happy Mother's Day!</h4>\n<p class=\"source-line\">Thank you very much for working so hard for our whole family. You always get up at five thirty every morning. And you get home from work at seven every evening. You always cook a delicious dinner for us. We all enjoy it. You really help us a lot.</p>\n<p class=\"source-line\">We know you like wearing pretty jewellery very much. But we don't have enough money to buy it for you. So Peter and I can buy only a new dress and make a cute card for you. For your health, please don't stay up too late.</p>\n<p class=\"source-line\">We love you forever, Mum.</p>\n<p class=\"source-line\">Your son and daughter,<br>\nPeter and Amy</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What time does Amy's mother get home every day?</p>", "options": ["At 5:30 a.m.", "At 7:00 a.m.", "At 5:30 p.m.", "At 7:00 p.m."], "answer": "D（At 7:00 p.m.）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">What does Amy's mother need to do for her health?</p>", "options": ["Get up early.", "Go to bed late.", "Go to bed early.", "Work hard."], "answer": "C（Go to bed early.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Who is Peter?</p>", "options": ["Amy's brother.", "Amy's son.", "Amy's father.", "Amy's daughter."], "answer": "A（Amy's brother.）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">What present does Amy give her mother?</p>", "options": ["Jewellery.", "Shoes.", "Flowers.", "Clothes."], "answer": "D（Clothes.）", "type": "mcq", "correct": 3}, {"number": 5, "questionHtml": "<p class=\"source-line\">Which one is TRUE?</p>", "options": ["Amy has a lot of money.", "Amy's mother is not a housewife.", "Amy doesn't like to eat dinner at home.", "Amy's mother doesn't like to wear jewellery."], "answer": "B（Amy's mother is not a housewife.）", "type": "mcq", "correct": 1}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s52", "section": 52, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 103 & 104", "title": "阅读理解", "lessons": "Lesson 103 & 104", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">My name is Julie. I like English very much. However, I am afraid of English tests. Every time I would give my English teacher a surprise. She never thought that I would perform badly. She knows I am a hard-working student.</p>\n<p class=\"source-line\">In fact, I am good at English. But I always make some mistakes when I fill out the answer sheet.</p>\n<p class=\"source-line\">My English teacher could never believe what I had done in my English tests. She said to me one day that she wanted to give me a second try. I spent only an hour finishing the paper because I thought it was a little easy.</p>\n<p class=\"source-line\">My English teacher was very surprised and asked me for the reason. I told her that I didn't need to fill out the answer sheet. That was the biggest problem.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What does Julie's English teacher think of her?</p>", "options": ["Lazy.", "Hard-working.", "Cold.", "Kind."], "answer": "B（Hard-working.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">When does Julie make some mistakes?</p>", "options": ["During her English test.", "When she fills out the answer sheet.", "While sleeping.", "When she meets her English teacher."], "answer": "B（When she fills out the answer sheet.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Julie thought the second English test was ____.</p>", "options": ["very easy", "hard", "difficult", "a little easy"], "answer": "D（a little easy）", "type": "mcq", "correct": 3}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">People in many countries are learning English. Some are learning at school. Others are learning at home. Why do all these people want to learn English? It is not easy to answer this question. Many boys and girls learn English at school because it is one of their lessons. Some people learn it because it is useful for their work. Many people learn English for their higher studies. Other people learn English because they want to read English books and learn a lot from other countries.</p>\n<p class=\"source-line\">English isn't easy, but it is useful. It is a bridge to so much knowledge. So we must work hard at it.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">People learn English ____.</p>", "options": ["at school", "at home", "on TV", "in different ways"], "answer": "D（in different ways）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">The students learn English at school because it is ____.</p>", "options": ["a bridge", "useful", "one of their lessons", "easy"], "answer": "C（one of their lessons）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">People want to learn English for ____.</p>", "options": ["different reasons", "their work", "so much knowledge", "higher studies"], "answer": "A（different reasons）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">From the passage we know that English is ____.</p>", "options": ["easy", "useful", "good", "high"], "answer": "B（useful）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">Which of the following is RIGHT?</p>", "options": ["We learn English easily.", "We don't need to learn English.", "Many people only learn English at school.", "English is a bridge to so much knowledge."], "answer": "D（English is a bridge to so much knowledge.）", "type": "mcq", "correct": 3}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s53", "section": 53, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 105 & 106", "title": "阅读理解", "lessons": "Lesson 105 & 106", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Once Newton invited his good friend to his house for dinner. When Jackson got to Newton's house, Newton went into his kitchen, but soon he remembered his laboratory. He went into his laboratory and conducted an experiment in physics.</p>\n<p class=\"source-line\">His friend Jackson waited in the living room for one hour, but he couldn't smell any food. He knew Newton was a busy man, so he wasn't angry with him. He went back home alone.</p>\n<p class=\"source-line\">The next day, when Jackson talked about the matter with Newton, Newton felt very sorry. He had forgotten that he had invited Jackson to his home for dinner the day before. What a mistake!</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Newton invited his good friend to his house ____.</p>", "options": ["for breakfast", "for dinner", "to play games", "to have a talk"], "answer": "B（for dinner）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Newton was a scientist of ____.</p>", "options": ["Chinese", "English", "physics", "music"], "answer": "C（physics）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why wasn't Jackson angry with Newton?</p>", "options": ["Because he knew Newton was busy.", "Because he was Newton's friend.", "Because he was a strange man.", "Because Newton couldn't cook any food."], "answer": "A（Because he knew Newton was busy.）", "type": "mcq", "correct": 0}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">A man was reading the paper when an ad（广告）caught his eye: \"$500 Porsche（保时捷汽车）! New!\" The man thought that it was very unusual to sell a Porsche for $500, and he thought it might be a joke. So he went to the lady's house and saw an almost brand-new（崭新的）Porsche.</p>\n<p class=\"source-line\">\"Wow!\" the man said. \"Can I take it for a test drive（试驾）?\" Unlike what he expected, the man found that the car ran perfectly and he took it back to the lady's house.</p>\n<p class=\"source-line\">\"Why are you selling me this great Porsche for only $500?\"</p>\n<p class=\"source-line\">\"My husband just ran off with（和……跑掉）his secretary, and he told me I could have the house and the furniture as long as I sold his Porsche and sent him the money.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Why did the woman sell the car?</p>", "options": ["Because her husband asked her to do so.", "Because she wanted to get the money.", "It is not mentioned."], "answer": "A（Because her husband asked her to do so.）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">How was the car?</p>", "options": ["It was in great condition.", "It was not worth a lot of money.", "It was poor and broken."], "answer": "A（It was in great condition.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why was the woman doing so?</p>", "options": ["Because she hated the car.", "Because she wanted to take revenge on her husband.", "It is not mentioned."], "answer": "B（Because she wanted to take revenge on her husband.）", "type": "mcq", "correct": 1}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s54", "section": 54, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 107 & 108", "title": "阅读理解", "lessons": "Lesson 107 & 108", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">This is Mini Clothing Store. There are many kinds of clothes in the shop. In the store, you can buy shirts, skirts, dresses and some coats. You can buy children's shoes, too. A lot of items are on sale, and they are very cheap at this time of year. A lot of pretty girls are choosing what they like. Some smart boys are in the store, too. They are asking the salesgirls about the sizes and styles.</p>\n<p class=\"source-line\">Sandra wants to buy a white skirt. She is asking Janet, the salesgirl, some questions:</p>\n<p class=\"source-line\">Sandra: I like the colour. How much is it?</p>\n<p class=\"source-line\">Salesgirl: It is 150 yuan.</p>\n<p class=\"source-line\">Sandra: It's a little expensive. What's more, I'm afraid it's a little small for me.</p>\n<p class=\"source-line\">Salesgirl: It's in fashion now. I think the colour suits you well.</p>\n<p class=\"source-line\">Sandra: OK. I will take it.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The store sells ____.</p>", "options": ["food", "drinks", "clothes", "books"], "answer": "C（clothes）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">We can't buy ____ in the store.</p>", "options": ["skirts", "coats", "shirts", "pencils"], "answer": "D（pencils）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Who can you see in the store?</p>", "options": ["Girls.", "Boys.", "Salesgirls.", "All of the above."], "answer": "D（All of the above.）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">How much does Sandra spend on the white skirt?</p>", "options": ["£150.", "¥150.", "$150.", "50 yuan."], "answer": "B（¥150.）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> Gardens</h4>\n<p class=\"source-line\">Mr. White has a big garden. There are lots of flowers in it. But he has only a few trees.</p>\n<p class=\"source-line\">His neighbour, Mr. Black, has a garden, too. Mr. Black's garden is smaller than Mr. White's garden. He has fewer flowers than Mr. White, but more trees.</p>\n<p class=\"source-line\">Mr. Brown is another neighbour of Mr. White's. Mr. Brown's garden is the smallest of the three. He has the fewest flowers of them all, but the weeds in his garden are the longest. There is always a lot of work in the garden, but Mr. Brown doesn't have enough time to work in his garden. So his garden is the worst.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">____ has a big garden.</p>", "options": ["Mr. White", "Mr. Black", "Mr. Brown", "Their neighbour"], "answer": "A（Mr. White）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mr. Black has ____ flowers and ____ trees.</p>", "options": ["fewer; fewer", "lots of; a few", "the fewest; more", "fewer; more"], "answer": "D（fewer; more）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Whose garden is the smallest of the three?</p>", "options": ["Mr. White's.", "Mr. Black's.", "Mr. Brown's.", "Their neighbour's."], "answer": "C（Mr. Brown's.）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Does Mr. Brown have enough time to work in the garden?</p>", "options": ["No, he doesn't.", "Yes, he does.", "No, he didn't.", "Yes, he did."], "answer": "A（No, he doesn't.）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s55", "section": 55, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 109 & 110", "title": "阅读理解", "lessons": "Lesson 109 & 110", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Jane's father is a heavy smoker. He likes smoking a lot. His teeth are yellow. Sometimes he coughs. Jane is very worried about him, but he often says smoking can relax him.</p>\n<p class=\"source-line\">One day, Jane had a good idea. She said to her father, \"Dear Dad, I don't understand the meaning of this newspaper article. Can you read it for me?\" Her father read it aloud. The article said smoking was bad for the lungs. It might cause cancer.</p>\n<p class=\"source-line\">\"Dad, do you still like smoking?\" asked Jane.</p>\n<p class=\"source-line\">\"No, but...\"</p>\n<p class=\"source-line\">\"Would you like to watch the 31st Olympic Games in 2016?\"</p>\n<p class=\"source-line\">\"Sure, I'd love to, but I'm afraid I can't go because I don't have much money.\"</p>\n<p class=\"source-line\">\"If you give up smoking now, you'll have enough money for a ticket in three years. And it's also good for your health. Why not do it?\"</p>\n<p class=\"source-line\">\"It's wonderful. I think I must give up smoking tomorrow.\"</p>\n<p class=\"source-line\">\"No, right now,\" Jane shouted.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What colour are Jane's father's teeth now?</p>", "options": ["Red.", "Yellow.", "Black.", "White."], "answer": "B（Yellow.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Jane's father thinks smoking can ____.</p>", "options": ["relax him", "make him tired", "make him excited", "help him deal with work"], "answer": "A（relax him）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Smoking can ____ according to the newspaper.</p>", "options": ["cause cancer", "hurt your face", "cause the flu", "relax you"], "answer": "A（cause cancer）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Jane is a(n) ____ girl.</p>", "options": ["clever", "tall", "old", "terrible"], "answer": "A（clever）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> The Sun and the Wind</h4>\n<p class=\"source-line\">The sun says he is stronger than the wind. The wind says he is stronger than the sun. A man is walking down the street with a hat and a coat on.</p>\n<p class=\"source-line\">The sun says, \"Let's see who can make the man take off his hat and coat. If you can do that, you are stronger than I am.\"</p>\n<p class=\"source-line\">Now the wind begins to blow. But the harder he blows, the tighter the man holds his hat and coat. The wind cannot make him take off his hat and coat. Now the sun tries. He shines brightly. Soon the man takes off his hat and coat.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">A man is sleeping in the street.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">The wind makes the man take off his hat and coat.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">The sun makes the man take off his hat and coat.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">The sun is stronger than the wind.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">The harder the wind blows, the tighter the man holds his hat and coat.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s56", "section": 56, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 111 & 112", "title": "阅读理解", "lessons": "Lesson 111 & 112", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Steve and Joan are going to get married. They are doing some shopping in a store. They want to buy a refrigerator for their new home. Steve wants to buy a famous brand. But he is only a worker and he can't afford to spend all that money. His future wife is a bank clerk. She gets a good salary, but she doesn't want to spend much money on a refrigerator. She likes to buy expensive clothes. Now they have different ideas. \"Can we buy the Haier refrigerator, dear? It is a little expensive, but it is worth the money,\" says Steve. \"No, we can't. I like the model, but you don't have enough money to pay for it,\" says Joan.</p>\n<p class=\"source-line\">\"Can I buy it on instalments?\" asks Steve. \"OK. But you must pay all the rest by yourself,\" says Joan.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Steve and Joan are ____.</p>", "options": ["watching TV", "doing some shopping", "buying a TV", "having lunch"], "answer": "B（doing some shopping）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">What kind of refrigerator does Steve want to buy?</p>", "options": ["Cheap.", "Expensive.", "Big.", "Small."], "answer": "B（Expensive.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Joan is ____.</p>", "options": ["a worker", "a policewoman", "a clerk", "a nurse"], "answer": "C（a clerk）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Which of the following sentences is NOT true?</p>", "options": ["Steve and Joan will get married soon.", "Joan would like to buy a Haier refrigerator.", "Steve doesn't have enough money to buy a Haier refrigerator.", "They will buy the refrigerator on instalments."], "answer": "B（Joan would like to buy a Haier refrigerator.）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mrs. Wilson likes to ask her husband to go shopping with her on Sundays. Her husband pays for the things that she buys. Now they are in a shop.</p>\n<p class=\"source-line\">\"Look, Andy. Isn't it a fancy hair clip?\" Mrs. Wilson asks her husband.</p>\n<p class=\"source-line\">\"All right. And how much is it?\" he answers and gives money to the shop assistant. When Mrs. Wilson asks him whether something is good or bad, he often says, \"All right. And how much is it?\"</p>\n<p class=\"source-line\">At about 8 o'clock p.m., Andy is tired and thirsty, and he wants to have a drink. Suddenly his wife looks up at the moon and says, \"Look, Andy. Isn't the moon beautiful?\"</p>\n<p class=\"source-line\">\"All right. And how much is it?\" her husband answers quickly.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mrs. Wilson likes to go shopping on Sundays.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Andy is Mrs. Wilson's husband.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Mrs. Wilson pays for all the things that she buys.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Andy is hungry and wants to buy some food.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">Mrs. Wilson wants Andy to buy the moon.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s57", "section": 57, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 113 & 114", "title": "阅读理解", "lessons": "Lesson 113 & 114", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Susan is an eight-year-old girl. She goes to school and comes back home on time every day. But yesterday she was late getting home. Her mother asked her, \"Have you got something special to do today, Susan?\" \"No. I've got nothing to do today. I went to the headmaster's office,\" replied Susan.</p>\n<p class=\"source-line\">Her mother asked her, \"Why did you go to the headmaster's office?\"</p>\n<p class=\"source-line\">\"Because the teacher asked us a question in class and nobody could answer it, but I could. Our teacher said it was good to answer her question. But the question was, 'Who poured ink on my skirt?'\"</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Susan is a girl of six years old.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Susan usually comes home on time.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Susan had to go to the headmaster's office yesterday.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Susan's teacher would be happy to hear Susan's answer.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">A woman was collecting money for a church charity. The money she collected was going to be given to poor children who had no parents to take care of them.</p>\n<p class=\"source-line\">She went from apartment to apartment and from house to house. She knocked on doors and asked for money.</p>\n<p class=\"source-line\">She always said the same words: \"Good morning. I'm collecting money for a church charity. Please be generous. We need $5,000.\"</p>\n<p class=\"source-line\">An artist lived in one of the apartments. He opened the door for her. \"Good morning,\" she said as usual.</p>\n<p class=\"source-line\">The artist said, \"I don't have any money. However, I'll give you a painting.\"</p>\n<p class=\"source-line\">A week later she called on him again. \"I'm sorry to trouble you again,\" she said, \"but we still need more money. I need another $100. Can you help?\" \"Of course,\" the artist said. \"I'll increase the value of my painting to $5,100.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What was the woman collecting money for?</p>", "options": ["A school.", "A church charity.", "Her children.", "Herself."], "answer": "B（A church charity.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">How much money did she plan to collect?</p>", "options": ["$100.", "$5,000.", "¥5,000.", "¥4,900."], "answer": "B（$5,000.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">What did the artist give to the woman?</p>", "options": ["Some coins.", "Some old books.", "A painting.", "A cheque."], "answer": "C（A painting.）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">Which of the following is TRUE?</p>", "options": ["The woman was rich enough to give money to those poor children.", "The woman asked for money door by door.", "The artist gave enough money to the woman.", "Nobody would like to give the woman a hand."], "answer": "B（The woman asked for money door by door.）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s58", "section": 58, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 115 & 116", "title": "阅读理解", "lessons": "Lesson 115 & 116", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">It's Saturday. There are so many people on the bus. An old man is looking here and there. He wants to find a seat. Then he finds one. He goes to it. A small bag is on the seat, and a young man is next to it.</p>\n<p class=\"source-line\">\"Excuse me. May I have this seat?\" asks the old man. \"Sorry, it's for a woman. She has gone to buy some apples,\" says the young man.</p>\n<p class=\"source-line\">\"Well,\" says the old man, \"let me sit here, please. When she comes back, I will leave.\" The bus starts.</p>\n<p class=\"source-line\">\"She hasn't come back, but her bag is here. Let me give her the bag.\" The old man wants to throw the bag out of the window.</p>\n<p class=\"source-line\">\"Don't throw it! It's my bag,\" the young man jumps up and shouts.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What day is it?</p>", "options": ["Sunday.", "Tuesday.", "Friday.", "Saturday."], "answer": "D（Saturday.）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">What is the old man looking for on the bus?</p>", "options": ["His son.", "His bag.", "A seat.", "The conductor."], "answer": "C（A seat.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Whose bag is it on the seat?</p>", "options": ["The old man's.", "The woman's.", "Nobody's.", "The young man's."], "answer": "D（The young man's.）", "type": "mcq", "correct": 3}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Today is my thirteenth birthday. This morning my teacher and classmates celebrated it with me. We sang the birthday song and had some pizza together. It was a lot of fun.</p>\n<p class=\"source-line\">After school, I went to a KTV with Helen and Jack. We stayed there for about three hours. Helen gave me a CD by my favourite singer, Elva. Jack wrote me a song and sang it to me. I was so happy.</p>\n<p class=\"source-line\">In the evening, Mum made a big cheesecake for me. My brother, Kevin, gave me a birthday card. And Dad took all of us to a movie. We all enjoyed the movie and had a good time.</p>\n<p class=\"source-line\">This is a very special birthday. I'll never forget it!</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Who wrote Nancy a song?</p>", "options": ["Kevin.", "Elva.", "Jack.", "Helen."], "answer": "C（Jack.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">How many people are there in Nancy's family?</p>", "options": ["Three.", "Four.", "Five.", "Six."], "answer": "B（Four.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">How did Nancy's teacher and classmates celebrate her birthday?</p>", "options": ["They went to the movies together.", "They gave her a big birthday card.", "They wrote her a song and sang it to her.", "They sang the birthday song and had pizza together."], "answer": "D（They sang the birthday song and had pizza together.）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">How old is Nancy now?</p>", "options": ["Thirteen.", "Fourteen.", "Thirty.", "Forty."], "answer": "A（Thirteen.）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s59", "section": 59, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 117 & 118", "title": "阅读理解", "lessons": "Lesson 117 & 118", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">A young man went to a coffee bar for a drink. He asked for a cup of milk, but he didn't drink it. Then he asked the waiter to bring him a cup of coffee and take the milk away. After he finished drinking, he left the coffee bar without paying any money. \"I'm sorry, sir. I am afraid you've forgotten to pay the bill,\" the waiter said to the man. \"But why should I pay for it?\" the young man asked. \"You drank a cup of coffee just now,\" the waiter answered. \"It's true, but I exchanged the cup of milk for the cup of coffee, and I didn't drink your milk. Why should I give you any money?\" \"Yes, you are right,\" the waiter thought for a moment and let the young man go.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Where did the young man go for a drink?</p>", "options": ["A restaurant.", "A hotel.", "A coffee bar.", "A tea bar."], "answer": "C（A coffee bar.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">How many cups of milk did the man drink in the bar?</p>", "options": ["None.", "One.", "Two.", "Three."], "answer": "A（None.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">What did the man drink at last?</p>", "options": ["A cup of orange juice.", "A cup of apple juice.", "A cup of milk.", "A cup of coffee."], "answer": "D（A cup of coffee.）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">What do you think of the waiter?</p>", "options": ["He is very old.", "He is a young man.", "He is very clever.", "He is very silly."], "answer": "D（He is very silly.）", "type": "mcq", "correct": 3}, {"number": 5, "questionHtml": "<p class=\"source-line\">Which of the following is NOT true?</p>", "options": ["A young woman went into a coffee bar to have a drink.", "The young man didn't drink the milk.", "The young man drank the coffee.", "The young man left the bar without paying any money."], "answer": "A（A young woman went into a coffee bar to have a drink.）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">John is travelling by train. He is very hungry. The train stops at a small station. He wants to buy one cake to eat, but it is raining hard. He wants someone to help him. A little boy comes over to him. John asks him to buy cakes for him. He gives the little boy one hundred yuan and says, \"Go and buy two cakes with the money. One cake is for me, and the other is for you. Can you help me?\" The little boy is very happy and runs to buy cakes in the rain. A few minutes later the little boy comes back and says to John, \"I'm sorry. There was only one cake left. I ate the cake. It was delicious. Thank you very much. Here is your fifty yuan.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">John is travelling ____.</p>", "options": ["by plane", "by train", "by bus"], "answer": "B（by train）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">John wants to eat ____.</p>", "options": ["one cake", "two cakes", "two more cakes"], "answer": "A（one cake）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">____ helps John to buy cakes.</p>", "options": ["A little boy", "A little girl", "A man"], "answer": "A（A little boy）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">The little boy can't buy two cakes because ____.</p>", "options": ["there is only one cake left", "he doesn't like to buy two", "John wants him to buy one"], "answer": "A（there is only one cake left）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">John must be（一定会）very ____.</p>", "options": ["happy", "surprised", "angry"], "answer": "C（angry）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s60", "section": 60, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 119 & 120", "title": "阅读理解", "lessons": "Lesson 119 & 120", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mrs. Black has a shop in the town. There are all kinds of fruit in her shop.</p>\n<p class=\"source-line\">One day, the apples she sold were all fresh and nice. She brought some home for her son, Sam. After lunch, she went out and left the apples on the table. That afternoon Sam came back from school. He felt very hungry. He looked for something to eat and found some apples on the table. \"Great! They are my favourite,\" he cried and ate a lot. Mrs. Black got home after she closed her fruit shop. When she saw Sam, she asked him, \"Did you have the apples?\" \"Yes. And I ate lots of them.\" \"Did you wash them?\" \"Oh, I forgot. I was too hungry. What should I do?\"</p>\n<p class=\"source-line\">A few minutes later, Mrs. Black found her son continuing to drink water.</p>\n<p class=\"source-line\">\"Are you thirsty?\" asked the mother.</p>\n<p class=\"source-line\">\"No, Mum. I want to wash the apples in my stomach with the water.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What kind of shop does Mrs. Black have?</p>", "options": ["A clothes shop.", "A food shop.", "A fruit shop.", "A bookshop."], "answer": "C（A fruit shop.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">What's Sam's favourite fruit?</p>", "options": ["Oranges.", "Pears.", "Bananas.", "Apples."], "answer": "D（Apples.）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Where did Sam find the fruit?</p>", "options": ["On the table.", "In the basket.", "In the kitchen.", "In his bedroom."], "answer": "A（On the table.）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">What do you think of Sam?</p>", "options": ["Kind.", "Funny.", "Old.", "Shy."], "answer": "B（Funny.）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">A man once had a wonderful parrot. The parrot was special and could say any word except the name of his hometown—Catano.</p>\n<p class=\"source-line\">The man tried his best to teach the parrot to say \"Catano,\" but he never managed it. At first, he was kind to it, but gradually he got angry and shouted many times, \"You stupid bird! Why can't you learn to say that one word? Say 'Catano,' or I'll kill you!\" But the parrot still would not say it.</p>\n<p class=\"source-line\">Finally the man gave up. He picked up the parrot and threw the bird into the chicken house. In the house, there were four old chickens waiting to be killed for Sunday's dinner. \"You are more stupid than the chickens,\" the man said as he was leaving.</p>\n<p class=\"source-line\">The next morning, the man went out to the chicken house. When he opened the door, he was shocked by what he saw. He saw the parrot shouting at the chickens, \"Say 'Catano,' or I'll kill you!\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What does the last \"it\" in the second paragraph（段落）refer to?</p>", "options": ["Catano.", "The name.", "The parrot.", "The hometown."], "answer": "A（Catano.）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">What does the word \"shocked\" mean（意思）?</p>", "options": ["Proud.", "Afraid.", "Excited.", "Surprised."], "answer": "D（Surprised.）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Which is TRUE about the reading?</p>", "options": ["The man killed the parrot at last.", "The man kept the parrot to eat on Saturday.", "The parrot was in fact really smart.", "The parrot could not say any word."], "answer": "C（The parrot was in fact really smart.）", "type": "mcq", "correct": 2}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s61", "section": 61, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 121 & 122", "title": "阅读理解", "lessons": "Lesson 121 & 122", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">I had a son named Mike. When he was in the second grade, he saved all his pocket money for over three months to buy holiday presents. On the third Saturday in December, Mike said he had made his list and had twenty dollars in his pocket.</p>\n<p class=\"source-line\">I drove him to a nearby supermarket. Mike picked up a handbasket and went in while I waited and watched from the car. It took Mike over 45 minutes to choose his presents. Finally, he came to the checkout counter and reached into his pocket for his money. It was not there! There was a hole in his pocket, but no money. Mike stood there holding his basket, tears falling down his face.</p>\n<p class=\"source-line\">Then the manager in a hat came and helped him pay for the presents.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">When they got to the supermarket, Mike went in ____.</p>", "options": ["by himself", "with his mother", "with a woman", "with his friends"], "answer": "A（by himself）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">What happened to Mike in the supermarket?</p>", "options": ["His gifts were stolen.", "He broke his basket.", "He lost his money.", "He lost his way."], "answer": "C（He lost his money.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Who paid for Mike's presents at last?</p>", "options": ["His mother.", "Mike himself.", "The manager.", "A woman."], "answer": "C（The manager.）", "type": "mcq", "correct": 2}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Everybody wants to be healthy. You know food is very important to health. There is plenty of healthy food. You can have more bananas, apples, oranges, tomatoes and lettuce because fruit and vegetables are good for you. But don't eat too much chocolate. It's not good for you. Healthy food can make you grow and make you strong and happy. Remember there is a saying, \"An apple a day keeps the doctor away.\" Sports can also keep you healthy. Get up early and do some sports every day. Don't be lazy! You will be healthy and happy.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Which is right?</p>", "options": ["Everybody is healthy.", "We want to be healthy.", "We are important."], "answer": "B（We want to be healthy.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">What is healthy food?</p>", "options": ["Fruit and vegetables.", "Bananas, apples and chocolate.", "Fruit and chocolate."], "answer": "A（Fruit and vegetables.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why is healthy food good for you?</p>", "options": ["It makes you happy.", "It makes you grow strong.", "It makes you grow and makes you strong and happy."], "answer": "C（It makes you grow and makes you strong and happy.）", "type": "mcq", "correct": 2}, {"number": 4, "questionHtml": "<p class=\"source-line\">\"An apple a day keeps the doctor away\" means（意思是）\"____\".</p>", "options": ["The doctor goes away when he sees an apple.", "The doctor runs away when you give him an apple.", "You eat an apple every day and you can be healthy."], "answer": "C（You eat an apple every day and you can be healthy.）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">What keeps you healthy?</p>", "options": ["Fruit and vegetables.", "Healthy food.", "Healthy food and sports."], "answer": "C（Healthy food and sports.）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s62", "section": 62, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 123 & 124", "title": "阅读理解", "lessons": "Lesson 123 & 124", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">There are some boys who think they are already men, and they go to the barber's to be shaved.</p>\n<p class=\"source-line\">Here is one story that happened when John was on a trip to Australia. One day, when he was being shaved in a barbershop, a boy came and asked the barber to shave him. The barber asked him to sit down and soaped his face. Later he left the boy alone. He stood at the door laughing and talking with another barber.</p>\n<p class=\"source-line\">The young gentleman waited for some minutes and then shouted, \"Why are you leaving me here all the time?\"</p>\n<p class=\"source-line\">The barber replied, \"I am waiting until your beard grows.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The boy at the barber's wanted to ____.</p>", "options": ["wash his face", "talk with the barber", "be shaved", "be laughed at"], "answer": "C（be shaved）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why did the barber leave the boy alone?</p>", "options": ["Because he liked laughing.", "Because the boy had no beard.", "Because he liked talking with another barber.", "Because the boy didn't tell the truth."], "answer": "B（Because the boy had no beard.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">How many people were there in the story?</p>", "options": ["2.", "4.", "6.", "10."], "answer": "B（4.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">At last the boy had to ____.</p>", "options": ["go without being shaved", "say sorry to the barber", "go to another barber's", "sit down and wait"], "answer": "A（go without being shaved）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Here are two pictures. A man and a boy are in one picture. Who are they?</p>\n<p class=\"source-line\">Let me tell you. The man is Mr. White, and the boy's name is Bill. He's the man's son. Now they are in Bill's bedroom. We can see some Chinese books on the desk. Bill's shirt is on the bed. His trousers are on the bed under his shirt, too. Now let's look at the other picture. You can see a woman and a girl in it. The woman is Bill's mother, and she's in her daughter Ann's room. You can see a photo of the Whites on the white wall. Between the windows is a desk. A clock is on the desk. It's eleven. What's that on the floor? Oh, it's Ann's hat. But it looks like a brown cat.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">In the two pictures we can see ____.</p>", "options": ["two people", "three people", "four people", "five people"], "answer": "C（four people）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mr. White is ____.</p>", "options": ["Ann's brother", "Ann's father", "Bill's friend", "Bill's teacher"], "answer": "B（Ann's father）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Bill's trousers are ____.</p>", "options": ["on the bed", "in the desk", "on the floor", "under the desk"], "answer": "A（on the bed）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">What colour is Ann's hat?</p>", "options": ["White.", "Red.", "Black.", "Brown."], "answer": "D（Brown.）", "type": "mcq", "correct": 3}, {"number": 5, "questionHtml": "<p class=\"source-line\">In Ann's bedroom we can see a ____ on the desk.</p>", "options": ["cat", "ball", "shirt", "clock"], "answer": "D（clock）", "type": "mcq", "correct": 3}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s63", "section": 63, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 125 & 126", "title": "阅读理解", "lessons": "Lesson 125 & 126", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">All over the world, people have very different ideas about drinking tea.</p>\n<p class=\"source-line\">In China, tea is always served when people get together. The Chinese drink tea at any time of the day at home or in teahouses. They prefer their tea plain with nothing else in it.</p>\n<p class=\"source-line\">The Japanese have a surprising way of serving tea called a tea ceremony. There is a special room for it in Japanese homes.</p>\n<p class=\"source-line\">In England, almost everyone has a cup of tea in the late afternoon. They usually make tea in a teapot by themselves and drink it with milk and sugar. They also eat cakes, cookies and little sandwiches at teatime.</p>\n<p class=\"source-line\">In the United States, people drink tea mostly for breakfast or after meals. Americans usually use tea bags to make their tea. In summer, many Americans drink cold tea—iced tea. Sometimes they drink iced tea from cans, like soda.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Tea is popular ____.</p>", "options": ["all over the world", "only in the United States", "only in English-speaking countries", "in Asian countries"], "answer": "A（all over the world）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">The Chinese drink tea ____.</p>", "options": ["for breakfast", "when people get together", "only in teahouses", "in a special ceremony"], "answer": "B（when people get together）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Iced tea is popular ____.</p>", "options": ["in Japan", "in England", "in Canada", "in the United States"], "answer": "D（in the United States）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">The passage is about ____.</p>", "options": ["why tea is important", "teatime in England", "different ways of drinking tea", "Chinese tea"], "answer": "C（different ways of drinking tea）", "type": "mcq", "correct": 2}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">To start with, put the napkin on your lap. This protects your clothes from food and can be used to wipe your hands or mouth when necessary.</p>\n<p class=\"source-line\">Hold the knife in your right hand and the fork in your left hand, and cut the meat or fish into pieces as you eat. Always use your fork to put food in your mouth. Use your spoon only for soup.</p>\n<p class=\"source-line\">Do not put your own fork, knife or spoon into a serving bowl.</p>\n<p class=\"source-line\">Do not spit food anywhere! If you have bones in your mouth, take them out with your fingers and place them on the edge of your plate, never on the table or floor.</p>\n<p class=\"source-line\">Do not reach across the table or in front of another person. Ask someone to pass whatever you want.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">There are three rules in the passage.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Use your knife and fork to put food in your mouth.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">Place bones on the edge of your plate.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Use spoons for both food and soup.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">If you can't reach the food, ask someone to pass it to you.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s64", "section": 64, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 127 & 128", "title": "阅读理解", "lessons": "Lesson 127 & 128", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Lisa has always been overweight. Her friends and family never made fun of her. They tried to help her instead. They wanted her to be happy and healthy. Sometimes when Lisa was feeling sad, she didn't want to speak to anyone.</p>\n<p class=\"source-line\">But now things are quite different. Last month her classmates were preparing for the School Art Week. Someone advised Lisa to play the lead role of the proud Queen, who was tall and fat. Lisa agreed and practised a lot.</p>\n<p class=\"source-line\">Soon after the play, Lisa became the star! She did so well that everybody remembered the proud Queen. She even won the School Best Actress Award for her wonderful performance.</p>\n<p class=\"source-line\">Now Lisa doesn't worry about being fat any more. She believes in the English saying \"Every dog has its day.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Who is Lisa?</p>", "options": ["A little baby.", "A queen.", "A mother.", "A student."], "answer": "D（A student.）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why was Lisa feeling sad sometimes?</p>", "options": ["Because her friends made fun of her.", "Because her family made fun of her.", "Because she was fat.", "Because she couldn't tell the truth."], "answer": "C（Because she was fat.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why doesn't Lisa worry about being fat any more?</p>", "options": ["Because she has lost weight.", "Because being fat made her succeed.", "Because she has a lot of friends.", "Because she is good at studying."], "answer": "B（Because being fat made her succeed.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">What did Lisa win?</p>", "options": ["The School Best Actress Award.", "Friendship.", "A lot of money.", "A real queen."], "answer": "A（The School Best Actress Award.）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Jackie Chan is a great movie star. He has made many good action movies. People all over the world like him and his movies because he can do Chinese kung fu very well. Jackie Chan also works hard to raise money for poor children. Many young men see Jackie Chan as their hero. Jackie Chan is my favourite actor. I like his movies very much. They are exciting and funny. My friends all like him, too. And they often go to see his movies with me on Sundays.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Jackie Chan is a famous（著名的）____.</p>", "options": ["singer", "action actor", "policeman", "doctor"], "answer": "B（action actor）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">People all over the world like Jackie Chan because ____.</p>", "options": ["he is a funny man", "he can do Chinese kung fu", "he is a famous singer", "he is exciting"], "answer": "B（he can do Chinese kung fu）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">The writer（作者）thinks Jackie Chan ____.</p>", "options": ["is a good man", "isn't an actor", "is a funny man", "is not great at all"], "answer": "A（is a good man）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Do the writer's friends like Jackie Chan?</p>", "options": ["Yes, they don't.", "Yes, they do.", "No, they do.", "No, they don't."], "answer": "B（Yes, they do.）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">The writer and his friends often see the movies on ____.</p>", "options": ["weekdays", "Mondays", "Sundays", "Saturdays"], "answer": "C（Sundays）", "type": "mcq", "correct": 2}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s65", "section": 65, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 129 & 130", "title": "阅读理解", "lessons": "Lesson 129 & 130", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mr. Smith and his wife had a third child last year. This made them sell their second car and buy a van. The sixth and seventh seats are used to put other things, for a family of five must carry many suitcases when they travel. When they arrive at their grandparents' home, the suitcases are taken out and the two seats can then carry the grandparents.</p>\n<p class=\"source-line\">Americans call vans motor homes. A motor home is often used for holidays. When a family is travelling to the mountains or to the seaside, they can live in their motor home for a few days. All the members of a big family can enjoy a happier life when they are travelling together. That is why motor homes have become very popular. In America there are many parks for motor homes.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">From the passage, a van is also called ____.</p>", "options": ["a motor car", "a motor home", "a motorbike", "a big truck"], "answer": "B（a motor home）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Before Mr. Smith and his wife bought a van, they ____.</p>", "options": ["sold their old house", "moved to their grandparents' house", "built a new place for a van", "sold their second car"], "answer": "D（sold their second car）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Americans usually use motor homes ____.</p>", "options": ["to travel with all the family members", "to do some shopping with all the family members", "to visit their grandparents at weekends", "to drive their children to school every day"], "answer": "A（to travel with all the family members）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">Motor homes have become popular because ____.</p>", "options": ["they can take people to another city when people are free", "they can let families have a happier life when they go out for their holidays", "some people think motor homes are cheap", "big families can put more things in motor homes"], "answer": "B（they can let families have a happier life when they go out for their holidays）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Many people like to travel by plane, but I don't like it because an airport is usually far from the city. You have to get there early and wait for hours for the plane to take off, and it is often late. You can't open the window. You can't choose the food. Planes are fast, but it still takes hours to get out of the airport and into the city.</p>\n<p class=\"source-line\">I like travelling by train. I think trains are safe. Railway stations are usually in cities. When you are late for a train, you can catch another one. You can walk around on the train and open the windows. You can see many interesting things on your way. I know it takes a little more time.</p>\n<p class=\"source-line\">I also like cars. You can start your journey when you want to, and you don't need to get to a railway station or a bus stop. Also, you can carry many things with you in a car. But sometimes there are too many cars on the road.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Why do many people like to travel by plane?</p>", "options": ["Because it is fast.", "Because it is safe.", "Because you can walk around on the plane."], "answer": "A（Because it is fast.）", "type": "mcq", "correct": 0}, {"number": 2, "questionHtml": "<p class=\"source-line\">Which is NOT a good thing about the train?</p>", "options": ["It is safe.", "It takes a little more time.", "You can open the windows."], "answer": "B（It takes a little more time.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">If you want to take a lot of things with you, what do you take to go out?</p>", "options": ["A bus.", "A car.", "A train."], "answer": "B（A car.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">What is the bad thing about the car?</p>", "options": ["You don't need to go to a station.", "You can start your journey when you want to.", "There are too many cars on the road."], "answer": "C（There are too many cars on the road.）", "type": "mcq", "correct": 2}, {"number": 5, "questionHtml": "<p class=\"source-line\">What does the writer think of the plane, train and car?</p>", "options": ["He thinks it takes a lot of time to get to and out of the airport.", "He likes to take a train because it takes a little more time.", "He likes to take a car because he has a car."], "answer": "A（He thinks it takes a lot of time to get to and out of the airport.）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s66", "section": 66, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 131 & 132", "title": "阅读理解", "lessons": "Lesson 131 & 132", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Long, long ago, there was a man and his wife who both worked for an old man as servants. One day, the old man pointed to a big box in his living room and said, \"There's only one thing you mustn't do: don't open this box.\" After saying this, he left home.</p>\n<p class=\"source-line\">The woman said to her husband, \"There must be something expensive in the box. Let's open it, shall we?\" Her husband didn't want to do that, but the woman didn't give up.</p>\n<p class=\"source-line\">A few days later, the woman made a decision to find out what was in the box. Before her husband could stop her, she had opened the box and looked into it. To her surprise, there was nothing in it. She tried hard to close the box, but she failed.</p>\n<p class=\"source-line\">That evening, the old man came home and found that the box was open. He was very angry and asked the woman and her husband to leave his home at once.</p>\n<p class=\"source-line\">\"But there was nothing in the box,\" the woman said. \"We haven't taken anything at all.\"</p>\n<p class=\"source-line\">The old man shouted, \"The box is not important. Now I know that I can't trust you. That's what's important!\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">How many people were there in the story?</p>", "options": ["Only one.", "Two.", "Three.", "Four."], "answer": "C（Three.）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">What's the relationship between the old man and the couple?</p>", "options": ["Friends.", "Family members.", "Teacher and students.", "Employer and employees."], "answer": "D（Employer and employees.）", "type": "mcq", "correct": 3}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why did the old man tell the couple not to open the box?</p>", "options": ["Because there was a lot of money in it.", "Because there was nothing in the box.", "Because he wanted to see whether he could trust the couple.", "Because he wanted to give the couple a surprise."], "answer": "C（Because he wanted to see whether he could trust the couple.）", "type": "mcq", "correct": 2}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> An Old Man</h4>\n<p class=\"source-line\">It is a beautiful autumn morning. It is sunny and cool. Bob is surprised when he finds an old man at the bus stop with a big, strong umbrella in his hand.</p>\n<p class=\"source-line\">Bob says to him, \"Is it going to rain?\" \"No,\" says the old man. \"I don't think so. I am an old man, so I really need a walking stick. When I carry a walking stick, people will say, 'Look at that poor old man.' And I don't want to be like that. When I carry an umbrella in fine weather, people only say, 'Look at that foolish man.'\"</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">It is a spring morning.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">It is warm.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">An old man carries an umbrella with him on a sunny morning.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">The old man takes a walking stick.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">The old man doesn't want to be seen as a poor old man.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s67", "section": 67, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 133 & 134", "title": "阅读理解", "lessons": "Lesson 133 & 134", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Our eating habits are important for good health and a strong body. Most of us would rather eat sweets and ice cream than meat and rice. Sweets and ice cream are not bad if we eat them at the end of a meal. If we eat them before a meal, they may take away our appetite. It is important for us to eat our meals at the same time each day.</p>\n<p class=\"source-line\">When we feel hungry, it is a sign that our body needs food. When we feel angry or excited, we may not want to eat.</p>\n<p class=\"source-line\">Once a reporter reported a sensational story: a long time ago, in England, some judges used to decide whether a man was telling the truth by giving him some dry bread. If the man could not eat the bread, it showed that he was telling lies. Although this seems very strange and rather foolish, it is indeed a very good way to find out the truth. A man who is worrying about something has difficulty eating anything dry. Because he is worrying, he loses his appetite and does not want to eat.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">It is not bad to eat sweets and ice cream ____.</p>", "options": ["when we are hungry", "after the meal", "when we want to", "before the meal"], "answer": "B（after the meal）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">According to the judges in England, if a man tells a lie, he ____.</p>", "options": ["eats dry bread easily", "eats dry bread with difficulty", "eats a lot of dry bread", "drinks milk with difficulty"], "answer": "B（eats dry bread with difficulty）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">A man who is angry ____.</p>", "options": ["has a better appetite", "likes to tell lies", "likes to eat ice cream", "has a poor appetite"], "answer": "D（has a poor appetite）", "type": "mcq", "correct": 3}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Mr. Green is my uncle. He has a house with a big garden. There are some orange trees in this garden. He looks after them. Now there are many oranges on the trees and my uncle is very happy.</p>\n<p class=\"source-line\">One afternoon, when he looks out of the window, he sees a boy in a red T-shirt in his orange tree. He opens the window and shouts, \"Hey, what are you doing there? Come down, or I'll go to see your father.\"</p>\n<p class=\"source-line\">The boy is not afraid of my uncle at all. \"Dad,\" he looks up and shouts, \"Mr. Green wants to see you.\" My uncle smiles. \"Ha-ha, it's my son Dave.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Mr. Green has a ____.</p>", "options": ["big zoo", "big park", "big garden", "big office"], "answer": "C（big garden）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mr. Green is very happy because ____.</p>", "options": ["he has a good friend", "he has a son", "there are many oranges on the trees", "his son is smart"], "answer": "C（there are many oranges on the trees）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">Why does Mr. Green want to see the boy's father?</p>", "options": ["Because the boy's father is ill.", "Because they are friends.", "Because he thinks the boy helps him a lot.", "Because he thinks the boy is stealing（偷）his oranges."], "answer": "D（Because he thinks the boy is stealing his oranges.）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">From the passage we know Dave is ____.</p>", "options": ["Mr. Green's son", "wearing a black T-shirt", "a high school student", "Mr. Green's uncle"], "answer": "A（Mr. Green's son）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">Which of the following is TRUE?</p>", "options": ["Dave is afraid of Mr. Green.", "Mr. Green has bad eyesight（视力）.", "Dave is under the orange tree.", "Mr. Green doesn't like his orange trees."], "answer": "B（Mr. Green has bad eyesight.）", "type": "mcq", "correct": 1}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s68", "section": 68, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 135 & 136", "title": "阅读理解", "lessons": "Lesson 135 & 136", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">At the age of almost four, Elijah Edney has never had a haircut in his life.</p>\n<p class=\"source-line\">But now he says that he no longer wants to have rock-star hair and wants to look like his elder brother. Losing his two-foot-long golden hair will mean that strangers stop mistaking him for a girl.</p>\n<p class=\"source-line\">Mrs. Edney and her husband, Dean Edney, want to collect enough money—£350—to transform their son's hair into a wig for a child with cancer or another condition.</p>\n<p class=\"source-line\">Mrs. Edney said, \"I couldn't stand seeing all Elijah's beautiful hair go to waste, and my mum mentioned charities that use human hair to make wigs. Elijah keeps telling people he is going to give his hair to the Little Princess Trust, and he is so excited to get it done.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Who is Elijah Edney?</p>", "options": ["A little girl.", "A little boy.", "A mother.", "A father."], "answer": "B（A little boy.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why does Elijah have his hair made into wigs?</p>", "options": ["Because he wants to look like his elder brother.", "Because he no longer wants to have rock-star hair.", "Because he is giving his hair to the Little Princess Trust.", "All of the above."], "answer": "C（Because he is giving his hair to the Little Princess Trust.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">How old is the boy?</p>", "options": ["Almost 2.", "Almost 4.", "Almost 6.", "Almost 10."], "answer": "B（Almost 4.）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">How much money is needed to transform the hair into a wig?</p>", "options": ["¥150.", "¥250.", "£350.", "¥350."], "answer": "C（£350.）", "type": "mcq", "correct": 2}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">In America, just as in Europe, men usually open doors for women, and women always walk ahead of men into a room or a restaurant, unless the men have to go ahead of the ladies to choose the table, open the door of a car or do something similar. On the street, men almost always walk or cross the street on the side of the ladies closer to the traffic. But if a man walks with two ladies, he should walk between them. If the host or hostess, or both of them, come in a car to get their guest for dinner, the guest should sit in the front seat and leave the back seat empty even if no one is sitting there.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">In America men usually ____.</p>", "options": ["walk ahead of women", "eat in a restaurant", "walk behind women", "drive a car to work"], "answer": "C（walk behind women）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">In the street men ____.</p>", "options": ["cross the street", "walk on the right side of the ladies", "walk on the side of the ladies closer to the traffic", "walk near the ladies"], "answer": "C（walk on the side of the ladies closer to the traffic）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">If a man walks with two ladies, he should ____.</p>", "options": ["walk between them", "run before them", "follow them", "go away"], "answer": "A（walk between them）", "type": "mcq", "correct": 0}, {"number": 4, "questionHtml": "<p class=\"source-line\">If Mrs. Green wants you to go to her house in a car, you should ____.</p>", "options": ["sit beside a guest", "sit in the front seat", "sit in the back seat", "drive the car"], "answer": "B（sit in the front seat）", "type": "mcq", "correct": 1}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s69", "section": 69, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 137 & 138", "title": "阅读理解", "lessons": "Lesson 137 & 138", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Dennis Tito, a billionaire financier who in 2001 became the first space tourist, has launched a project to send two civilians on \"a historic journey\" to the Red Planet in January 2018. The mission, a \"return fly-by\" in which the spacecraft would fly around Mars rather than land, would last for 500 days.</p>\n<p class=\"source-line\">He said that if a man and a woman were on such a long voyage, it would make sense for them to be married so that they could give each other the emotional support that would probably be needed when they looked out of the window and saw Earth getting smaller and more distant. He added, \"If that's not scary, I don't know what is.\"</p>\n<p class=\"source-line\">He said that one of the questions he hoped to help answer was, \"How do humans behave when they look out and see this pale blue dot that can barely be distinguished from a star?\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Who will be sent to the Red Planet?</p>", "options": ["Dennis Tito.", "A couple.", "Monkeys.", "Two men and a woman."], "answer": "B（A couple.）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">What did Dennis want to do?</p>", "options": ["He wanted to be famous.", "To see how humans behave there.", "He wanted to make a joke.", "To live alone."], "answer": "B（To see how humans behave there.）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">How long will the historic journey last?</p>", "options": ["3 months.", "Half a year.", "A year.", "About a year and a half."], "answer": "D（About a year and a half.）", "type": "mcq", "correct": 3}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">Have you ever dreamed of having a robot? It will do everything that you order it to do. Every morning it wakes you up and cooks breakfast when you are still in bed. After breakfast, it washes the dishes and does the cleaning. In a word, it does everything for your family. It works day and night all year round. After dinner, it even helps you do your homework and study on the eve of an exam.</p>\n<p class=\"source-line\">It never becomes tired or sick and, most of all, never complains. In the near future, you will see many changes that you cannot even dream of now.</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">What is a robot?</p>", "options": ["A man.", "An animal.", "A bin.", "A machine."], "answer": "D（A machine.）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">What does the word \"him\" mean in the second sentence?</p>", "options": ["The speaker.", "The dream.", "The robot.", "The world."], "answer": "C（The robot.）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">The robot ____ gets tired or sick.</p>", "options": ["often", "never", "always", "usually"], "answer": "B（never）", "type": "mcq", "correct": 1}], "questionCount": 3, "hasAnswers": true}]}, {"id": "s70", "section": 70, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 139 & 140", "title": "阅读理解", "lessons": "Lesson 139 & 140", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">John went to university to study history, but at the end of his first year, his history professor failed him in his exam, and John would have to leave the university. However, his father decided that he would go to see the professor to urge him to let John continue his studies the following year.</p>\n<p class=\"source-line\">\"He's a good boy,\" said his father, \"and if you let him pass this time, I'm sure he'll improve a lot next year and pass the exam at the end of it.\"</p>\n<p class=\"source-line\">\"No, no, that's quite impossible,\" said the professor at once. \"Do you know, last month I asked him when Napoleon died, and he didn't know!\"</p>\n<p class=\"source-line\">\"Please, sir, give him another chance,\" said John's father. \"You see, I'm afraid we don't take any newspapers in our house, so none of us even knew that Napoleon was ill.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">John would have to leave the university because ____.</p>", "options": ["he didn't like history", "he didn't pass the exam", "he was a good boy", "he didn't know Napoleon was ill"], "answer": "B（he didn't pass the exam）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">John's father wanted the professor ____.</p>", "options": ["to tell him a story", "to give John a lesson", "to let John continue his studies", "to let John leave the university"], "answer": "C（to let John continue his studies）", "type": "mcq", "correct": 2}, {"number": 3, "questionHtml": "<p class=\"source-line\">The underlined word \"it\" means \"____\".</p>", "options": ["John's exam", "the university", "John's first year", "John's second year"], "answer": "D（John's second year）", "type": "mcq", "correct": 3}, {"number": 4, "questionHtml": "<p class=\"source-line\">John didn't know when Napoleon died because ____.</p>", "options": ["he didn't do well in history", "he didn't take any newspapers", "he didn't know Napoleon", "he didn't like Napoleon"], "answer": "A（he didn't do well in history）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> She Is Looking for Me</h4>\n<p class=\"source-line\">Mr. Jones and Mr. Green work in the same office. One day, Mr. Jones says to Mr. Green, \"I will have a small party at our house on Tuesday evening. Would you and your wife like to come?\"</p>\n<p class=\"source-line\">Mr. Green says, \"Thank you very much. I'd love to, but let me ask my wife first.\" So Mr. Green goes to the other room and telephones his wife. Then he comes back and looks very worried.</p>\n<p class=\"source-line\">\"What's the matter?\" asks Mr. Jones. \"Is your wife at home?\"</p>\n<p class=\"source-line\">\"No,\" answers Mr. Green. \"She isn't there. My little son answered the telephone. I said to him, 'Is your mother there, David?' and he answered, 'No, she isn't in the house.' 'Where is she?' I asked. 'She is somewhere outside.' 'What's she doing?' 'She is looking for me.'\"</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">There is a party at Mr. Jones's house on Monday evening.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mr. Jones asks Mr. Green and his wife to go to the party.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">The telephone is in Mr. Green's office.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Mr. Green speaks to Mrs. Green on the telephone.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 5, "questionHtml": "<p class=\"source-line\">Mrs. Green is looking for her son.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 5, "hasAnswers": true}]}, {"id": "s71", "section": 71, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 141 & 142", "title": "阅读理解", "lessons": "Lesson 141 & 142", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> Safety Concerns Keep Paris Tourists Away</h4>\n<p class=\"source-line\">There is a joke on Weibo saying, \"There are two types of Chinese people in Paris—those who have been robbed and those who will be.\"</p>\n<p class=\"source-line\">Last month I was on business in Paris. I was excited to arrive, but I was curious to find that there were three locks on my apartment door when I moved in. I thought my landlord must be a very cautious person obsessed with security. But now I understand.</p>\n<p class=\"source-line\">Every day I make sure that all three locks on my door are securely bolted before I leave. I am always very careful when I go out. I wish I had eyes in the back of my head when I walk alone at night. I am scared to answer my iPhone or use it to check messages and emails. I never wear high heels, just in case I need to run if something bad happens.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The writer was born in Paris.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">The writer always thinks it's safe to live in Paris.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 3, "questionHtml": "<p class=\"source-line\">One should pay close attention to security in Paris.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> A Small Girl</h4>\n<p class=\"source-line\">A mother and her young girl get on a bus and sit down. The bus conductor comes to them for their tickets. The mother says, \"Give me one ticket to New York.\" And she gives the conductor a dollar.</p>\n<p class=\"source-line\">The conductor looks at the small girl for a few minutes and then says to her, \"How old are you?\"</p>\n<p class=\"source-line\">The mother wants to speak, but the conductor stops her, and the girl says, \"I'm four years old at home, and two and a half on buses and trains.\"</p>\n<p class=\"source-line\">The mother takes half a dollar out of her bag and gives it to the conductor. The conductor gives her one and a half tickets.</p>\n<p class=\"source-line\">根据短文内容判断对（T）错（F）。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The girl is two and a half years old.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 2, "questionHtml": "<p class=\"source-line\">The girl's mother gives the conductor one and a half dollars.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">The girl's mother buys two tickets.</p>", "options": ["正确（T）", "错误（F）"], "answer": "B（F）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">The girl's mother didn't want to buy a ticket for the young girl at first.</p>", "options": ["正确（T）", "错误（F）"], "answer": "A（T）", "type": "mcq", "correct": 0}], "questionCount": 4, "hasAnswers": true}]}, {"id": "s72", "section": 72, "unit": 1, "unitName": "第一册阅读练习", "short": "Lesson 143 & 144", "title": "阅读理解", "lessons": "Lesson 143 & 144", "knowledgeHtml": "", "grammarHtml": "", "notesHtml": "", "exerciseGroups": [{"title": "基础阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<h4 style=\"margin-top: 0; margin-bottom: 16px; font-size: 18px; text-align: center; color: var(--ink); font-weight: bold;\"> Oxford Graduate in the Hills</h4>\n<p class=\"source-line\">Believe it or not, but the Daily Mail of London reported that an Oxford graduate chose to live in the hills.</p>\n<p class=\"source-line\">An Oxford graduate has left society and lived in a mud roundhouse surrounded by beautiful woods in the Welsh hills for 13 years. It is not a famous beauty spot. Fifty-eight-year-old Emma Orbach has lived without electricity in her self-built house, generating her own power and growing her own food. She named her home \"Spirit Land,\" where she doesn't use any technology.</p>\n<p class=\"source-line\">Emma said, \"This is how I want to live. Every day I can freely do what I want in the woods. This lifestyle makes me feel really happy and peaceful, and this is my ideal home.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">Who lives in the hills?</p>", "options": ["An Oxford graduate.", "Emma Orbach.", "A 58-year-old lady.", "All of the above."], "answer": "D（All of the above.）", "type": "mcq", "correct": 3}, {"number": 2, "questionHtml": "<p class=\"source-line\">Why did Emma choose to live in the hills?</p>", "options": ["Because she likes the lifestyle very much.", "Because she can tell the truth.", "Because she was poor.", "Because she can't tell the truth."], "answer": "A（Because she likes the lifestyle very much.）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">When did Emma start to live in the hills?</p>", "options": ["At 25.", "At 35.", "At 45.", "At 55."], "answer": "C（At 45.）", "type": "mcq", "correct": 2}], "questionCount": 3, "hasAnswers": true}, {"title": "提高阅读", "questionsHtml": "", "answersHtml": "", "preambleHtml": "<p class=\"source-line\">The students were having their chemistry（化学）class. Mr. Li was telling the children what water was like. After that, he asked his students, \"What's water?\" No one spoke for a few minutes. Mr. Li asked again, \"Why don't you answer my question? Didn't I tell you what water is like?\"</p>\n<p class=\"source-line\">Just then a boy put up his hand and said, \"Mr. Li, you told us that water has no colour and no smell. But where can we find such water? The water in the river behind my house is always black and it has a bad smell.\" Most of the children agreed with him.</p>\n<p class=\"source-line\">\"I'm sorry, children,\" said the teacher. \"Our water is getting dirtier and dirtier. That's a problem.\"</p>\n<p class=\"source-line\">根据短文内容，选择最佳选项。</p>\n", "items": [{"number": 1, "questionHtml": "<p class=\"source-line\">The students were having their ____ class.</p>", "options": ["English", "Chinese", "chemistry", "maths"], "answer": "C（chemistry）", "type": "mcq", "correct": 2}, {"number": 2, "questionHtml": "<p class=\"source-line\">Mr. Li was telling the children what ____ was like.</p>", "options": ["water", "air", "earth", "weather"], "answer": "A（water）", "type": "mcq", "correct": 0}, {"number": 3, "questionHtml": "<p class=\"source-line\">A boy said, \"The water in the river behind my house is always ____.\"</p>", "options": ["white", "black", "clean", "clear"], "answer": "B（black）", "type": "mcq", "correct": 1}, {"number": 4, "questionHtml": "<p class=\"source-line\">Most of the children ____ the boy.</p>", "options": ["agreed with", "wrote to", "heard from", "sent for"], "answer": "A（agreed with）", "type": "mcq", "correct": 0}, {"number": 5, "questionHtml": "<p class=\"source-line\">The water in the river has colour and smell because it is getting ____.</p>", "options": ["more and more", "less and less", "cleaner and cleaner", "dirtier and dirtier"], "answer": "D（dirtier and dirtier）", "type": "mcq", "correct": 3}], "questionCount": 5, "hasAnswers": true}]}];
(function clientRuntime() {
  const $ = (id) => document.getElementById(id);
  const escapeHtml = (value) =>
    String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  const storageKey = "new-concept-grammar-72-v1";
  let curUnit = 1;
  let curSec = DATA[0].id;
  let state = { solved: {}, work: {}, stars: {}, vocab: {}, highlights: {} };
  let pendingHighlight = null;

  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) || "{}");
    state.solved = saved.solved || {};
    state.work = saved.work || {};
    state.stars = saved.stars || {};
    state.vocab = saved.vocab || {};
    state.highlights = saved.highlights || {};
  } catch (error) {
    state = { solved: {}, work: {}, stars: {}, vocab: {}, highlights: {} };
  }

  function saveState() {
    try {
      localStorage.setItem(storageKey, JSON.stringify(state));
    } catch (error) {
      // Local files or privacy settings may block storage; the page still works in-memory.
    }
  }

  function solvedSet(id) {
    return new Set(state.solved[id] || []);
  }

  function setSolved(id, values) {
    state.solved[id] = [...values].sort();
    saveState();
  }

  function totalOf(section) {
    return section.exerciseGroups.reduce(
      (sum, group) => sum + (group.items.length || 1),
      0
    );
  }

  function itemKey(groupIndex, itemIndex) {
    return `${groupIndex}-${itemIndex}`;
  }

  function highlightKey(sectionId, groupIndex) {
    return `${sectionId}-${groupIndex}`;
  }

  function mergeHighlightRanges(ranges) {
    return ranges
      .filter((range) => Number.isInteger(range.start) && Number.isInteger(range.end) && range.end > range.start)
      .sort((a, b) => a.start - b.start)
      .reduce((merged, range) => {
        const previous = merged[merged.length - 1];
        if (previous && range.start <= previous.end) {
          previous.end = Math.max(previous.end, range.end);
        } else {
          merged.push({ start: range.start, end: range.end });
        }
        return merged;
      }, []);
  }

  function unwrapStudyHighlights(container) {
    container.querySelectorAll("mark.study-highlight").forEach((mark) => {
      mark.replaceWith(...mark.childNodes);
    });
    container.normalize();
  }

  function applyHighlights(container) {
    const key = container.dataset.highlightKey;
    unwrapStudyHighlights(container);
    const ranges = mergeHighlightRanges(state.highlights[key] || []);
    state.highlights[key] = ranges;
    if (!ranges.length) return;

    const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
    const textNodes = [];
    let offset = 0;
    let node;
    while ((node = walker.nextNode())) {
      const length = node.nodeValue.length;
      textNodes.push({ node, start: offset, end: offset + length });
      offset += length;
    }

    textNodes.forEach((entry) => {
      const segments = ranges
        .map((range) => ({
          start: Math.max(range.start, entry.start) - entry.start,
          end: Math.min(range.end, entry.end) - entry.start,
          rangeStart: range.start,
          rangeEnd: range.end,
        }))
        .filter((segment) => segment.end > segment.start)
        .sort((a, b) => b.start - a.start);

      segments.forEach((segment) => {
        entry.node.splitText(segment.end);
        const selectedText = entry.node.splitText(segment.start);
        const mark = document.createElement("mark");
        mark.className = "study-highlight";
        mark.dataset.highlightKey = key;
        mark.dataset.highlightStart = String(segment.rangeStart);
        mark.dataset.highlightEnd = String(segment.rangeEnd);
        selectedText.replaceWith(mark);
        mark.appendChild(selectedText);
      });
    });
  }

  function restoreHighlights() {
    $("main").querySelectorAll(".highlightable-passage").forEach(applyHighlights);
  }

  function captureHighlightSelection() {
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0 || selection.isCollapsed) return;
    const range = selection.getRangeAt(0);
    const ancestor = range.commonAncestorContainer.nodeType === Node.ELEMENT_NODE
      ? range.commonAncestorContainer
      : range.commonAncestorContainer.parentElement;
    const container = ancestor && ancestor.closest(".highlightable-passage");
    if (!container || !container.contains(range.startContainer) || !container.contains(range.endContainer)) return;

    const before = document.createRange();
    before.selectNodeContents(container);
    before.setEnd(range.startContainer, range.startOffset);
    const start = before.toString().length;
    const end = start + range.toString().length;
    if (end <= start) return;

    pendingHighlight = { key: container.dataset.highlightKey, start, end };
    $("main").querySelectorAll("[data-highlight-add]").forEach((button) => {
      const selectedHere = button.dataset.highlightAdd === pendingHighlight.key;
      button.disabled = !selectedHere;
      button.textContent = selectedHere ? "🖍️ 高亮选中内容" : "先选择原文";
    });
  }

  function addPendingHighlight(key) {
    if (!pendingHighlight || pendingHighlight.key !== key) return;
    const ranges = state.highlights[key] || [];
    ranges.push({ start: pendingHighlight.start, end: pendingHighlight.end });
    state.highlights[key] = mergeHighlightRanges(ranges);
    saveState();
    const container = $("main").querySelector(`.highlightable-passage[data-highlight-key="${key}"]`);
    if (container) applyHighlights(container);
    pendingHighlight = null;
    window.getSelection()?.removeAllRanges();
    const button = $("main").querySelector(`[data-highlight-add="${key}"]`);
    if (button) {
      button.disabled = true;
      button.textContent = "先选择原文";
    }
  }

  function undoLastHighlight(key) {
    const ranges = state.highlights[key] || [];
    if (!ranges.length) return;
    ranges.pop();
    state.highlights[key] = ranges;
    saveState();
    const container = $("main").querySelector(`.highlightable-passage[data-highlight-key="${key}"]`);
    if (container) applyHighlights(container);
  }

  function clearPassageHighlights(key) {
    if (!(state.highlights[key] || []).length) return;
    if (!confirm("确定要清除这篇原文的全部高亮吗？")) return;
    state.highlights[key] = [];
    saveState();
    const container = $("main").querySelector(`.highlightable-passage[data-highlight-key="${key}"]`);
    if (container) applyHighlights(container);
  }

  function speak(text) {}

  function buildNav() {
    let topActionsHtml = `<button class="unit-tab${curUnit !== 'stars' && curUnit !== 'vocab' ? " on" : ""}" data-u="reading">阅读练习</button>`;
    
    if ($("top-actions")) {
      $("top-actions").innerHTML = topActionsHtml + 
        `<button class="unit-tab${curUnit === 'stars' ? " on" : ""}" style="color:#B96A00;background:${curUnit==='stars'?'#FFF3E2':'transparent'};border:1px solid #FFF3E2" data-u="stars">⭐ 错题本</button>` + 
        `<button class="unit-tab${curUnit === 'vocab' ? " on" : ""}" style="color:#0EA5E9;background:${curUnit==='vocab'?'#E0F2FE':'transparent'};border:1px solid #E0F2FE" data-u="vocab">📖 生词本</button>`;
      
      $("top-actions").querySelectorAll(".unit-tab").forEach(button => {
        button.onclick = () => {
          const u = button.dataset.u;
          if (u === "stars") {
            curUnit = "stars";
            if (typeof renderStars === 'function') renderStars();
          } else if (u === "vocab") {
            curUnit = "vocab";
            if (typeof renderVocabBook === 'function') renderVocabBook();
          } else {
            curUnit = 1;
            curSec = DATA[0].id;
            render();
          }
        };
      });
    }

    if (curUnit !== 'stars' && curUnit !== 'vocab') {
        let selectHtml = `<select id="navSelect" style="width: 100%; padding: 8px 12px; border-radius: 8px; border: 1px solid var(--line); font-size: 15px; outline: none; background: #fff; color: var(--ink);">`;
        DATA.forEach((section) => {
          const count = solvedSet(section.id).size;
          const done = count >= totalOf(section) && totalOf(section) > 0;
          const selected = section.id === curSec ? "selected" : "";
          selectHtml += `<option value="${section.id}" ${selected}>${section.short} ${section.title} ${done ? "✓" : ""}</option>`;
        });
        selectHtml += `</select>`;
        
        $("chips").innerHTML = selectHtml;
        $("chips").style.padding = "10px 18px 12px";

        $("navSelect").onchange = (e) => {
          curSec = e.target.value;
          render();
          window.scrollTo({ top: 0, behavior: "smooth" });
        };
    } else {
        $("chips").innerHTML = "";
    }
    
    if ($("units")) $("units").style.display = "none";
  }

  function feedbackHtml(secId, groupIndex, itemIndex) {
    return `<div class="fb" id="feedback-${secId}-${groupIndex}-${itemIndex}"></div>`;
  }

  function practiceItemHtml(section, item, groupIndex, itemIndex) {
    const isStarred = (state.stars[section.id] || []).includes(itemKey(groupIndex, itemIndex));
    const starBtn = `<button class="star-btn${isStarred ? " on" : ""}" type="button" data-star="${section.id}|${itemKey(groupIndex, itemIndex)}" title="收藏本题">⭐</button>`;
    const key = itemKey(groupIndex, itemIndex);
    const done = solvedSet(section.id).has(key);
    const workKey = `${section.id}-${key}`;
    if (item.type === "mcq") {
      const options = item.options
        .map(
          (option, optionIndex) =>
            `<button class="opt" type="button" data-mcq="${section.id}|${groupIndex}-${itemIndex}" data-option="${optionIndex}">
              ${String.fromCharCode(65 + optionIndex)}. ${option}
            </button>`
        )
        .join("");
      return `<div class="q exercise-item${done ? " is-done" : ""}" id="item-${section.id}-${key}">
        <div class="qt"><b>${item.number}.</b> ${starBtn}<div class="question-body">${item.questionHtml}</div></div>
        <div class="opts">${options}</div>
        <div class="group-actions" style="display:flex; justify-content: space-between; align-items: center; width: 100%;">
          ${item.correct === null ? `<button class="btn done-btn${done ? " on" : ""}" type="button" data-manual="${section.id}|${key}">${done ? "✓ 已完成本题" : "标记本题完成"}</button>` : "<div></div>"}
          ${curUnit === 'stars' ? `<button class="btn" type="button" data-star="${section.id}|${key}" style="color:#B96A00; background:#FFF3E2;">🗑️ 移出错题本</button>` : ""}
        </div>
        ${feedbackHtml(section.id, groupIndex, itemIndex)}
      </div>`;
    }

    const answerButtons = item.answer
      ? `<button class="btn p" type="button" data-check="${section.id}|${key}">检查</button>
         <button class="btn s" type="button" data-show="${section.id}|${key}">看答案</button>`
      : `<button class="btn done-btn${done ? " on" : ""}" type="button" data-manual="${section.id}|${key}">
           ${done ? "✓ 已完成本题" : "标记本题完成"}
         </button>
         <button class="btn s" type="button" disabled>原文未列答案</button>`;
    return `<div class="q exercise-item${done ? " is-done" : ""}" id="item-${section.id}-${key}">
      <div class="qt"><b>${item.number}.</b> ${starBtn}<div class="question-body">${item.questionHtml}</div></div>
      <div class="row" style="display:flex; flex-wrap:wrap; gap:8px;">
        <input type="text" class="item-input" id="input-${section.id}-${key}" data-input="${section.id}|${key}"
          value="${escapeHtml(state.work[workKey] || "")}" placeholder="在这里填写答案…" autocomplete="off" spellcheck="false" style="flex:1;">
        ${answerButtons}
        ${curUnit === 'stars' ? `<button class="btn" type="button" data-star="${section.id}|${key}" style="color:#B96A00; background:#FFF3E2;">🗑️ 移出错题本</button>` : ""}
      </div>
      ${feedbackHtml(section.id, groupIndex, itemIndex)}
    </div>`;
  }

  function fallbackGroupHtml(section, group, groupIndex) {
    const key = itemKey(groupIndex, 0);
    const done = solvedSet(section.id).has(key);
    const workKey = `${section.id}-${key}`;
    return `<div class="q exercise-item${done ? " is-done" : ""}" id="item-${section.id}-${key}">
      <div class="source-content">${group.questionsHtml}</div>
      <label class="work-label" for="work-${key}">我的作答（自动保存在本浏览器）</label>
      <textarea class="workpad" id="work-${key}" data-fallback="${key}" placeholder="在这里写下答案、改写后的句子或翻译……">${escapeHtml(
        state.work[workKey] || ""
      )}</textarea>
      <div class="group-actions">
        <button class="btn done-btn${done ? " on" : ""}" type="button" data-manual="${section.id}|${key}">
          ${done ? "✓ 已完成本组" : "标记本组完成"}
        </button>
      </div>
      ${group.hasAnswers ? `<div class="answer-panel source-content"><div class="answer-label">参考答案</div>${group.answersHtml}</div>` : ""}
    </div>`;
  }

  function groupHtml(section, group, groupIndex) {
    const items = group.items.length
      ? group.items
          .map((item, itemIndex) => practiceItemHtml(section, item, groupIndex, itemIndex))
          .join("")
      : fallbackGroupHtml(section, group, groupIndex);
    
    let style = "";
    if (group.title.includes("基础阅读")) {
      style = "background: #F1FBF4; border: 1px solid #CFEEDA; padding: 16px; border-radius: 12px;";
    } else if (group.title.includes("提高阅读")) {
      style = "background: #FFF3E2; border: 1px solid #FDE6C8; padding: 16px; border-radius: 12px;";
    } else {
      style = "background: #F8FAFC; border: 1px solid #E2E8F0; padding: 16px; border-radius: 12px;";
    }
    
    let preamble = group.preambleHtml || "";
    let instruction = "";
    const match = preamble.match(/(<p class="source-line">根据.*?<\/p>)/);
    if (match) {
       instruction = match[1];
       preamble = preamble.replace(match[1], "");
    }
    const passageHighlightKey = highlightKey(section.id, groupIndex);

    return `<section class="exercise-section" style="border-top: 1px solid var(--line); margin-top: 24px; padding-top: 16px;">
      <div class="group-top">
        <div class="group-title" style="font-size: 16px;">${group.title}</div>
        <span class="count-badge">约 ${group.questionCount} 题</span>
      </div>
      <div style="display: flex; gap: 24px; flex-wrap: wrap; align-items: flex-start;">
        ${preamble.trim() ? `<div class="split-left" style="flex: 1; min-width: 300px; position: sticky; top: 110px; max-height: calc(100vh - 130px); overflow-y: auto; scrollbar-width: thin; ${style}">
          <div class="highlight-toolbar">
            <span class="highlight-hint">拖动选择原文，再点高亮；高亮会自动保存</span>
            <button class="highlight-btn" type="button" data-highlight-add="${passageHighlightKey}" disabled>先选择原文</button>
            <button class="highlight-btn highlight-clear-btn" type="button" data-highlight-undo="${passageHighlightKey}">撤销一次</button>
            <button class="highlight-btn highlight-clear-btn" type="button" data-highlight-clear="${passageHighlightKey}">清除本篇</button>
          </div>
          <div class="source-content highlightable-passage" data-highlight-key="${passageHighlightKey}">${preamble}</div>
        </div>` : ""}
        <div class="split-right" style="flex: 1.2; min-width: 350px; background: #fff; max-height: calc(100vh - 130px); overflow-y: auto; scrollbar-width: thin; padding-right: 12px;">
          ${instruction ? `<div class="source-content" style="margin-bottom: 12px; color: var(--ink2); font-weight: 600;">${instruction.replace('<p class="source-line">', '').replace('</p>', '')}</div>` : ""}
          ${items}
        </div>
      </div>
    </section>`;
  }

  
  function toggleStar(secId, key) {
    state.stars[secId] = state.stars[secId] || [];
    const stars = new Set(state.stars[secId]);
    if (stars.has(key)) stars.delete(key);
    else stars.add(key);
    state.stars[secId] = [...stars];
    saveState();
    document.querySelectorAll(`[data-star="${secId}|${key}"]`).forEach(btn => {
      btn.classList.toggle("on", stars.has(key));
    });
    if (curUnit === "stars" && !stars.has(key)) {
      renderStars();
    }
  }

  window.removeVocab = (word) => {
    delete state.vocab[word];
    saveState();
    if (curUnit === 'vocab') renderVocabBook();
  };
  
  window.clearVocab = () => {
    state.vocab = {};
    saveState();
    if (curUnit === 'vocab') renderVocabBook();
  };

  function renderVocabBook() {
    buildNav();
    $("chips").innerHTML = "";
    
    const list = Object.keys(state.vocab).map(word => {
      const v = state.vocab[word];
      return `<div class="exercise-item" style="padding: 16px; border: 1px solid var(--line); border-radius: 12px; margin-bottom: 12px; background: #fff;">
        <div style="display:flex; justify-content:space-between; align-items:center;">
          <div style="font-weight:700; font-size:18px; color:var(--ink);">${escapeHtml(word)}</div>
          <div style="font-size:12px; color:#9AA3B5;">${new Date(v.ts).toLocaleString()}</div>
        </div>
        <div style="margin-top:6px; color:var(--ink2); font-size:15px;">${escapeHtml(v.translation)}</div>
        <div class="group-actions" style="margin-top:12px;">
          <button class="btn" onclick="removeVocab('${escapeHtml(word)}')">🗑️ 移除生词</button>
        </div>
      </div>`;
    }).join("");

    $("main").innerHTML = `
      <div class="card">
        <div class="group-top" style="align-items:center;">
          <h2><span class="em">📖</span>我的生词本 <span class="count-badge">${Object.keys(state.vocab).length} 词</span></h2>
          <div>
             <button class="btn" style="background:#FFEEEE; color:#E02424;" onclick="if(confirm('确定清空所有生词吗？')) { window.clearVocab(); }">清空生词本</button>
          </div>
        </div>
        <div style="margin-top: 20px;">
          ${list || '<p style="color:#9AA3B5; font-size:14px; text-align:center; padding: 40px 0;">双击课文或题目中的英文单词，即可查看中文意思并自动加入生词本哦~</p>'}
        </div>
      </div>
    `;
  }

  function renderStars() {
    buildNav();
    $("chips").innerHTML = "";
    let html = `<div class="card">
        <h2><span class="em">⭐</span>错题本</h2>
        <p class="lead">您收藏的所有错题和难点。</p>
        <div class="exp-row" style="margin:12px 0 10px;"><b>导出</b>
          <label><input type="checkbox" id="optStarsEx" checked> 错题</label>
          <label><input type="checkbox" id="optStarsAns" checked> 答案</label>
        </div>
        <div style="display:flex; gap:10px;">
          <button class="btn p" id="btnExportStars" type="button">⬇️ 导出错题为 Word</button>
          <button class="btn" id="btnResetStars" type="button" style="color:#f57c00; background:#fff3e0;">🔄 重置所有答案</button>
          <button class="btn" id="btnClearStars" type="button" style="color:#d32f2f; background:#ffebee;">🗑️ 清空所有错题</button>
        </div>
      </div>`;
    
    let hasStars = false;
    DATA.forEach(section => {
      const stars = state.stars[section.id] || [];
      if (stars.length === 0) return;
      
      let sectionHtml = `<div class="card"><h3>${section.short} ${section.title}</h3>`;
      let sectionHasItems = false;
      section.exerciseGroups.forEach((group, gIdx) => {
         const starredItems = group.items.filter((item, iIdx) => stars.includes(itemKey(gIdx, iIdx)));
         if (starredItems.length > 0) {
            sectionHasItems = true;
            sectionHtml += `<div class="group-title" style="margin-top:14px;margin-bottom:8px">${group.title}</div>`;
            starredItems.forEach(item => {
               const iIdx = group.items.indexOf(item);
               sectionHtml += practiceItemHtml(section, item, gIdx, iIdx);
            });
         }
      });
      sectionHtml += `</div>`;
      if (sectionHasItems) {
         html += sectionHtml;
         hasStars = true;
      }
    });

    if (!hasStars) {
      html += `<div class="card"><p style="text-align:center;color:#999;padding:40px 0">还没有收藏任何题目哦~</p></div>`;
    }

    $("main").innerHTML = html;
    bindMainEvents();
  }

    function bindMainEvents() {
    const btnResetSection = $("btnResetSection");
    if (btnResetSection) {
       btnResetSection.onclick = () => {
          if (confirm("确定要清空本节所有练习的输入内容和完成状态吗？（错题本收藏不会被清空）")) {
             state.solved[curSec] = [];
             Object.keys(state.work).forEach(key => {
                if (key.startsWith(curSec + "-")) {
                   delete state.work[key];
                }
             });
             saveState();
             render();
          }
       };
    }
    const btnExportStars = $("btnExportStars");
    if (btnExportStars) btnExportStars.onclick = exportStarsDoc;
    
    const btnResetStars = $("btnResetStars");
    if (btnResetStars) btnResetStars.onclick = () => {
       if (confirm("确定要清空错题本中所有题目的输入内容和完成状态吗？（题目仍会保留在错题本中）")) {
          Object.keys(state.stars).forEach(secId => {
             const starKeys = state.stars[secId] || [];
             starKeys.forEach(key => {
                delete state.work[`${secId}-${key}`];
                if (state.solved[secId]) {
                   state.solved[secId] = state.solved[secId].filter(k => k !== key);
                }
             });
          });
          saveState();
          renderStars();
       }
    };

    const btnClearStars = $("btnClearStars");
    if (btnClearStars) btnClearStars.onclick = () => {
       if (confirm("确定要清空所有错题吗？操作不可恢复。")) {
          state.stars = {};
          saveState();
          renderStars();
       }
    };
    $("main")
      .querySelectorAll(".spk")
      .forEach((button) => (button.onclick = () => {} /* TTS removed */));
    $("main")
      .querySelectorAll("[data-mcq]")
      .forEach((button) => (button.onclick = () => pickMcq(button)));
    $("main")
      .querySelectorAll("[data-check]")
      .forEach((button) => (button.onclick = () => checkInput(button.dataset.check)));
    $("main")
      .querySelectorAll("[data-show]")
      .forEach((button) => (button.onclick = () => showInputAnswer(button.dataset.show)));
    $("main")
      .querySelectorAll("[data-manual]")
      .forEach((button) => (button.onclick = () => toggleManual(button.dataset.manual)));
    $("main")
      .querySelectorAll("[data-star]")
      .forEach((button) => (button.onclick = () => {
         const [secId, key] = button.dataset.star.split("|");
         toggleStar(secId, key);
      }));
    $("main")
      .querySelectorAll("[data-highlight-add]")
      .forEach((button) => (button.onclick = () => addPendingHighlight(button.dataset.highlightAdd)));
    $("main")
      .querySelectorAll("[data-highlight-clear]")
      .forEach((button) => (button.onclick = () => clearPassageHighlights(button.dataset.highlightClear)));
    $("main")
      .querySelectorAll("[data-highlight-undo]")
      .forEach((button) => (button.onclick = () => undoLastHighlight(button.dataset.highlightUndo)));
    $("main")
      .querySelectorAll("[data-input]")
      .forEach((input) => {
        input.addEventListener("input", () => {
          if (input.value.length > 0) {
            const firstChar = input.value.charAt(0);
            if (firstChar >= 'a' && firstChar <= 'z') {
              input.value = firstChar.toUpperCase() + input.value.slice(1);
            }
          }
          const [secId, key] = input.dataset.input.split("|");
          state.work[`${secId}-${key}`] = input.value;
          saveState();
        });
        input.addEventListener("keydown", (event) => {
          if (event.key === "Enter") checkInput(input.dataset.input);
        });
      });
    $("main")
      .querySelectorAll("[data-fallback]")
      .forEach((input) => {
        input.addEventListener("input", () => {
          if (input.value.length > 0) {
            const firstChar = input.value.charAt(0);
            if (firstChar >= 'a' && firstChar <= 'z') {
              input.value = firstChar.toUpperCase() + input.value.slice(1);
            }
          }
          const key = input.dataset.fallback;
          state.work[`${curSec}-${key}`] = input.value;
          saveState();
        });
      });
    restoreHighlights();
  }

  function render() {
    buildNav();
    const section = DATA.find((item) => item.id === curSec) || DATA[0];
    curSec = section.id;
    const totalQuestions = section.exerciseGroups.reduce(
      (sum, group) => sum + (group.questionCount || 0),
      0
    );

    $("main").innerHTML = `
      <div class="card">
        <div class="section-kicker">第${String(section.section).padStart(2, "0")}节 · ${section.lessons}</div>
        <h2><span class="em">📖</span>${section.title}</h2>
        <div class="course-meta">
          <span class="meta-pill">全课共 72 节</span>
          <span class="meta-pill">${section.unitName}</span>
          <span class="meta-pill">基础阅读 + 提高阅读</span>
        </div>
        
      </div>

      
      </div>

      <div class="card">
        <div style="display:flex; justify-content:space-between; align-items:flex-start;">
          <h2><span class="em">✏️</span>阅读练习</h2>
          <button class="btn" id="btnResetSection" type="button" style="color:#d32f2f; background:#ffebee;">🔄 重置本节练习</button>
        </div>
        <p class="lead">共 ${section.exerciseGroups.length} 组、约 ${totalQuestions} 题。先在作答区完成，再展开参考答案核对。</p>
        ${section.exerciseGroups.map((group, index) => groupHtml(section, group, index)).join("")}
        <div id="allDone"></div>
      </div>



      <div class="card">
        <h2><span class="em">📄</span>一键导出 Word</h2>
        <p class="lead">生成 .doc 文件，可用 Word 或 WPS 打开并打印。</p>
        <div class="exp-row"><b>范围</b>
          <label><input type="radio" name="scope" value="sec" checked> 本节</label>
          <label><input type="radio" name="scope" value="unit"> 本单元</label>
          <label><input type="radio" name="scope" value="all"> 全部 72 节</label>
        </div>
        <div class="exp-row"><b>内容</b>
          
          
          <label><input type="checkbox" id="optEx" checked> 练习题</label>
          <label><input type="checkbox" id="optAns" checked> 参考答案</label>

        </div>
        <button class="btn p" id="btnExport" type="button">⬇️ 导出 Word 文档</button>
        <div class="tip">制作纯练习卷时，可只保留“练习题”和“参考答案”。</div>
      </div>`;

    bindMainEvents();
    $("btnExport").onclick = exportDoc;
    updateScore(curSec);
  }

  function getItem(secId, key) {
    const [groupIndex, itemIndex] = key.split("-").map(Number);
    const section = DATA.find((item) => item.id === secId);
    return {
      section,
      groupIndex,
      itemIndex,
      item: section.exerciseGroups[groupIndex].items[itemIndex],
    };
  }

  function markSolved(secId, key) {
    const values = solvedSet(secId);
    values.add(key);
    setSolved(secId, values);
    const item = $(`item-${secId}-${key}`);
    if (item) item.classList.add("is-done");
    updateScore(secId);
    if (curUnit !== "stars") updateCurrentChip(secId);
  }

  function updateCurrentChip(secId) {
    const section = DATA.find((item) => item.id === secId);
    if (!section) return;
    const values = solvedSet(secId);
    const chip = $("chips").querySelector(`.chip[data-s="${section.id}"]`);
    if (chip) {
      const complete = values.size >= totalOf(section) && totalOf(section) > 0;
      chip.innerHTML = `${section.short}${complete ? ' <span class="dot">✓</span>' : ""}`;
    }
  }

  function toggleManual(dataset_manual) {
    const [secId, key] = dataset_manual.split("|");
    const values = solvedSet(secId);
    const done = !values.has(key);
    if (done) values.add(key);
    else values.delete(key);
    setSolved(secId, values);
    const item = $(`item-${secId}-${key}`);
    const button = document.querySelector(`[data-manual="${section.id}|${key}"]`);
    if (item) item.classList.toggle("is-done", done);
    if (button) {
      button.classList.toggle("on", done);
      button.textContent = done ? "✓ 已完成本题" : "标记本题完成";
    }
    updateScore(secId);
    if (curUnit !== "stars") updateCurrentChip(secId);
  }

  function feedback(secId, key, correct, html) {
    const panel = $(`feedback-${secId}-${key}`);
    if (!panel) return;
    panel.className = `fb show ${correct ? "good" : "bad"}`;
    panel.innerHTML = html;
  }

  function pickMcq(button) {
    const [secId, key] = button.dataset.mcq.split("|");
    const { item } = getItem(secId, key);
    const picked = Number(button.dataset.option);
    const box = $(`item-${secId}-${key}`);
    const options = box.querySelectorAll(".opt");

    if (item.correct === null) {
      options.forEach((option) => option.classList.remove("on"));
      button.classList.add("on");
      feedback(secId, key, false, "本题源文件未单列答案，请完成后使用“标记本题完成”。");
      return;
    }

    options.forEach((option, index) => {
      option.disabled = true;
      if (index === item.correct) option.classList.add("ok");
      else if (index === picked) option.classList.add("no");
    });
    const correct = picked === item.correct;
    feedback(
      secId,
      key,
      correct,
      correct
        ? "🎉 答对了！"
        : `再看看～ 正确答案是 <span class="ans">${String.fromCharCode(
            65 + item.correct
          )}. ${item.options[item.correct]}</span>`
    );
    if (correct) {
      markSolved(secId, key);
    } else {
      const stars = new Set(state.stars[secId] || []);
      if (!stars.has(key)) toggleStar(secId, key);
    }
  }

  function normalizeAnswer(value) {
    return String(value || "")
      .toLowerCase()
      .replace(/[‘’]/g, "'")
      .replace(/[“”]/g, '"')
      .replace(/[.,!?;:"()，。！？；：]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  function checkInput(dataset_check) {
    const [secId, key] = dataset_check.split("|");
    const { item } = getItem(secId, key);
    const input = $(`input-${secId}-${key}`);
    const value = input ? input.value : "";
    if (!value.trim()) {
      feedback(key, false, "先填写答案再检查哦～");
      return;
    }
    
    // Support multiple answers split by "||"
    const possibleAnswers = item.answer.split("||").map(s => s.trim());
    const normalizedInput = normalizeAnswer(value);
    
    const correct = possibleAnswers.some(ans => normalizeAnswer(ans) === normalizedInput);
    
    // Formatting the correct answers for display
    const answersDisplay = possibleAnswers.map(ans => `<span class="ans">${escapeHtml(ans)}</span>`).join(' 或 ');
    
    feedback(
      secId,
      key,
      correct,
      correct
        ? "🎉 答对了！"
        : `还差一点，参考答案：${answersDisplay}`
    );
    if (correct) {
      markSolved(secId, key);
    } else {
      const stars = new Set(state.stars[secId] || []);
      if (!stars.has(key)) toggleStar(secId, key);
    }
  }

  function showInputAnswer(dataset_show) {
    const [secId, key] = dataset_show.split("|");
    const { item } = getItem(secId, key);
    const possibleAnswers = item.answer.split("||").map(s => s.trim());
    const answersDisplay = possibleAnswers.map(ans => `<span class="ans">${escapeHtml(ans)}</span>`).join(' 或 ');
    feedback(secId, key, false, `参考答案：${answersDisplay}`);
  }

  function updateScore(secId) {
    const section = DATA.find((item) => item.id === secId);
    if (!section) return;
    const count = solvedSet(section.id).size;
    const total = totalOf(section);
    const scoreTxt = $("scoreTxt");
    if (!scoreTxt) return;
    scoreTxt.textContent = `本节练习进度 ${count} / ${total} 组`;
    const scoreBar = $("scoreBar");
    if (scoreBar) scoreBar.style.width = `${total ? Math.round((count / total) * 100) : 0}%`;
    const done = $("allDone");
    if (done) {
      done.innerHTML =
        total && count >= total
          ? '<div class="done">🏆 本节练习全部完成！可以进入下一节。</div>'
          : "";
    }
  }

  const WORD_CSS = `@page{size:A4;margin:2cm 1.8cm}
body{font-family:"Microsoft YaHei","PingFang SC",SimSun,sans-serif;font-size:10.5pt;line-height:1.75;color:#111}
h1{font-size:19pt;text-align:center;margin:0 0 4pt}
.head-sub{text-align:center;color:#666;font-size:9.5pt;margin:0 0 18pt}
h2{font-size:15pt;border-bottom:1.5pt solid #4F7DF3;padding-bottom:3pt;margin:20pt 0 4pt;color:#1F3A93}
h3{font-size:12pt;margin:13pt 0 5pt;color:#B45309}
p{margin:3pt 0}.source-heading{font-size:11.5pt;color:#1F3A93}.english-line{font-family:"Times New Roman",serif}
table{border-collapse:collapse;width:100%;margin:5pt 0;font-size:9.5pt}td,th{border:.5pt solid #999;padding:3pt 5pt}
th{background:#EEF2FB}.lesson-figure img{max-width:100%;height:auto}.spk{display:none}
.answer-block{background:#F1FBF4;padding:7pt;margin:5pt 0}.exercise-block{margin:8pt 0 14pt}.blank-token{border-bottom:.75pt solid #444;color:transparent}`;

  function exportClean(html) {
    return html
      .replace(/<button[\s\S]*?<\/button>/g, "")
      .replace(/\sloading="lazy"/g, "")
      .replace(/<figure class="lesson-figure">/g, "<div class=\"lesson-figure\">")
      .replace(/<\/figure>/g, "</div>");
  }

  
  function exportStarsDoc() {
    const includeEx = $("optStarsEx") ? $("optStarsEx").checked : true;
    const includeAns = $("optStarsAns") ? $("optStarsAns").checked : true;
    
    if (!includeEx && !includeAns) {
       alert("请至少选择一项导出内容！");
       return;
    }

    let body = `<h1>错题本聚合练习卷</h1><p class="head-sub">姓名：__________　日期：__________</p>`;
    
    let hasStars = false;
    let questionsHtmlAll = "";
    let answersHtmlAll = "";

    DATA.forEach(section => {
      const stars = state.stars[section.id] || [];
      if (stars.length === 0) return;
      hasStars = true;
      
      let secQHtml = "";
      let secAHtml = "";

      section.exerciseGroups.forEach((group, gIdx) => {
         const starredItems = group.items.filter((item, iIdx) => stars.includes(itemKey(gIdx, iIdx)));
         if (starredItems.length > 0) {
            secQHtml += `<div class="exercise-block"><b>${group.title}</b>`;
            secAHtml += `<div class="answer-block"><b>${group.title}</b><div style="margin-top: 5px;">`;
            
            starredItems.forEach(item => {
               let qHtml = item.questionHtml.replace(/<\/?p[^>]*>/g, "");
               secQHtml += `<div style="margin: 6pt 0;"><b>${item.number}.</b> ${qHtml}`;
               if (item.type === 'mcq') {
                 secQHtml += `<div style="margin-left: 18pt;">${item.options.map((opt, i) => String.fromCharCode(65+i) + '. ' + opt).join('&nbsp;&nbsp;&nbsp;&nbsp;')}</div>`;
               } else {
                 secQHtml += `<div style="margin-top: 4pt;">_________________________________________</div>`;
               }
               secQHtml += `</div>`;
               
               secAHtml += `<span style="margin-right: 15px;"><b>${item.number}.</b> ${item.answer}</span>`;
            });
            secQHtml += `</div>`;
            secAHtml += `</div></div>`;
         }
      });
      if (secQHtml) {
         if (includeEx) {
             questionsHtmlAll += `<h2>第${str_padStart(String(section.section), 2, "0")}节　${section.title}</h2>${secQHtml}`;
         }
         if (includeAns) {
             answersHtmlAll += `<h3>第${str_padStart(String(section.section), 2, "0")}节　${section.title}</h3>${secAHtml}`;
         }
      }
    });

    if (!hasStars) {
       alert("错题本为空，无法导出！");
       return;
    }

    if (includeEx) {
       body += questionsHtmlAll;
    }
    if (includeAns) {
       if (includeEx) body += '<h2 style="page-break-before:always">参考答案</h2>';
       else body += '<h2>参考答案</h2>';
       body += answersHtmlAll;
    }
    
    const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>${WORD_CSS}</style></head><body>${body}</body></html>`;
    const blob = new Blob(['\ufeff' + html], { type: "application/msword;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `错题本_新概念语法课.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

  function str_padStart(str, len, pad) {
     return String(str).padStart(len, pad);
  }

  function exportDoc() {
    const scope = (document.querySelector('input[name="scope"]:checked') || { value: "sec" })
      .value;
    const include = {
      
      
      exercise: $("optEx").checked,
      answers: $("optAns").checked,
    };
    const current = DATA.find((section) => section.id === curSec);
    let sections;
    let name;
    if (scope === "unit") {
      sections = DATA.filter((section) => section.unit === current.unit);
      name = `72节新概念语法课_${current.unitName.replace(" · ", "_")}`;
    } else if (scope === "all") {
      sections = DATA.slice();
      name = "72节新概念语法课_全册";
    } else {
      sections = [current];
      name = `72节新概念语法课_第${String(current.section).padStart(2, "0")}节_${current.title}`;
    }

    let body = `<h1>${name}</h1><p class="head-sub">新概念英语第一册 · 阅读练习　　姓名：__________　日期：__________</p>`;
    sections.forEach((section) => {
      body += `<h2>第${String(section.section).padStart(2, "0")}节　${section.title}</h2>`;
      body += `<p>${section.lessons}</p>`;
      
      
      if (include.exercise) {
        body += "<h3>阅读练习</h3>";
        section.exerciseGroups.forEach((group) => {
          let questionsHtml = group.preambleHtml || "";
          group.items.forEach(item => {
            let qHtml = item.questionHtml.replace(/<\/?p[^>]*>/g, "");
            questionsHtml += `<div style="margin: 6pt 0;"><b>${item.number}.</b> ${qHtml}`;
            if (item.type === 'mcq') {
              questionsHtml += `<div style="margin-left: 18pt;">${item.options.map((opt, i) => String.fromCharCode(65+i) + '. ' + opt).join('&nbsp;&nbsp;&nbsp;&nbsp;')}</div>`;
            } else {
              questionsHtml += `<div style="margin-top: 4pt;">_________________________________________</div>`;
            }
            questionsHtml += `</div>`;
          });
          body += `<div class="exercise-block"><b>${group.title}</b>${exportClean(
            questionsHtml
          )}</div>`;
        });
      }

    });

    if (include.answers && include.exercise) {
      body += '<h2 style="page-break-before:always">参考答案</h2>';
      sections.forEach((section) => {
        body += `<h3>第${String(section.section).padStart(2, "0")}节　${section.title}</h3>`;
        section.exerciseGroups.forEach((group) => {
          let answersHtml = "";
          group.items.forEach(item => {
            answersHtml += `<span style="margin-right: 15px;"><b>${item.number}.</b> ${item.answer}</span>`;
          });
          body += `<div class="answer-block"><b>${group.title}</b><div style="margin-top: 5px;">${
            answersHtml
              ? exportClean(answersHtml)
              : "<p>源文件未单列本组答案。</p>"
          }</div></div>`;
        });
      });
    }

    const html =
      "﻿<html xmlns:o='urn:schemas-microsoft-com:office:office' " +
      "xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>" +
      `<head><meta charset="utf-8"><title>${name}</title><style>${WORD_CSS}</style></head><body>${body}</body></html>`;
    const blob = new Blob([html], { type: "application/msword;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `${name.replace(/[\\/:*?"<>|]/g, "")}.doc`;
    document.body.appendChild(anchor);
    anchor.click();
    setTimeout(() => {
      URL.revokeObjectURL(url);
      anchor.remove();
    }, 1500);
    const button = $("btnExport");
    const original = button.textContent;
    button.textContent = "✅ 已导出，去下载文件夹查看";
    setTimeout(() => (button.textContent = original), 2600);
  }


  // Translation Popup Logic
  let translationToast = null;
  
  function showTranslationToast(x, y, word, text) {
    if (translationToast) {
      translationToast.remove();
    }
    translationToast = document.createElement("div");
    translationToast.style.position = "absolute";
    translationToast.style.left = x + "px";
    translationToast.style.top = y + "px";
    translationToast.style.background = "#fff";
    translationToast.style.padding = "12px 16px";
    translationToast.style.borderRadius = "12px";
    translationToast.style.boxShadow = "0 8px 24px rgba(0,0,0,0.12)";
    translationToast.style.border = "1px solid #E2E8F0";
    translationToast.style.zIndex = "10000";
    translationToast.style.transform = "translate(-50%, -100%)";
    translationToast.style.marginTop = "-10px";
    translationToast.style.pointerEvents = "auto";
    
    const isAdded = !!state.vocab[word];
    
    translationToast.innerHTML = `
      <div style="font-weight:700; color:var(--blue); font-size:16px;">${escapeHtml(word)}</div>
      <div style="color:var(--ink2); font-size:14px; margin-top:4px; max-width:250px; line-height: 1.4;">${escapeHtml(text)}</div>
      <div style="margin-top:10px;">
        <button id="btn-add-vocab" style="border:none; background:${isAdded ? '#F1FBF4' : '#E0F2FE'}; color:${isAdded ? '#10B981' : 'var(--blue)'}; padding: 6px 12px; border-radius: 6px; font-size:13px; cursor:pointer; font-weight: 500; transition: all 0.2s;">
          ${isAdded ? '✅ 已收录生词本' : '➕ 收录到生词本'}
        </button>
      </div>
    `;
    
    document.body.appendChild(translationToast);
    
    document.getElementById("btn-add-vocab").onclick = (e) => {
       e.stopPropagation();
       if (!state.vocab[word]) {
          state.vocab[word] = { translation: text, ts: Date.now() };
          saveState();
          e.target.innerText = '✅ 已收录生词本';
          e.target.style.background = '#F1FBF4';
          e.target.style.color = '#10B981';
          if (typeof curUnit !== "undefined" && curUnit === "vocab" && typeof renderVocabBook === "function") {
            renderVocabBook();
          }
       }
    };
    
    setTimeout(() => {
      document.addEventListener("click", function closeToast(e) {
        if (translationToast && !translationToast.contains(e.target)) {
          translationToast.remove();
          translationToast = null;
          document.removeEventListener("click", closeToast);
        }
      });
    }, 100);
  }

  document.body.addEventListener("dblclick", async (e) => {
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0) return;
    const text = selection.toString().trim();
    if (!text) return;
    
    // Only accept alphabetic words, allow apostrophe
    if (!/^[a-zA-Z']+$/.test(text)) return;
    
    // Don't translate very short common words
    if (text.length <= 2) return;
    
    const word = text.toLowerCase();
    
    // Calculate position
    const range = selection.getRangeAt(0);
    const rect = range.getBoundingClientRect();
    const x = rect.left + rect.width / 2 + window.scrollX;
    const y = rect.top + window.scrollY;
    
    const callbackName = "jsonp_youdao_" + Date.now() + "_" + Math.floor(Math.random() * 10000);
    window[callbackName] = function(data) {
      delete window[callbackName];
      const scriptElem = document.getElementById(callbackName);
      if (scriptElem) scriptElem.remove();
      
      if (data && data.data && data.data.entries && data.data.entries.length > 0) {
        let trans = data.data.entries[0].explain;
        if (!trans) trans = data.data.entries[0].entry;
        
        showTranslationToast(x, y, word, trans);
      } else {
        showTranslationToast(x, y, word, "未找到释义");
      }
    };
    
    const script = document.createElement("script");
    script.id = callbackName;
    script.src = `https://dict.youdao.com/suggest?num=1&doctype=json&q=${encodeURIComponent(word)}&callback=${callbackName}`;
    document.body.appendChild(script);
  });

  document.body.addEventListener("mouseup", (event) => {
    if (event.target.closest(".highlightable-passage")) {
      window.setTimeout(captureHighlightSelection, 0);
    }
  });

  document.body.addEventListener("touchend", (event) => {
    if (event.target.closest(".highlightable-passage")) {
      window.setTimeout(captureHighlightSelection, 0);
    }
  });

  render();
})();
